        uint256 id;
        uint256 amount;  
        uint8 decimals;

        address pair;
        address token;
        address bribe;

        string symbol;
    }

    struct PairReward {
        address pair;
        Reward[] votingRewards;
    }

    struct LockReward {
        uint256 id;
        uint128 lockedAmount;
        PairReward[] pairRewards;
    }

    uint256 constant public MAX_RESULTS = 1000;
    uint256 constant public MAX_PAIRS = 30;
    uint256 public WEEK; 

    IVoter public voter;
    IGaugeManager public gaugeManager;
    IGaugeFactory public gaugeFactory;
    address public underlyingToken;


    IVotingEscrow public ve;
    IRewardsDistributor public rewardDisitributor;

    address public pairAPI;
    IPairFactory public pairFactory;


    address public owner;
    IAutoVotingEscrowManager public avm;

    event Owner(address oldOwner, address newOwner);

    struct AllPairRewards {
        Reward[] rewards;
    }
    constructor() {}

    function initialize(address _votingEscrow, address _gaugeManager) initializer public {
        owner = msg.sender;
        ve = IVotingEscrow( _votingEscrow );
        gaugeManager = IGaugeManager(_gaugeManager);
        WEEK = BlackTimeLibrary.WEEK;
    }

    function getAllNFT(uint256 _amounts, uint256 _offset) external view returns(veNFT[] memory _veNFT){

        require(_amounts <= MAX_RESULTS, 'TOO_MANY');
        _veNFT = new veNFT[](_amounts);

        uint i = _offset;
        address _owner;

        for(i; i < _offset + _amounts; i++){
            _owner = ve.ownerOf(i);
            // if id_i has owner read data
            if(_owner != address(0)){
                _veNFT[i-_offset] = _getNFTFromId(i, _owner);
            }
        }
    }

    function getNFTFromId(uint256 id) external view returns(veNFT memory){
        return _getNFTFromId(id,ve.ownerOf(id));
    }

    function getNFTFromAddress(address _user) external view returns(veNFT[] memory venft){

        uint256 totNFTs = (_user != address(0)) ? ve.balanceOf(_user) : 0;

        venft = new veNFT[](totNFTs);
        uint256 i=0;
        uint256 _id;

        for(i; i < totNFTs; i++){
            _id = ve.tokenOfOwnerByIndex(_user, i);
            if(_id != 0){
                venft[i] = _getNFTFromId(_id, _user);
            }
        }

        return venft;
    }

        function getAVMNFTFromAddress(address _user) public view returns (veNFT[] memory) {
        IAutoVotingEscrow[] memory avms = avm.getAVMs(); // assuming avms() is a function
        veNFT[] memory temp = new veNFT[](1000) ; // ✅ DECLARATION — fixed-size temporary memory array
        uint count = 0;

        for (uint256 i = 0; i < avms.length; i++) {
            IAutoVotingEscrow.LockInfo[] memory locks = avms[i].getLocks(); // assuming locks() is a function
            for (uint256 j = 0; j < locks.length; j++) {
                IAutoVotingEscrow.LockInfo memory _lock = locks[j];
                if (_lock.owner == _user) {
                    temp[count] = _getNFTFromId(_lock.tokenId, address(avms[i]));
                    count++;
                }
            }
        }

        // Final array trimmed to correct size
        veNFT[] memory venft = new veNFT[](count);
        for (uint256 i = 0; i < count; i++) {
            venft[i] = temp[i];
        }

        return venft;
    }

    function _getNFTFromId(uint256 id, address _owner) internal view returns(veNFT memory venft){

        if(_owner == address(0)){
            return venft;
        }

        // uint _totalPoolVotes = voter.poolVoteLength(id);
        // pairVotes[] memory votes = new pairVotes[](_totalPoolVotes);

        IVotingEscrow.LockedBalance memory _lockedBalance;
        _lockedBalance = ve.locked(id);

        uint k;
        uint256 _poolWeight;
        address _votedPair;

        // for(k = 0; k < _totalPoolVotes; k++){

        //     _votedPair = voter.poolVote(id, k);
        //     if(_votedPair == address(0)){
        //         break;
        //     }
        //     _poolWeight = voter.votes(id, _votedPair);
        //     votes[k].pair = _votedPair;
        //     votes[k].weight = _poolWeight;
        // }

        venft.id = id;
        venft.account = _owner;
        venft.decimals = ve.decimals();
        venft.amount = _lockedBalance.isSMNFT ? uint128(ve.calculate_original_sm_nft_amount(uint256(int256(_lockedBalance.amount)))) : uint128(_lockedBalance.amount); // this is 10% extra for super massive
        venft.voting_amount = ve.balanceOfNFT(id);
        // venft.rebase_amount = rewardDisitributor.claimable(id);
        venft.lockEnd = _lockedBalance.end;
        // venft.vote_ts = voter.lastVotedTimestamp(id);
        // venft.votes = votes;
        venft.token = ve.token();
        venft.tokenSymbol =  IERC20( ve.token() ).symbol();
        venft.tokenDecimals = IERC20( ve.token() ).decimals();
        venft.attachments = ve.attachments(id);
        venft.isSMNFT = _lockedBalance.isSMNFT;
        venft.isPermanent = _lockedBalance.isPermanent;

        venft.voted = ve.voted(id);
        // venft.hasVotedForEpoch = (voter.epochTimestamp() < venft.vote_ts) && (venft.vote_ts < voter.epochTimestamp() + WEEK);
    }

    // used only for sAMM and vAMM    
    // function allPairRewards(uint256 _amount, uint256 _offset, uint256 id) external view returns(AllPairRewards[] memory rewards){

    //     rewards = new AllPairRewards[](MAX_PAIRS);

    //     uint256 totalPairs = pairFactory.allPairsLength();

    //     uint i = _offset;
    //     address _pair;
    //     address _gaugeAddress;
    //     for(i; i < _offset + _amount; i++){
    //         if(i >= totalPairs){
    //             break;
    //         }
    //         _pair = pairFactory.allPairs(i);
    //         _gaugeAddress = IVoter(voter).gauges(_pair);
    //         rewards[i].rewards = _pairReward(_pair, id, _gaugeAddress);
    //     }
    // }

    function getAllPairRewards(address _user, uint _amounts, uint _offset) external view returns(uint totNFTs, bool hasNext, LockReward[] memory _lockReward){

        if(_user == address(0)){

            return (totNFTs, hasNext, _lockReward);
        }

        totNFTs = ve.balanceOf(_user);

        uint length = _amounts < totNFTs ? _amounts : totNFTs;
        _lockReward = new LockReward[](length);

        uint i = _offset;
        uint256 nftId;
        hasNext = true;

        for(i; i < _offset + length; i++){
            if(i >= totNFTs) {
                hasNext = false;
                break;
            }

            nftId = ve.tokenOfOwnerByIndex(_user, i);

            _lockReward[i-_offset].id = nftId;
            _lockReward[i-_offset].lockedAmount = uint128(ve.locked(nftId).amount);
            _lockReward[i-_offset].pairRewards = _getRewardsForNft(nftId);
        }
    }  

    function _getRewardsForNft(uint nftId) internal view returns (PairReward[] memory pairReward) {
        uint gaugesLength = gaugeFactory.length();
        uint maxPairRewardCount = 0;
        PairReward[] memory _pairRewards = new PairReward[](gaugesLength);

        for(uint i=0; i<gaugesLength; i++){
            address poolAddress = IGaugeManager(gaugeManager).poolForGauge(gaugeFactory.gauges(i));
            (Reward[] memory _rewardData, bool hasReward) = _pairReward(poolAddress, nftId, gaugeFactory.gauges(i));
            if(hasReward)
            {
                _pairRewards[maxPairRewardCount].pair = poolAddress;
                _pairRewards[maxPairRewardCount].votingRewards = _rewardData;
                maxPairRewardCount++;
            }
        }

        pairReward = new PairReward[](maxPairRewardCount);

        for(uint i=0; i<maxPairRewardCount; i++){
            pairReward[i].pair = _pairRewards[i].pair;
            pairReward[i].votingRewards = _pairRewards[i].votingRewards;
        }
    }

    function _pairReward(address _pair, uint256 id,  address _gauge) internal view returns (Reward[] memory _reward, bool) {

        if (_gauge == address(0)) {
            return (_reward, false);
        }

        address external_bribe = gaugeManager.external_bribes(_gauge);
        address internal_bribe = gaugeManager.internal_bribes(_gauge);

        uint256 totBribeTokens = (external_bribe == address(0)) ? 0 : IBribeAPI(external_bribe).rewardsListLength();
        _reward = new Reward[](2 + totBribeTokens);

        // Fetch pair contract once
        IPair ipair = IPair(_pair);
        (address t0, address t1) = (ipair.token0(), ipair.token1());

        InternalBribeInputs memory internal_bribes_input = InternalBribeInputs({
            id: id,
            t0: t0,
            t1: t1,
            bribe_address: internal_bribe,
            pair: _pair
        });

        ExternalBribeInputs memory external_bribes_input = ExternalBribeInputs({
            id: id,
            bribe_address: external_bribe,
            tokens: totBribeTokens,
            pair: _pair
        });

        // Fetch earned fees
        bool internalRewards = _addInternalBribeRewards(_reward, internal_bribes_input);
        bool externalRewards = _addExternalBribeRewards(_reward, external_bribes_input);

        return (_reward, internalRewards || externalRewards);
    }

    function _addInternalBribeRewards(Reward[] memory _reward, InternalBribeInputs memory internal_bribes_inputs) internal view returns (bool) {
        uint256 _feeToken0 = IBribeAPI(internal_bribes_inputs.bribe_address).earned(internal_bribes_inputs.id, internal_bribes_inputs.t0);
        uint256 _feeToken1 = IBribeAPI(internal_bribes_inputs.bribe_address).earned(internal_bribes_inputs.id, internal_bribes_inputs.t1);
        bool hasReward = false;
        if (_feeToken0 > 0) {
            _reward[0] = _createReward(internal_bribes_inputs.id, _feeToken0, internal_bribes_inputs.t0, internal_bribes_inputs.bribe_address, internal_bribes_inputs.pair);
            hasReward = true;
        }
        if (_feeToken1 > 0) {
            _reward[1] = _createReward(internal_bribes_inputs.id, _feeToken1, internal_bribes_inputs.t1, internal_bribes_inputs.bribe_address, internal_bribes_inputs.pair);
            hasReward = true;
        }

        return hasReward;
    }

    function _addExternalBribeRewards(Reward[] memory _reward, ExternalBribeInputs memory external_bribes_input) internal view returns (bool) {
        bool hasReward = false;
        for (uint256 k = 0; k < external_bribes_input.tokens; k++) {
            address _token = IBribeAPI(external_bribes_input.bribe_address).bribeTokens(k);
            uint256 bribeAmount = IBribeAPI(external_bribes_input.bribe_address).earned(external_bribes_input.id, _token);
            if(bribeAmount > 0){
                hasReward = true;
                _reward[2 + k] = _createReward(external_bribes_input.id, bribeAmount, _token, external_bribes_input.bribe_address, external_bribes_input.pair);
            }
        }

        return hasReward;
    }

    function _createReward(uint256 id, uint256 amount, address token, address bribe, address _pair) internal view returns (Reward memory) {
        return Reward({
            id: id,
            pair: _pair,
            amount: amount,
            token: token,
            symbol: IERC20(token).symbol(),
            decimals: IERC20(token).decimals(),
            bribe: bribe
        });
    }


    function setOwner(address _owner) external {
        require(msg.sender == owner, 'NA');
        require(_owner != address(0), 'ZA');
        owner = _owner;
        emit Owner(msg.sender, _owner);
    }


    function setVoter(address _voter) external  {
        require(msg.sender == owner);

        voter = IVoter(_voter);
    }

    function setAVM(address _avm) external {
        require(msg.sender == owner && _avm!=address(0));
        avm = IAutoVotingEscrowManager(_avm);
    }

    function setGaugeManager(address _gaugeManager) external  {
        require(msg.sender == owner);

        gaugeManager = IGaugeManager(_gaugeManager);
    }

    function setGaugeFactory(address _gaugeFactory) external  {
        require(msg.sender == owner);

        gaugeFactory = IGaugeFactory(_gaugeFactory);
    }


    function setRewardDistro(address _rewarddistro) external {
        require(msg.sender == owner);

        rewardDisitributor = IRewardsDistributor(_rewarddistro);
        require(rewardDisitributor.voting_escrow() == voter._ve(), 've!=ve');

        ve = IVotingEscrow( rewardDisitributor.voting_escrow() );
        underlyingToken = IVotingEscrow(ve).token();
    }

    function setPairAPI(address _pairApi) external {
        require(msg.sender == owner);

        pairAPI = _pairApi;
    }


    function setPairFactory(address _pairFactory) external {
        require(msg.sender == owner);  
        pairFactory = IPairFactory(_pairFactory);
    }

}
"},"contracts/APIHelper/veNFTAPIV1.sol":{"content":"// SPDX-License-Identifier: MIT OR GPL-3.0-or-later
pragma solidity 0.8.13;


import '../libraries/Math.sol';
import '../interfaces/IBribeAPI.sol';
import '../interfaces/IERC20.sol';
import '../interfaces/IPair.sol';
import '../interfaces/IPairFactory.sol';
import '../interfaces/IVoter.sol';
import '../interfaces/IGaugeManager.sol';
import '../interfaces/IVotingEscrow.sol';
import '../interfaces/IRewardsDistributor.sol';
import '../interfaces/IGaugeFactory.sol';
import '../interfaces/IGaugeFactoryCL.sol';


import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "../AVM/interfaces/IAutoVotingEscrowManager.sol";
import {BlackTimeLibrary} from "../libraries/BlackTimeLibrary.sol";

import "hardhat/console.sol";

interface IPairAPI {
    struct Bribes {
        address bribeAddress;
        address[] tokens;
        string[] symbols;
        uint[] decimals;
        uint[] amounts;
    }

    struct Rewards {
        Bribes[] bribes;
    }

    function pair_factory() external view returns(address);
}

contract veNFTAPIV1 is Initializable {

    struct LockInfo {
        address owner;
        uint256 tokenId;
    }

    struct pairVotes {
        address pair;
        uint256 weight;
    }

    struct InternalBribeInputs {
        uint id;
        address bribe_address;
        address t0;
        address t1;
        address pair;
    }

    struct ExternalBribeInputs {
        uint id;
        address bribe_address;
        uint tokens;
        address pair;
    }

    struct veNFT {
        uint8 decimals;

        bool voted;
        bool hasVotedForEpoch;
        uint256 attachments;

        uint256 id;
        uint128 amount;
        uint256 voting_amount;
        uint256 rebase_amount;
        uint256 lockEnd;
        uint256 vote_ts;
        pairVotes[] votes;        

        address account;

        bool isSMNFT;
        bool isPermanent;

        address token;
        string tokenSymbol;
        uint256 tokenDecimals;
    }

    struct Reward {

        uint256 id;
        uint256 amount;  
        uint8 decimals;

        address pair;
        address token;
        address bribe;

        string symbol;
    }

    struct PairReward {
        address pair;
        Reward[] votingRewards;
    }

    struct LockReward {
        uint256 id;
        uint128 lockedAmount;
        PairReward[] pairRewards;
    }

    uint256 constant public MAX_RESULTS = 1000;
    uint256 constant public MAX_PAIRS = 30;
    uint256 public WEEK; 

    IVoter public voter;
    IGaugeManager public gaugeManager;
    IGaugeFactory public gaugeFactory;
    IGaugeFactoryCL public gaugeFactoryCL;
    address public underlyingToken;


    IVotingEscrow public ve;
    IRewardsDistributor public rewardDisitributor;

    address public pairAPI;
    IPairFactory public pairFactory;


    address public owner;
    IAutoVotingEscrowManager public avm;
    event Owner(address oldOwner, address newOwner);

    struct AllPairRewards {
        Reward[] rewards;
    }
    constructor() {}

    function initialize(address _voter, address _rewarddistro, address _gaugeFactory, address _gaugeFactoryCL, address _gaugeManager) initializer public {
        owner = msg.sender;
        voter = IVoter(_voter);
        rewardDisitributor = IRewardsDistributor(_rewarddistro);
        gaugeFactory = IGaugeFactory(_gaugeFactory);
        gaugeManager = IGaugeManager(_gaugeManager);
        gaugeFactoryCL = IGaugeFactoryCL(_gaugeFactoryCL);

        require(rewardDisitributor.voting_escrow() == voter._ve(), 've!=ve');

        ve = IVotingEscrow( rewardDisitributor.voting_escrow() );
        underlyingToken = IVotingEscrow(ve).token();

        WEEK = BlackTimeLibrary.WEEK;
    }

    function getAllNFT(uint256 _amounts, uint256 _offset) external view returns(veNFT[] memory _veNFT){

        require(_amounts <= MAX_RESULTS, 'TOO_MANY');
        _veNFT = new veNFT[](_amounts);

        uint i = _offset;
        address _owner;

        for(i; i < _offset + _amounts; i++){
            _owner = ve.ownerOf(i);
            // if id_i has owner read data
            if(_owner != address(0)){
                _veNFT[i-_offset] = _getNFTFromId(i, _owner);
            }
        }
    }

    function getNFTFromId(uint256 id) external view returns(veNFT memory){
        return _getNFTFromId(id,ve.ownerOf(id));
    }

    function getNFTFromAddress(address _user) external view returns(veNFT[] memory venft){

        uint256 totNFTs = (_user != address(0)) ? ve.balanceOf(_user) : 0;

        venft = new veNFT[](totNFTs);
        uint256 i=0;
        uint256 _id;

        for(i; i < totNFTs; i++){
            _id = ve.tokenOfOwnerByIndex(_user, i);
            if(_id != 0){
                venft[i] = _getNFTFromId(_id, _user);
            }
        }

        return venft;
    }

    function getAVMNFTFromAddress(address _user) public view returns (veNFT[] memory) {
        IAutoVotingEscrow[] memory avms = avm.getAVMs(); // assuming avms() is a function
        veNFT[] memory temp = new veNFT[](1000) ; // ✅ DECLARATION — fixed-size temporary memory array
        uint count = 0;

        for (uint256 i = 0; i < avms.length; i++) {
            IAutoVotingEscrow.LockInfo[] memory locks = avms[i].getLocks(); // assuming locks() is a function
            for (uint256 j = 0; j < locks.length; j++) {
                IAutoVotingEscrow.LockInfo memory _lock = locks[j];
                if (_lock.owner == _user) {
                    temp[count] = _getNFTFromId(_lock.tokenId, address(avms[i]));
                    count++;
                }
            }
        }

        // Final array trimmed to correct size
        veNFT[] memory venft = new veNFT[](count);
        for (uint256 i = 0; i < count; i++) {
            venft[i] = temp[i];
        }

        return venft;
    }

    function _getNFTFromId(uint256 id, address _owner) internal view returns(veNFT memory venft){

        if(_owner == address(0)){
            return venft;
        }

        uint _totalPoolVotes = voter.poolVoteLength(id);
        pairVotes[] memory votes = new pairVotes[](_totalPoolVotes);

        IVotingEscrow.LockedBalance memory _lockedBalance;
        _lockedBalance = ve.locked(id);

        uint k;
        uint256 _poolWeight;
        address _votedPair;

        for(k = 0; k < _totalPoolVotes; k++){

            _votedPair = voter.poolVote(id, k);
            if(_votedPair == address(0)){
                break;
            }
            _poolWeight = voter.votes(id, _votedPair);
            votes[k].pair = _votedPair;
            votes[k].weight = _poolWeight;
        }

        venft.id = id;
        venft.account = _owner;
        venft.decimals = ve.decimals();
        venft.amount = _lockedBalance.isSMNFT ? uint128(ve.calculate_original_sm_nft_amount(uint256(int256(_lockedBalance.amount)))) : uint128(_lockedBalance.amount); // this is 10% extra for super massive
        venft.voting_amount = ve.balanceOfNFT(id);
        venft.rebase_amount = rewardDisitributor.claimable(id);
        venft.lockEnd = _lockedBalance.end;
        venft.vote_ts = voter.lastVotedTimestamp(id);
        venft.votes = votes;
        venft.token = ve.token();
        venft.tokenSymbol =  IERC20( ve.token() ).symbol();
        venft.tokenDecimals = IERC20( ve.token() ).decimals();
        venft.attachments = ve.attachments(id);
        venft.isSMNFT = _lockedBalance.isSMNFT;
        venft.isPermanent = _lockedBalance.isPermanent;

        venft.voted = ve.voted(id);
        venft.hasVotedForEpoch = (BlackTimeLibrary.epochStart(block.timestamp) < venft.vote_ts) && (venft.vote_ts < BlackTimeLibrary.epochNext(block.timestamp));
    }

    // used only for sAMM and vAMM    
    // function allPairRewards(uint256 _amount, uint256 _offset, uint256 id) external view returns(AllPairRewards[] memory rewards){

    //     rewards = new AllPairRewards[](MAX_PAIRS);

    //     uint256 totalPairs = pairFactory.allPairsLength();

    //     uint i = _offset;
    //     address _pair;
    //     address _gaugeAddress;
    //     for(i; i < _offset + _amount; i++){
    //         if(i >= totalPairs){
    //             break;
    //         }
    //         _pair = pairFactory.allPairs(i);
    //         _gaugeAddress = IVoter(voter).gauges(_pair);
    //         rewards[i].rewards = _pairReward(_pair, id, _gaugeAddress);
    //     }
    // }

    function getAllPairRewards(address _user, uint _amounts, uint _offset) external view returns(uint totNFTs, bool hasNext, LockReward[] memory _lockReward){

        if(_user == address(0)){

            return (totNFTs, hasNext, _lockReward);
        }
        veNFT[] memory avmNFTsOfUser = getAVMNFTFromAddress(_user);

        totNFTs = ve.balanceOf(_user);

        uint length = _amounts < (totNFTs + avmNFTsOfUser.length) ? _amounts : (totNFTs + avmNFTsOfUser.length); 
        _lockReward = new LockReward[](length);


        // int length = avmNFTsOfUser.length;

        uint i = _offset;
        uint256 nftId;
        hasNext = true;

        for(i; i < _offset + _amounts; i++){ // need to be amounts right
            if(i >= (totNFTs + avmNFTsOfUser.length)) {
                hasNext = false;
                break;
            }
            if(i < totNFTs) {
                nftId = ve.tokenOfOwnerByIndex(_user, i);
            } else {
                uint avmIndex = i - totNFTs;
                nftId = avmNFTsOfUser[avmIndex].id;
            }

            _lockReward[i-_offset].id = nftId;
            _lockReward[i-_offset].lockedAmount = uint128(ve.locked(nftId).amount);
            _lockReward[i-_offset].pairRewards = _getRewardsForNft(nftId);
        }

        totNFTs += avmNFTsOfUser.length;
    }  

    function _getRewardsForNft(uint nftId) internal view returns (PairReward[] memory pairReward) {
        uint basicPoolGaugeLength = gaugeFactory.length();
        uint clPoolGaugeLength = gaugeFactoryCL.length();
        uint maxPairRewardCount = 0;
        PairReward[] memory _pairRewards = new PairReward[](basicPoolGaugeLength + clPoolGaugeLength);
        Reward[] memory _rewardData; 
        bool hasReward;
        address poolAddress;

        for(uint i=0; i<basicPoolGaugeLength + clPoolGaugeLength; i++){
            if(i >= basicPoolGaugeLength){
                poolAddress = IGaugeManager(gaugeManager).poolForGauge(gaugeFactoryCL.gauges(i-basicPoolGaugeLength));
                (_rewardData, hasReward) = _pairReward(poolAddress, nftId, gaugeFactoryCL.gauges(i-basicPoolGaugeLength));
            }
            else{
                poolAddress = IGaugeManager(gaugeManager).poolForGauge(gaugeFactory.gauges(i));
                (_rewardData, hasReward) = _pairReward(poolAddress, nftId, gaugeFactory.gauges(i));
            }

            if(hasReward)
            {
                _pairRewards[maxPairRewardCount].pair = poolAddress;
                _pairRewards[maxPairRewardCount].votingRewards = _rewardData;
                maxPairRewardCount++;
            }
        }

        pairReward = new PairReward[](maxPairRewardCount);

        for(uint i=0; i<maxPairRewardCount; i++){
            pairReward[i].pair = _pairRewards[i].pair;
            pairReward[i].votingRewards = _pairRewards[i].votingRewards;
        }
    }

    function _pairReward(address _pair, uint256 id,  address _gauge) internal view returns (Reward[] memory _reward, bool) {

        if (_gauge == address(0)) {
            return (_reward, false);
        }

        address external_bribe = gaugeManager.external_bribes(_gauge);
        address internal_bribe = gaugeManager.internal_bribes(_gauge);

        uint256 totBribeTokens = (external_bribe == address(0)) ? 0 : IBribeAPI(external_bribe).rewardsListLength();
        _reward = new Reward[](2 + totBribeTokens);

        // Fetch pair contract once
        IPair ipair = IPair(_pair);
        (address t0, address t1) = (ipair.token0(), ipair.token1());

        InternalBribeInputs memory internal_bribes_input = InternalBribeInputs({
            id: id,
            t0: t0,
            t1: t1,
            bribe_address: internal_bribe,
            pair: _pair
        });

        ExternalBribeInputs memory external_bribes_input = ExternalBribeInputs({
            id: id,
            bribe_address: external_bribe,
            tokens: totBribeTokens,
            pair: _pair
        });

        // Fetch earned fees
        bool internalRewards = _addInternalBribeRewards(_reward, internal_bribes_input);
        bool externalRewards = _addExternalBribeRewards(_reward, external_bribes_input);

        return (_reward, internalRewards || externalRewards);
    }

    function _addInternalBribeRewards(Reward[] memory _reward, InternalBribeInputs memory internal_bribes_inputs) internal view returns (bool) {
        uint256 _feeToken0 = IBribeAPI(internal_bribes_inputs.bribe_address).earned(internal_bribes_inputs.id, internal_bribes_inputs.t0);
        uint256 _feeToken1 = IBribeAPI(internal_bribes_inputs.bribe_address).earned(internal_bribes_inputs.id, internal_bribes_inputs.t1);
        bool hasReward = false;
        if (_feeToken0 > 0) {
            _reward[0] = _createReward(internal_bribes_inputs.id, _feeToken0, internal_bribes_inputs.t0, internal_bribes_inputs.bribe_address, internal_bribes_inputs.pair);
            hasReward = true;
        }
        if (_feeToken1 > 0) {
            _reward[1] = _createReward(internal_bribes_inputs.id, _feeToken1, internal_bribes_inputs.t1, internal_bribes_inputs.bribe_address, internal_bribes_inputs.pair);
            hasReward = true;
        }

        return hasReward;
    }

    function _addExternalBribeRewards(Reward[] memory _reward, ExternalBribeInputs memory external_bribes_input) internal view returns (bool) {
        bool hasReward = false;
        for (uint256 k = 0; k < external_bribes_input.tokens; k++) {
            address _token = IBribeAPI(external_bribes_input.bribe_address).bribeTokens(k);
            uint256 bribeAmount = IBribeAPI(external_bribes_input.bribe_address).earned(external_bribes_input.id, _token);
            if(bribeAmount > 0){
                hasReward = true;
                _reward[2 + k] = _createReward(external_bribes_input.id, bribeAmount, _token, external_bribes_input.bribe_address, external_bribes_input.pair);
            }
        }

        return hasReward;
    }

    function _createReward(uint256 id, uint256 amount, address token, address bribe, address _pair) internal view returns (Reward memory) {
        return Reward({
            id: id,
            pair: _pair,
            amount: amount,
            token: token,
            symbol: IERC20(token).symbol(),
            decimals: IERC20(token).decimals(),
            bribe: bribe
        });
    }


    function setOwner(address _owner) external {
        require(msg.sender == owner, 'NA');
        require(_owner != address(0), 'ZA');
        owner = _owner;
        emit Owner(msg.sender, _owner);
    }


    function setVoter(address _voter) external  {
        require(msg.sender == owner);

        voter = IVoter(_voter);
    }

    function setAVM(address _avm) external {
        require(msg.sender == owner && _avm!=address(0));
        avm = IAutoVotingEscrowManager(_avm);
    }

    function setGaugeManager(address _gaugeManager) external  {
        require(msg.sender == owner);
        gaugeManager = IGaugeManager(_gaugeManager);
    }

    function setGaugeFactory(address _gaugeFactory) external  {
        require(msg.sender == owner);
        gaugeFactory = IGaugeFactory(_gaugeFactory);
    }

    function setGaugeFactoryCL(address _gaugeFactoryCL) external  {
        require(msg.sender == owner);
        gaugeFactoryCL = IGaugeFactoryCL(_gaugeFactoryCL);
    }


    function setRewardDistro(address _rewarddistro) external {
        require(msg.sender == owner);

        rewardDisitributor = IRewardsDistributor(_rewarddistro);
        require(rewardDisitributor.voting_escrow() == voter._ve(), 've!=ve');

        ve = IVotingEscrow( rewardDisitributor.voting_escrow() );
        underlyingToken = IVotingEscrow(ve).token();
    }

    function setPairAPI(address _pairApi) external {
        require(msg.sender == owner);

        pairAPI = _pairApi;
    }


    function setPairFactory(address _pairFactory) external {
        require(msg.sender == owner);  
        pairFactory = IPairFactory(_pairFactory);
    }

}

"},"contracts/AVM/AutoVotingEscrow.sol":{"content":"// SPDX-License-Identifier: GPL-3.0-or-later
pragma solidity ^0.8.13;

import "../interfaces/IVotingEscrow.sol";
import "./interfaces/IAutoVotingEscrow.sol";
import "../interfaces/IRewardsDistributor.sol";
import "./interfaces/IAutoVotingEscrowManager.sol";
import {BlackTimeLibrary} from "../libraries/BlackTimeLibrary.sol";
import "../interfaces/IVoter.sol";

interface IERC20 {
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract AutoVotingEscrow is IAutoVotingEscrow {
    address public manager;
    uint256 public constant MAX_LOCKS = 1024;
    address public voter;

    address public votingEscrow;
    LockInfo[] public locks;
    address public rewardsDistributor;
    mapping(uint256 => uint256) public tokenIdIndex; // tokenId => index in `locks`

    modifier onlyManager() {
        require(msg.sender == manager, "Only manager");
        _;
    }

    constructor(address _manager, address _voter, address _votingEscrow, address _rewardsDistributor) {
        manager = _manager;
        voter = _voter;
        rewardsDistributor = _rewardsDistributor;
        votingEscrow = _votingEscrow;
    }

    function acceptLock(address _owner, uint256 _tokenId) external onlyManager {
        require(locks.length < MAX_LOCKS, "AVM full");
        tokenIdIndex[_tokenId] = locks.length;
        locks.push(LockInfo({ owner: _owner, tokenId: _tokenId }));
    }

    function releaseLock(uint256 _tokenId) external onlyManager {
        require(!BlackTimeLibrary.isLastHour(block.timestamp), "Cannot disable in last hour before voting");

        uint256 index = tokenIdIndex[_tokenId];
        uint256 lastIndex = locks.length - 1;

        if (index != lastIndex) {
            LockInfo memory lastLock = locks[lastIndex];
            locks[index] = lastLock;
            tokenIdIndex[lastLock.tokenId] = index;
        }

        locks.pop();
        delete tokenIdIndex[_tokenId];

        IVotingEscrow(votingEscrow).approve(msg.sender, _tokenId);
    }

    function lockOwner(uint256 _tokenId) external view override returns (address) {
        uint256 index = tokenIdIndex[_tokenId];
        require(index < locks.length, "Token not found");
        return locks[index].owner;
    }

    function isFull() external view override returns (bool) {
        return locks.length >= MAX_LOCKS;
    }

    function getLockCount() external view override returns (uint256) {
        return locks.length;
    }

    function voteLocks(uint256 start, uint256 length) external override onlyManager {
        require(start + length <= locks.length, "Out of bounds");
        address[] memory pools = IAutoVotingEscrowManager(manager).getTopPools();
        uint[] memory weights = IAutoVotingEscrowManager(manager).getVoteWeights();

        for (uint256 i = start; i < start + length; i++) {
            IVotingEscrow.LockedBalance memory _locked = IVotingEscrow(votingEscrow).locked(locks[i].tokenId);
            if (_locked.end > block.timestamp || _locked.isPermanent) {
                _vote(locks[i].tokenId, pools, weights);
            }
        }
    }

    function resetLocks(uint256 start, uint256 length) external override onlyManager {
        require(start + length <= locks.length, "Out of bounds");

        for (uint256 i = start; i < start + length; i++) {
            IVotingEscrow.LockedBalance memory _locked = IVotingEscrow(votingEscrow).locked(locks[i].tokenId);
            if (_locked.end > block.timestamp || _locked.isPermanent) {
                _reset(locks[i].tokenId);
            }
        }
    }

    function _vote(uint256 tokenId, address[] memory pools, uint[] memory weights) internal {
        IRewardsDistributor(rewardsDistributor).claim(tokenId);
        IVoter(voter).vote(tokenId, pools, weights);
    }

    function _reset(uint256 tokenId) internal {
        IVoter(voter).reset(tokenId);
    }

    function getTotalVotingPower() external view returns (uint256) {
        uint256 votingBalance = 0;
        uint locksLen = locks.length;
        for(uint i=0; i<locksLen; i++) {
            votingBalance += IVotingEscrow(votingEscrow).balanceOfNFT(locks[i].tokenId);
        }
        return votingBalance;
    }

    function getLocks() external view returns (LockInfo[] memory) {
        return locks;
    }

}
"},"contracts/AVM/AutoVotingEscrowManager.sol":{"content":"// SPDX-License-Identifier: GPL-3.0-or-later
pragma solidity ^0.8.13;

import "./AutoVotingEscrow.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "../interfaces/IVotingEscrow.sol";
import "./interfaces/IAutoVotingEscrow.sol";
import "../interfaces/ITopNPoolsStrategy.sol";
import "../interfaces/IVoteWeightStrategy.sol";
import "../interfaces/IVoter.sol";
import "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import {IAutoVotingEscrowManager} from "./interfaces/IAutoVotingEscrowManager.sol";

// change name of contract
contract AutoVotingEscrowManager is IAutoVotingEscrowManager, Initializable, OwnableUpgradeable, ReentrancyGuardUpgradeable  {
    ITopNPoolsStrategy public topPoolsStrategy;
    IVoteWeightStrategy public voteWeightStrategy;

    IVotingEscrow public votingEscrow;
    address public voter;
    uint256 public topN;

    uint256 public constant MAX_TOP_N = 100; // can be changed but has to be assigned on the instantiation

    mapping(uint256 => uint256) public tokenIdToAVMId;
    mapping(uint256 => address) public originalOwner;
    IAutoVotingEscrow[] public avms;

    uint256 public nextAvailableAVMIndex;
    address public rewardsDistributor;
    uint public minBalanceForAutovoting;
    address public executor;

    modifier validAVMIndex(uint256 index) {
        require(index < avms.length, "Invalid AVM index");
        _;
    }

    modifier onlyVotingEscrow {
        require(msg.sender == address(votingEscrow), '!VE');
        _;
    }

    modifier onlyExecutor() {
        require(msg.sender == executor, "Only executor");
        _;
    }

    uint256 public MAX_LOCKS;

    function initialize(address _votingEscrow, address _voter, address _rewardsDistributor) public initializer {
        __Ownable_init();
        __ReentrancyGuard_init();
        votingEscrow = IVotingEscrow(_votingEscrow);
        voter = _voter;
        executor = msg.sender;
        minBalanceForAutovoting = 100_000*1e18; // decimals in black
        rewardsDistributor = _rewardsDistributor;
        _transferOwnership(msg.sender);
        MAX_LOCKS = 200;
    }

    function enableAutoVoting(uint256 tokenId) external {
        require(votingEscrow.isApprovedOrOwner(msg.sender, tokenId), "NAO");
        require(!BlackTimeLibrary.isLastHour(block.timestamp), "LH");

        // Extract locked balance into separate variable
        IVotingEscrow.LockedBalance memory lockedBalance = votingEscrow.locked(tokenId);
        uint256 lockedAmount = uint256(int256(lockedBalance.amount));

        // Check minimum balance requirement
        require(lockedAmount >= minBalanceForAutovoting, "IB");

        // Check that the token is not an SMNFT
        require(lockedBalance.isSMNFT, "only_SMNFT");

        uint avmsLength = avms.length;
        // Search for a non-full AVM using while loop
        IAutoVotingEscrow target;
        while (nextAvailableAVMIndex < avmsLength) {
            if (!isFull(avms[nextAvailableAVMIndex])) {
                target = avms[nextAvailableAVMIndex];
                break;
            }
            nextAvailableAVMIndex++;
        }

        // If none found, create a new AVM
        if (address(target) == address(0)) {
            AutoVotingEscrow newAVM = new AutoVotingEscrow(address(this), voter, address(votingEscrow), rewardsDistributor);
            target = IAutoVotingEscrow(address(newAVM));
            avms.push(target);
        }

        votingEscrow.transferFrom(msg.sender, address(target), tokenId);
        target.acceptLock(msg.sender, tokenId); // insert to token Ids here
        tokenIdToAVMId[tokenId] = nextAvailableAVMIndex + 1;
    }

    function disableAutoVoting(uint256 tokenId) external {
        uint256 avmIdxOneBased = tokenIdToAVMId[tokenId];
        require(avmIdxOneBased > 0 && avmIdxOneBased - 1 < avms.length, "out of range"); // is this necessary
        require(!BlackTimeLibrary.isLastHour(block.timestamp), "LH");
        IAutoVotingEscrow avm = avms[avmIdxOneBased - 1];
        require(avm.lockOwner(tokenId) == msg.sender, "Not owner");

        // Release lock
        avm.releaseLock(tokenId); // replace with last element and pop here 
        IVoter(voter).reset(tokenId); // wrote it here as the autovoting escrow itself isnt upgradeable
        votingEscrow.transferFrom(address(avm), msg.sender, tokenId);

        delete tokenIdToAVMId[tokenId];

        // If AVM became non-full, track it
        if ((!isFull(avm)) && (avmIdxOneBased - 1 < nextAvailableAVMIndex)) {
            nextAvailableAVMIndex = avmIdxOneBased - 1;
        }
    }
    // instead of avm addresses how about avm indexes
    function getAVMIndex(address avmAddr) internal view returns (uint256) {
        uint avmsLength = avms.length;
        for (uint256 i = 0; i < avmsLength; i++) {
            if (address(avms[i]) == avmAddr) {
                return i;
            }
        }
        revert("AVM not found");
    }

    function performLockAction(
        uint256 avmIndex,
        uint256 localStart,
        uint256 localEnd,
        bool isVote
    ) external onlyExecutor {
        require(avmIndex < avms.length, "Invalid AVM index");
        require(localEnd > localStart, "Invalid range");
        require(!isVote || BlackTimeLibrary.isLastHour(block.timestamp), "!LH");

        uint256 avmLockCount = avms[avmIndex].getLockCount();
        require(localEnd <= avmLockCount, "End exceeds available locks");

        if (isVote) {
            avms[avmIndex].voteLocks(localStart, localEnd - localStart);
        } else {
            avms[avmIndex].resetLocks(localStart, localEnd - localStart);
        }
    }

    function getAVMs() external view returns (IAutoVotingEscrow[] memory) {
        return avms;
    }

    function setVoter(address _voter) external onlyOwner {
        require(_voter != address(0), "ZA");
        voter = _voter;
        return;
    }

    function setExecutor(address _executor) external {
        require(msg.sender == executor || msg.sender == owner(), "NA");
        require(_executor != address(0), "ZA");
        executor = _executor;
    }

    function setTopPoolsStrategy(address strategy) external onlyOwner {
        require(strategy != address(0), "ZA");
        topPoolsStrategy = ITopNPoolsStrategy(strategy);
    }

    function setVoteWeightStrategy(address strategy) external onlyOwner {
        require(strategy != address(0), "ZA");
        voteWeightStrategy = IVoteWeightStrategy(strategy);
    }

    function getTopPools() external view returns (address[] memory) {
        require(address(topPoolsStrategy) != address(0), "ZA");
        address[] memory pools = topPoolsStrategy.getTopNPools();
        return pools;
    }

    function getVoteWeights() external view returns (uint256[] memory) {
        require(address(voteWeightStrategy) != address(0), "ZA");
        return voteWeightStrategy.getVoteWeights(); // need to change interface
    }

    function getTotalVotingPower() external view returns (uint256) {
        uint256 totalVotingPower = 0;
        uint avmsLength = avms.length;
        for(uint i=0; i<avmsLength; i++) {
            totalVotingPower+=avms[i].getTotalVotingPower();
        }
        return totalVotingPower;
    }

    function setTopN(uint256 _topN) public onlyOwner {
        require(_topN > 0 && _topN < MAX_TOP_N, "OUT_RANG");
        topN = _topN;
        if(address(topPoolsStrategy) != address(0)) {
            topPoolsStrategy.setTopN();
        }

        if(address(voteWeightStrategy) != address(0)) {
            voteWeightStrategy.setTopN();
        }
    }

    function setOriginalOwner(uint256 _tokenId, address _user) external onlyVotingEscrow {} // implement this

    function getOriginalOwner(uint256 _tokenId) external view returns (address) {
        uint256 avmIdxOneBased = tokenIdToAVMId[_tokenId];
        require(avmIdxOneBased > 0 && avmIdxOneBased - 1 < avms.length, "OUT_RANG");

        IAutoVotingEscrow avm = avms[avmIdxOneBased - 1];
        return avm.lockOwner(_tokenId);
    }

    function setMinBalanceForAutovoting(uint _minBalance) external onlyOwner {
        minBalanceForAutovoting = _minBalance;
    }

    function isFull(IAutoVotingEscrow _avm) internal view returns (bool) {
        uint lockCount = _avm.getLockCount();
        return lockCount >= MAX_LOCKS;
    }

    function setMaxLockCount(uint _maxLockCount) external onlyOwner {
        MAX_LOCKS = _maxLockCount;
    }

}
"},"contracts/AVM/interfaces/IAutoVotingEscrow.sol":{"content":"// SPDX-License-Identifier: GPL-3.0-or-later
pragma solidity ^0.8.13;

interface IAutoVotingEscrow {
    struct LockInfo {
        address owner;
        uint256 tokenId;
    }

    function acceptLock(address user, uint256 tokenId) external;
    function releaseLock(uint256 tokenId) external;
    function isFull() external view returns (bool);
    function lockOwner(uint256 tokenId) external view returns (address);
    function getLockCount() external view returns (uint256);
    function voteLocks (uint start, uint end) external;
    function resetLocks(uint start, uint end) external;
    function getTotalVotingPower() external view returns (uint256);
    function getLocks() external view returns (LockInfo[] memory);
}
"},"contracts/AVM/interfaces/IAutoVotingEscrowManager.sol":{"content":"// SPDX-License-Identifier: GPL-3.0-or-later
pragma solidity ^0.8.13;

import "./IAutoVotingEscrow.sol";

interface IAutoVotingEscrowManager {
    function getTopPools() external view returns (address[] memory);
    function getVoteWeights() external view returns (uint[] memory);
    function topN() external view returns(uint256);
    function getTotalVotingPower() external view returns (uint256 _totalAVMVotingPower);
    function executor() external view returns (address);
    function getAVMs() external view returns (IAutoVotingEscrow[] memory);
