// Black Hole Foundation 2025

pragma solidity 0.8.13;

import {IERC20} from "./interfaces/IERC20.sol";
import {IBlackClaims} from "./interfaces/IBlackClaims.sol";
import {IVotingEscrow} from "./interfaces/IVotingEscrow.sol";
import {BlackTimeLibrary} from "./libraries/BlackTimeLibrary.sol";

/// @title Manager for the seasonal player rewards program.
/// @author Chance Santana-Wees (Coelacanth/Coel.eth)
/// @custom:modified-by Mitesh
/// @dev Season rewards pulled from a treasury contract that must have a token allowance set for this contract.
/// @notice Allows System Admins to set up and report scores for Seasons.
contract BlackClaims is IBlackClaims {

    uint256 public MAX_PERIOD;

    ///@notice The address of the rewards token. (The BLACK token)
    IERC20 immutable token;

    ///@notice The traeasury from which Seasons pull their reward tokens.
    address treasury;

    address public owner;
    address public secondOwner;
    modifier onlyOwner {
        require(msg.sender == owner || msg.sender == secondOwner, 'not owner');
        _;
    }

    /// @notice The metagame staking pool
    IVotingEscrow public _ve;

    ///@notice A claim season period.
    IBlackClaims.Season public season;

    ///@notice A mapping of scores reported for each user by address.
    mapping(address => uint256) public season_rewards;

    ///@notice A mapping of quantity of tokens claimed for each user by address.
    mapping(address => uint256) public claimed_rewards;

    event TreasurySet(address treasury);
    event StakedRewards(address staker, uint256 rewards);

    ///@param treasury_ The address of the account/contract that the Seasons reward system pulls reward tokens from.
    /// @param __ve Address of the ve(3,3) system that will be locked into
    constructor(
        address treasury_,
        address __ve) 
    {
        owner = msg.sender;
        treasury = treasury_;
        _ve = IVotingEscrow(__ve);
        token = IERC20(_ve.token());
        MAX_PERIOD = BlackTimeLibrary.MAX_LOCK_DURATION;
    }

    ///@notice Updates the address of the account/contract that the Seasons reward system pulls reward tokens from.
    ///@dev Only callable by Global Admins.
    ///@param treasury_ The address of the new treasury.
    function setTreasury(address treasury_) external onlyOwner {
        treasury = treasury_;
        emit TreasurySet(treasury_);
    }

    ///@notice Initializes a new Season of the rewards program.
    ///@dev Only callable by Systems Admins. It is permissable to create Seasons with overlapping times.
    ///@param start_time_ The start time of the new season.
    ///@return season_ IBlackClaims.Season The Season struct that was initialized.
    function startSeason(
        uint256 start_time_
    ) external onlyOwner returns(IBlackClaims.Season memory season_)
    {
        require(start_time_ > 0, "CANNOT START AT 0");
        require(season.start_time==0, "SEASON ALREADY STARTED");
        season_.start_time = start_time_;
        season = season_;
    }

    ///@notice Queries the finalized status of a season.
    ///@dev A season is finalized if its claim time is set.
    ///@return _finalized bool The finalized status of the provided season.
    function isSeasonFinalized() public view returns(bool _finalized) 
    {
        _finalized = season.claim_end_time > 0;
    }

    ///@notice Queries if a season has been finalized and can have rewards claimed from it.
    ///@return _active bool True if the season has ended at the provided timestamp
    function isSeasonClaimingActive() public view returns(bool _active) 
    {
        _active = isSeasonFinalized() && season.claim_end_time >= block.timestamp;
    }

    ///@notice Queries if a season has been finalized and the claim period has already elapsed.
    ///@return _ended bool True if the season's rewards claim period has elapsed.
    function isSeasonClaimingEnded() public view returns(bool _ended) 
    {
        _ended = isSeasonFinalized() && season.claim_end_time < block.timestamp;
    }

    ///@notice Revokes unclaimed reward tokens into the treasury.
    ///@dev Callable only by Systems Admins and only after the season's claim period has elapsed.
    function revokeUnclaimedReward() external onlyOwner
    {
        Season storage _season = season;
        uint256 _remaining_reward_amount = _season.remaining_reward_amount;
        require(_season.start_time > 0, "SEASON NOT FOUND");
        require(isSeasonClaimingEnded(), "SEASON_CLAIM_NOT_ENDED");
        require(_remaining_reward_amount > 0, "ZERO_REMAINING_AMOUNT");

        bool transfer_success = token.transfer(treasury, _remaining_reward_amount);
        require(transfer_success, "FAILED TRANSFER");
        _season.remaining_reward_amount -= uint128(_remaining_reward_amount);
    }

    ///@notice Finalizes a season, setting its rewards quantity and claim period.
    ///@dev Callable only by Systems Admins and only after the season has been ended by calling the endSeason(...) function.
    ///@param claim_duration_ The duration of the claim period.
    function finalize(
        uint256 claim_duration_
    ) external onlyOwner
    {
        Season storage _season = season;
        require(_season.start_time > 0, "SEASON NOT FOUND");
        require(!isSeasonFinalized(), "SEASON_FINALIZED");
        require(_season.reward_amount>0, "NO REWARD AMOUNT");
        require(claim_duration_ >= 1 days && claim_duration_ < 1000 days, "CLAIM DURATION OUT OF BOUNDS");

        bool transfer_success = token.transferFrom(treasury, address(this), _season.reward_amount);
        require(transfer_success, "FAILED TRANSFER");

        _season.remaining_reward_amount = _season.reward_amount;
        _season.claim_end_time = block.timestamp + claim_duration_;
    }

    ///@notice Extends a season claim end time, setting its rewards quantity and claim period.
    function extendClaimDuration(
        uint256 claim_duration_
    ) external onlyOwner
    {
        Season storage _season = season;
        require(_season.start_time > 0, "SEASON NOT FOUND");
        require(isSeasonFinalized(), "SEASON_NOT_FINALIZED");
        require(_season.reward_amount>0, "NO REWARD AMOUNT");
        _season.claim_end_time = _season.claim_end_time + claim_duration_;
    }

    ///@notice Reports an list of players' scores for the specified season.
    ///@dev Callable only by Systems Admins.
    ///@param players_ The list of player addresses.
    ///@param rewards_ The list of player's total current rewards.
    function reportRewards(
        address[] calldata players_,
        uint256[] calldata rewards_
    ) external onlyOwner
    {
        require(players_.length == rewards_.length, "ARRAYS  MISMATCH");

        Season storage _season = season;
        require(_season.start_time > 0, "SEASON NOT FOUND");
        require(!isSeasonFinalized(), "SEASON FINALIZED");

        uint256 _increase = 0;
        uint256 _decrease = 0;

        for (uint256 i = 0; i < players_.length; i++) {
            _increase += rewards_[i];
            _decrease += season_rewards[players_[i]];
            season_rewards[players_[i]] = rewards_[i];
        }

        _season.reward_amount += _increase;
        _season.reward_amount -= _decrease;
    }

    ///@notice Claim tokens rewarded to msg.sender in the specified season. Must have a verified Access Pass.
    ///@dev Callable only on seasons which have been finalized and whose claim duration has not elapsed.
    function _preClaim() internal 
        returns (uint256)
    {
        require(claimed_rewards[msg.sender] == 0, "REWARD CLAIMED");

        Season storage _season = season;
        require(isSeasonClaimingActive(), "SEASON_CLAIM_ENDED");

        uint256 _reward = season_rewards[msg.sender];
        require(_reward > 0, "MUST HAVE A NON ZERO REWARD");

        _season.remaining_reward_amount -= _reward;
        claimed_rewards[msg.sender] = _reward;

        return _reward;
    }

    ///@notice Stake tokens claimed.
    ///@dev Callable only on seasons which have been finalized and whose claim duration has not elapsed.
    function claimAndStakeReward(uint percent) external returns (uint)
    {
        require(percent>=50&&percent<=100, "Percent out of bounds");
        uint256 _reward = _preClaim();
        uint256 staked_reward = 0;
        Season storage _season = season;

        if(percent == 100) {
            staked_reward = _reward;
        } else {
            uint256 credit_amount = (_reward * 100)/110;
            uint256 forfeit_amount = _reward - credit_amount;

            _season.remaining_reward_amount += forfeit_amount;

            staked_reward = (credit_amount * percent)/100;
            uint256 claimed_reward = credit_amount - staked_reward;
            bool transfer_success = token.transfer(msg.sender, claimed_reward);
            require(transfer_success, "FAILED TRANSFER");
        }
        token.approve(address(_ve), staked_reward);
        uint _tokenId = _ve.create_lock_for(staked_reward, MAX_PERIOD, msg.sender, true);
        emit StakedRewards(msg.sender, staked_reward);
        return _tokenId;
    }

    ///@notice get reward tokens claimable by a player in the specified season.
    function getClaimableReward(address userAddress) public view returns(uint256 _reward) 
    {

        _reward = season_rewards[userAddress] - claimed_rewards[userAddress];
        if( !isSeasonClaimingActive() )
        {
            _reward = 0;
        }
    }

    /// @notice Transfer tokens that have been sent to this contract by mistake.
    /// @dev Only callable by address with Global Admin permissions. Cannot be called to withdraw emissions tokens.
    /// @param tokenAddress_ The address of the token to recover
    function recoverERC20(address tokenAddress_) external onlyOwner {
        require(tokenAddress_ != address(0));
        uint _balance = IERC20(tokenAddress_).balanceOf(address(this));
        IERC20(tokenAddress_).transfer(msg.sender, _balance);
    }

    function setOwner(address _owner) external onlyOwner {
        require(_owner != address(0));
        owner = _owner;
    }
    function setOwner2(address _owner) external onlyOwner {
        require(_owner != address(0));
        secondOwner = _owner;
    }
}"},"contracts/BlackGovernor.sol":{"content":"// SPDX-License-Identifier: MIT OR GPL-3.0-or-later
pragma solidity 0.8.13;

import {IGovernor} from "./governance/IGovernor.sol";
import {IBlackHoleVotes} from "./interfaces/IBlackHoleVotes.sol";
import {L2Governor, L2GovernorCountingSimple, L2GovernorVotes, L2GovernorVotesQuorumFraction} from "./governance/Governor.sol";
import {IMinter} from "./interfaces/IMinter.sol";
import {BlackTimeLibrary} from "./libraries/BlackTimeLibrary.sol";

contract BlackGovernor is
    L2Governor,
    L2GovernorCountingSimple,
    L2GovernorVotes,
    L2GovernorVotesQuorumFraction
{
    address public team;
    uint256 public constant MAX_PROPOSAL_NUMERATOR = 100; // max 10%
    uint256 public constant PROPOSAL_DENOMINATOR = 1000;
    uint256 private VOTING_DELAY = 3600;
    uint256 public proposalNumerator = 2; // start at 0.02%
    address public minter;

    constructor(
        IBlackHoleVotes _ve,
        address _minter
    )
        L2Governor("Black Governor")
        L2GovernorVotes(_ve)
        L2GovernorVotesQuorumFraction(4) // 4%
    {
        minter = _minter;
        team = msg.sender;
    }

    function votingDelay() public view override(IGovernor) returns (uint256) {
        return VOTING_DELAY; // 1 block
    }

    function votingPeriod() public view override(IGovernor) returns (uint256) {
        return BlackTimeLibrary.epochVoteEnd(block.timestamp);
    }

    function setTeam(address newTeam) external {
        require(msg.sender == team, "not team");
        team = newTeam;
    }

    function setVotingDelay(uint256 delay) external {
        require(msg.sender == team, "not team");
        VOTING_DELAY = delay;
    }

    function setProposalNumerator(uint256 numerator) external {
        require(msg.sender == team, "not team");
        require(numerator <= MAX_PROPOSAL_NUMERATOR, "numerator too high");
        proposalNumerator = numerator;
    }

    function proposalThreshold()
        public
        view
        override(L2Governor)
        returns (uint256)
    {
        uint totalSMNftVote = token.getsmNFTPastTotalSupply();
        uint totalSMNftVotePlusBonus = totalSMNftVote + token.calculate_sm_nft_bonus(totalSMNftVote);
        return
            ( totalSMNftVotePlusBonus * proposalNumerator) /
            PROPOSAL_DENOMINATOR;
    }

    function clock() public view override returns (uint48) {}

    function CLOCK_MODE() public view override returns (string memory) {}

    function cancel(
        address[] memory targets,
        uint256[] memory values,
        bytes[] memory calldatas,
        bytes32 epochTimeHash
    ) public virtual override returns (uint256 proposalId) {
        address proposer = msg.sender;
        uint256 _proposalId = hashProposal(
            targets,
            values,
            calldatas,
            epochTimeHash
        );
        require(
            state(_proposalId) == ProposalState.Pending,
            "Governor: too late to cancel"
        );
        require(
            proposer == _proposals[_proposalId].proposer,
            "Governor: only proposer can cancel"
        );
        return _cancel(targets, values, calldatas, epochTimeHash);
    }

    function quorum(uint256 blockTimestamp) public view override (L2GovernorVotesQuorumFraction, IGovernor) returns (uint256) {
        uint totalSMNftVote = token.getsmNFTPastTotalSupply();
        uint totalSMNftVotePlusBonus = totalSMNftVote + token.calculate_sm_nft_bonus(totalSMNftVote);
        return (totalSMNftVotePlusBonus * quorumNumerator()) / quorumDenominator();
    }

    function propose(
        uint256 tokenId,
        address[] memory targets,
        uint256[] memory values,
        bytes[] memory calldatas,
        string memory description
    ) public virtual override returns (uint256) {

        require(targets.length == 1, "GovernorSimple: only one target allowed");
        require(address(targets[0]) == minter, "GovernorSimple: only minter allowed");
        require(calldatas.length == 1, "GovernorSimple: only one calldata allowed");
        require(bytes4(calldatas[0]) == IMinter.nudge.selector, "GovernorSimple: only nudge allowed");
        return _proposal(tokenId, targets, values, calldatas, description);
    }

}
"},"contracts/Bribes.sol":{"content":"// SPDX-License-Identifier: MIT OR GPL-3.0-or-later
pragma solidity 0.8.13;

import "./interfaces/IMinter.sol";
import "./interfaces/IVoter.sol";
import "./interfaces/IGaugeManager.sol";
import "./interfaces/IVotingEscrow.sol";
import "./interfaces/ITokenHandler.sol";
import {IAutomatedVotingManager} from "./interfaces/IAutomatedVotingManager.sol";
import {IAutoVotingEscrowManager} from "./AVM/interfaces/IAutoVotingEscrowManager.sol";
import {IAutoVotingEscrow} from "./AVM/interfaces/IAutoVotingEscrow.sol";
import {BlackTimeLibrary} from "./libraries/BlackTimeLibrary.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";


contract Bribe is ReentrancyGuard {
    using SafeERC20 for IERC20;
    uint256 public WEEK; 

    /* ========== STATE VARIABLES ========== */

    struct VotingRewardsPlot {
        uint128 balanceOf;
        uint32 timestamp;
    }

    struct VotingSupplyPlot {
        uint128 supply;
        uint32 timestamp;
    }

    mapping(address => mapping(uint256 => uint256)) public tokenRewardsPerEpoch;
    address public voter;
    address public gaugeManager;
    address public immutable bribeFactory;
    address public minter;
    address public immutable ve;
    address public owner;
    address public avm; // does it need to be immutable?
    ITokenHandler public tokenHandler;

    string public TYPE;

    uint256 public totalSupply;
    mapping(uint256 => uint256) public balanceOf;

    mapping(address => mapping(uint256 => uint256)) public lastEarn;

    mapping(uint256 => mapping(uint256 => VotingRewardsPlot)) public votingRewardsPlots;
    mapping(uint256 => uint256) public numVotingRewardsPlots;

    mapping(uint256 => VotingSupplyPlot) public votingSupplyPlots;
    uint256 public numVotingSupplyPlots;

    mapping(address => bool) internal isBribeToken;
    address[] public bribeTokens;


    /* ========== CONSTRUCTOR ========== */

    constructor(address _owner,address _voter,address _gaugeManager, address _bribeFactory, address _tokenHandler, address _token0, address _token1, string memory _type)  {
        require(_bribeFactory != address(0) && _voter != address(0) && _gaugeManager != address(0) && _owner != address(0), "ZA");
        WEEK = BlackTimeLibrary.WEEK;
        voter = _voter;
        gaugeManager = _gaugeManager;
        bribeFactory = _bribeFactory;
        tokenHandler = ITokenHandler(_tokenHandler);
        ve = IVoter(_voter)._ve();
        minter = IGaugeManager(_gaugeManager).minter();
        avm = IVotingEscrow(ve).avm();
        require(minter != address(0), "ZA");
        owner = _owner;
        TYPE = _type;

        bribeTokens.push(_token0);
        bribeTokens.push(_token1);
        isBribeToken[_token0] = true;
        isBribeToken[_token1] = true;
    }

    function getEpochStart() public view returns(uint256){
        return IMinter(minter).active_period();
    }

    /// @notice get next epoch (where bribes are saved)
    function getNextEpochStart() public view returns(uint256){
        return BlackTimeLibrary.epochNext(block.timestamp);
    }

    /* ========== VIEWS ========== */

    /// @notice get the length of the reward tokens
    function rewardsListLength() external view returns(uint256) {
        return bribeTokens.length;
    }

    /// @notice Read earned amount given a tokenID and _rewardToken
    function earned(uint256 tokenId, address _rewardToken) public view returns(uint256){
        if (numVotingRewardsPlots[tokenId] == 0) {
            return 0;
        }

        uint256 reward = 0;
        uint256 _supply = 1;
        uint256 _currTs = BlackTimeLibrary.epochStart(lastEarn[_rewardToken][tokenId]); // take epoch last claimed in as starting point
        uint256 _index = getPriorVotingRewardsIndex(tokenId, _currTs);
        VotingRewardsPlot memory cp0 = votingRewardsPlots[tokenId][_index];


        _currTs = Math.max(_currTs, BlackTimeLibrary.epochStart(cp0.timestamp));

        uint256 numEpochs = (BlackTimeLibrary.epochStart(block.timestamp) - _currTs) / WEEK;

        if (numEpochs > 0) {
            for (uint256 i = 0; i < numEpochs; i++) {
                _index = getPriorVotingRewardsIndex(tokenId, _currTs + WEEK - 1);
                cp0 = votingRewardsPlots[tokenId][_index];
                _supply = Math.max(votingSupplyPlots[getPriorVotingSupplyIndex(_currTs + WEEK - 1)].supply, 1);
                reward += (cp0.balanceOf * tokenRewardsPerEpoch[_rewardToken][_currTs]) / _supply;
                _currTs += WEEK;
            }
        } 
        return reward;  
    }


    function getPriorVotingRewardsIndex(uint256 tokenId, uint256 timestamp) public view returns (uint256) {
        uint256 nPlots = numVotingRewardsPlots[tokenId];
        if (nPlots == 0) {
            return 0;
        }
        if (votingRewardsPlots[tokenId][nPlots - 1].timestamp <= timestamp) {
            return (nPlots - 1);
        }
        if (votingRewardsPlots[tokenId][0].timestamp > timestamp) {
            return 0;
        }

        uint256 lower = 0;
        uint256 upper = nPlots - 1;
        while (upper > lower) {
            uint256 center = upper - (upper - lower) / 2;
            VotingRewardsPlot memory plot = votingRewardsPlots[tokenId][center];
            if (plot.timestamp == timestamp) {
                return center;
            } else if (plot.timestamp < timestamp) {
                lower = center;
            } else {
                upper = center - 1;
            }
        }
        return lower;
    }

    function getPriorVotingSupplyIndex(uint256 timestamp) public view returns (uint256) {
        uint256 nPlots = numVotingSupplyPlots;
        if (nPlots == 0) {
            return 0;
        }

        if (votingSupplyPlots[nPlots - 1].timestamp <= timestamp) {
            return nPlots - 1;
        }

        if (votingSupplyPlots[0].timestamp > timestamp) {
            return 0;
        }

        uint256 lower = 0;
        uint256 upper = nPlots - 1;
        while (upper > lower) {
            uint256 center = upper - (upper - lower) / 2;
            VotingSupplyPlot memory plot = votingSupplyPlots[center];
            if (plot.timestamp == timestamp) return center;
            else if (plot.timestamp < timestamp) {
                lower = center;
            } else {
                upper = center - 1;
            }
        }
        return lower;
    }

    function isRewardToken(address _rewardToken) external view returns (bool) {
        return _isRewardToken(_rewardToken);
    }

    function _isRewardToken(address _rewardToken) internal view returns (bool) {
        return isBribeToken[_rewardToken] || tokenHandler.isConnector(_rewardToken);
    }

    /* ========== MUTATIVE FUNCTIONS ========== */

    /// @notice User votes deposit
    /// @dev    called on voter.vote() or voter.poke()
    ///         we save into owner "address" and not "tokenID". 
    ///         Owner must reset before transferring token
    function deposit(uint256 amount, uint256 tokenId) external nonReentrant {
        require(amount > 0, "ZV");
        require(msg.sender == voter, "NA");
        totalSupply = totalSupply + amount;
        balanceOf[tokenId] = balanceOf[tokenId] + amount;

        _writeVotingRewardsPlot(tokenId, balanceOf[tokenId]);
        _writeVotingSupplyPlot();

        emit Staked(tokenId, amount);
    }

    function _writeVotingRewardsPlot(uint256 tokenId, uint256 balance) internal {
        uint256 nPlots = numVotingRewardsPlots[tokenId];
        uint32 ts = uint32(block.timestamp);

        if (
            nPlots > 0 &&
            BlackTimeLibrary.epochStart(votingRewardsPlots[tokenId][nPlots - 1].timestamp) ==
            BlackTimeLibrary.epochStart(ts)
        ) {
            votingRewardsPlots[tokenId][nPlots - 1] = VotingRewardsPlot(uint128(balance), ts);
        } else {
            votingRewardsPlots[tokenId][nPlots] = VotingRewardsPlot(uint128(balance), ts);
            numVotingRewardsPlots[tokenId] = nPlots + 1;
        }
    }

    function _writeVotingSupplyPlot() internal {
        uint256 nPlots = numVotingSupplyPlots;
        uint32 ts = uint32(block.timestamp);

        if (
            nPlots > 0 &&
            BlackTimeLibrary.epochStart(votingSupplyPlots[nPlots - 1].timestamp) ==
            BlackTimeLibrary.epochStart(ts)
        ) {
            votingSupplyPlots[nPlots - 1] = VotingSupplyPlot(uint128(totalSupply), ts);
        } else {
            votingSupplyPlots[nPlots] = VotingSupplyPlot(uint128(totalSupply), ts);
            numVotingSupplyPlots = nPlots + 1;
        }
    }

    /// @notice User votes withdrawal 
    /// @dev    called on voter.reset()
    function withdraw(uint256 amount, uint256 tokenId) external nonReentrant {
        require(amount > 0, "ZV");
        require(msg.sender == voter, "NA");
        if (amount <= balanceOf[tokenId]) {
            totalSupply -= amount;
            balanceOf[tokenId] -= amount;

            _writeVotingRewardsPlot(tokenId, balanceOf[tokenId]);
            _writeVotingSupplyPlot();
            emit Withdrawn(tokenId, amount);
        }
    }

    /// @notice Claim the TOKENID rewards
    function getReward(uint256 tokenId, address[] memory tokens) external nonReentrant  {
        address _owner = IVotingEscrow(ve).ownerOf(tokenId);
        if(_isAValidAutoVotingEscrow(_owner)) {
            _owner = IAutoVotingEscrowManager(avm).getOriginalOwner(tokenId);
        }
        require(msg.sender == gaugeManager, "NA");
        uint256 _length = tokens.length;
        for (uint256 i = 0; i < _length; i++) {
            uint256 _reward = earned(tokenId, tokens[i]);
            lastEarn[tokens[i]][tokenId] = block.timestamp;
            if (_reward > 0) {
                IERC20(tokens[i]).safeTransfer(_owner, _reward);
            }
        }
    }

    function _isAValidAutoVotingEscrow(address _addr) public view returns (bool) {
        IAutoVotingEscrow[] memory avmList = IAutoVotingEscrowManager(avm).getAVMs();
        for (uint i = 0; i < avmList.length; i++) {
            if (address(avmList[i]) == _addr) return true;
        }
        return false;
    }
    /// @dev Rewards are saved into Current EPOCH mapping. 
    function notifyRewardAmount(address _rewardsToken, uint256 reward) external nonReentrant {
        require(_isRewardToken(_rewardsToken), "!VERIFIED");

        if(!isBribeToken[_rewardsToken]){
            isBribeToken[_rewardsToken] = true;
            bribeTokens.push(_rewardsToken);
        }

        IERC20(_rewardsToken).safeTransferFrom(msg.sender,address(this),reward);
        uint256 epochStart = BlackTimeLibrary.epochStart(block.timestamp);
        tokenRewardsPerEpoch[_rewardsToken][epochStart] += reward;
        emit RewardAdded(_rewardsToken, reward, epochStart);
    }

    /* ========== RESTRICTED FUNCTIONS ========== */

    /// @notice Recover some ERC20 from the contract and updated given bribe
    function recoverERC20AndUpdateData(address tokenAddress, uint256 tokenAmount) external onlyAllowed {
        require(tokenAmount <= IERC20(tokenAddress).balanceOf(address(this)), "TOO_MUCH");

        uint256 _startTimestamp = IMinter(minter).active_period();
        uint256 _lastReward = tokenRewardsPerEpoch[tokenAddress][_startTimestamp];
        tokenRewardsPerEpoch[tokenAddress][_startTimestamp] = _lastReward - tokenAmount;
        IERC20(tokenAddress).safeTransfer(owner, tokenAmount);
        emit Recovered(tokenAddress, tokenAmount);
    }

    /// @notice Recover some ERC20 from the contract.
    /// @dev    Be careful --> if called then getReward() at last epoch will fail because some reward are missing! 
    ///         Think about calling recoverERC20AndUpdateData()
    function emergencyRecoverERC20(address tokenAddress, uint256 tokenAmount) external onlyAllowed {
        require(tokenAmount <= IERC20(tokenAddress).balanceOf(address(this)), "TOO_MUCH");
        IERC20(tokenAddress).safeTransfer(owner, tokenAmount);
        emit Recovered(tokenAddress, tokenAmount);
    }

    /// @notice Set a new voter
    function setVoter(address _Voter) external onlyAllowed {
        require(_Voter != address(0), "ZA");
        voter = _Voter;
    }

    /// @notice Set a new gaugeManager
    function setGaugeManager(address _gaugeManager) external onlyAllowed {
        require(_gaugeManager != address(0));
        gaugeManager = _gaugeManager;
    }

    /// @notice Set a new minter
    function setMinter(address _minter) external onlyAllowed {
        require(_minter != address(0), "ZA");
        minter = _minter;
    }

    /// @notice Set a new AVM 
    function setAVM(address _avm) external onlyAllowed {
        require(_avm!=address(0), "ZA");
        avm = _avm;
    }

    /// @notice Set a new Owner
    event SetOwner(address indexed _owner);
    function setOwner(address _owner) external onlyAllowed {
        require(_owner != address(0), "ZA");
        owner = _owner;
        emit SetOwner(_owner);
    }


    /* ========== MODIFIERS ========== */

    modifier onlyAllowed() {
        require( (msg.sender == owner || msg.sender == bribeFactory), "NA" );
        _;
    }


    /* ========== EVENTS ========== */

    event RewardAdded(address indexed rewardToken, uint256 reward, uint256 startTimestamp);
    event Staked(uint256 indexed tokenId, uint256 amount);
    event Withdrawn(uint256 indexed tokenId, uint256 amount);
    event RewardPaid(address indexed user,address indexed rewardsToken,uint256 reward);
    event Recovered(address indexed token, uint256 amount);
}
"},"contracts/chainlink/AutomationBase.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract AutomationBase {
  error OnlySimulatedBackend();

  /**
   * @notice method that allows it to be simulated via eth_call by checking that
   * the sender is the zero address.
   */
  function preventExecution() internal view {
    if (tx.origin != address(0)) {
      revert OnlySimulatedBackend();
    }
  }

  /**
   * @notice modifier that allows it to be simulated via eth_call by checking
   * that the sender is the zero address.
   */
  modifier cannotExecute() {
    preventExecution();
    _;
  }
}"},"contracts/chainlink/AutomationCompatible.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "./AutomationBase.sol";
import "./AutomationCompatibleInterface.sol";

abstract contract AutomationCompatible is AutomationBase, AutomationCompatibleInterface {}"},"contracts/chainlink/AutomationCompatibleInterface.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

interface AutomationCompatibleInterface {
  /**
   * @notice method that is simulated by the keepers to see if any work actually
   * needs to be performed. This method does does not actually need to be
   * executable, and since it is only ever simulated it can consume lots of gas.
   * @dev To ensure that it is never called, you may want to add the
   * cannotExecute modifier from KeeperBase to your implementation of this
   * method.
   * @param checkData specified in the upkeep registration so it is always the
   * same for a registered upkeep. This can easily be broken down into specific
   * arguments using `abi.decode`, so multiple upkeeps can be registered on the
   * same contract and easily differentiated by the contract.
   * @return upkeepNeeded boolean to indicate whether the keeper should call
   * performUpkeep or not.
   * @return performData bytes that the keeper should call performUpkeep with, if
   * upkeep is needed. If you would like to encode data to decode later, try
   * `abi.encode`.
   */
  function checkUpkeep(bytes calldata checkData) external returns (bool upkeepNeeded, bytes memory performData);
  function checkUpPrekeep(bytes calldata checkData) external returns (bool preUpkeepNeeded, bytes memory performData);

  /**
   * @notice method that is actually executed by the keepers, via the registry.
   * The data returned by the checkUpkeep simulation will be passed into
   * this method to actually be executed.
   * @dev The input to this method should not be trusted, and the caller of the
   * method should not even be restricted to any single registry. Anyone should
   * be able call it, and the input should be validated, there is no guarantee
   * that the data passed in is the performData returned from checkUpkeep. This
   * could happen due to malicious keepers, racing keepers, or simply a state
   * change while the performUpkeep transaction is waiting for confirmation.
   * Always validate the data passed in.
   * @param performData is the data which was passed back from the checkData
   * simulation. If it is encoded, it can easily be decoded into other types by
   * calling `abi.decode`. This data should not be trusted, and should be
   * validated against the contract's current state.
   */
  function performUpkeep(bytes calldata performData) external;
  function performPreUpkeep(bytes calldata performData) external;
}"},"contracts/chainlink/EpochController.sol":{"content":"// SPDX-License-Identifier: MIT OR GPL-3.0-or-later
pragma solidity ^0.8.7;

import "../chainlink/AutomationCompatibleInterface.sol";
import "../interfaces/IMinter.sol";
import "../interfaces/IGaugeManager.sol";
import "../interfaces/IGenesisPoolManager.sol";
import "../interfaces/IPermissionsRegistry.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

contract EpochController is AutomationCompatibleInterface, OwnableUpgradeable {

    address public automationRegistry;
    address public automationRegistry2;
    address public minter;
    address public gaugeManager;
    IGenesisPoolManager public genesisManager;
    IPermissionsRegistry public permissionsRegistry;

    event Logger(string addr, uint timestamp, uint blocknbr, bool x1, bool x2, string msg);

    constructor() {}

    function initialize(address _minter, address _permissionsRegistry, address _gaugeManager) public initializer {
        __Ownable_init();
        minter = _minter;
        gaugeManager = _gaugeManager;
        permissionsRegistry = IPermissionsRegistry(_permissionsRegistry);
    }


    function checkUpkeep(bytes memory /*checkdata*/) public view override returns (bool upkeepNeeded, bytes memory /*performData*/) {
        upkeepNeeded = IMinter(minter).check();
        // event fire with upkeepNeeded....
    }

    function checkUpPrekeep(bytes memory /*checkdata*/) public view override returns (bool preUpkeepNeeded, bytes memory /*performData*/) {
        preUpkeepNeeded = genesisManager.check();
        // event fire with upkeepNeeded....
    }

    function performUpkeep(bytes calldata /*performData*/) external override {
        // event fire msg.sender and automationRegistry
        require(msg.sender == automationRegistry || permissionsRegistry.hasRole("EPOCH_MANAGER", msg.sender), 'cannot execute');
        (bool upkeepNeeded,) = checkUpkeep('0x');
        // event fire with upkeepNeeded..
        require(upkeepNeeded, "condition not met");
        string memory sender = Strings.toHexString(msg.sender);
        emit Logger(sender, block.timestamp, block.number, msg.sender == automationRegistry, permissionsRegistry.hasRole("EPOCH_MANAGER", msg.sender), 'performUpkeep called');
        genesisManager.checkAtEpochFlip();
        IGaugeManager(gaugeManager).distributeAll();
        IGaugeManager(gaugeManager).distributeFees();
    }

    function performPreUpkeep(bytes calldata /*performData*/) external override {
        // event fire msg.sender and automationRegistry2
        require(msg.sender == automationRegistry2 || permissionsRegistry.hasRole("EPOCH_MANAGER", msg.sender), 'cannot execute');
        (bool preUpkeepNeeded,) = checkUpPrekeep('0x');
        // event fire with preUpkeepNeeded..
        require(preUpkeepNeeded, "condition not met");
        string memory sender = Strings.toHexString(msg.sender);
        emit Logger(sender, block.timestamp, block.number, msg.sender == automationRegistry2, permissionsRegistry.hasRole("EPOCH_MANAGER", msg.sender), 'performPreUpkeep called');
        genesisManager.checkBeforeEpochFlip();
    }

    function setAutomationRegistry(address _automationRegistry) external onlyOwner {
        require(_automationRegistry != address(0));
        automationRegistry = _automationRegistry;
    }

    function setAutomationRegistry2(address _automationRegistry2) external onlyOwner {
        require(_automationRegistry2 != address(0));
        automationRegistry2 = _automationRegistry2;
    }

    function setGaugeManager(address _gaugeManager) external onlyOwner {
        require(_gaugeManager != address(0));
        gaugeManager = _gaugeManager;
    }

    function setMinter(address _minter) external onlyOwner {
        require(_minter != address(0));
        minter = _minter;
    }

    function setGenesisManager(address _genesisManager) external onlyOwner {
        require(_genesisManager != address(0));
        genesisManager = IGenesisPoolManager(_genesisManager);
    }
}"},"contracts/CustomPoolDeployer.sol":{"content":"// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.13;

import "@cryptoalgebra/integral-periphery/contracts/interfaces/IAlgebraCustomPoolEntryPoint.sol";
import "@cryptoalgebra/integral-core/contracts/interfaces/IAlgebraPool.sol";
import "@cryptoalgebra/integral-core/contracts/interfaces/vault/IAlgebraCommunityVault.sol";
import "./interfaces/IAlgebraPoolAPIStorage.sol";
import "./interfaces/IAlgebraFarmingProxyPluginFactory.sol";
import "./interfaces/IAlgebraCustomVaultPoolEntryPoint.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

contract CustomPoolDeployer is Initializable, OwnableUpgradeable {
    event AuthorizedAccountAdded(address indexed account);
    event AuthorizedAccountRemoved(address indexed account);

    address public entryPoint;
    address public plugin;
    int24 public tickSpacing;
    address public algebraPoolAPIStorage;
    address public algebraFeeRecipient;
    address public algebraFeeManager;
    uint16 public algebraFeeShare;

    address public algebraFarmingProxyPluginFactory;
    address public algebraFactory;
    address public algebraPluginFactory;

    mapping(address => address) public poolToPlugin;
    mapping(address => bool) public authorizedAccounts;

    modifier onlyAuthorized() {
        require(
            authorizedAccounts[msg.sender] || msg.sender == owner(),
            "not owner or authorized"
        );
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(
        address _entryPoint,
        address _plugin,
        int24 _tickSpacing,
        address _algebraPoolAPIStorage,
        address _algebraFeeRecipient,
        address _algebraFeeManager,
        uint16 _algebraFeeShare,
        address _algebraFarmingProxyPluginFactory,
        address _algebraFactory,
        address _algebraPluginFactory
    ) public initializer {
        __Ownable_init();

        entryPoint = _entryPoint;
        plugin = _plugin;
        tickSpacing = _tickSpacing;
        algebraPoolAPIStorage = _algebraPoolAPIStorage;
        algebraFeeRecipient = _algebraFeeRecipient;
        algebraFeeManager = _algebraFeeManager;
        algebraFeeShare = _algebraFeeShare;
        algebraFarmingProxyPluginFactory = _algebraFarmingProxyPluginFactory;
        algebraFactory = _algebraFactory;
        algebraPluginFactory = _algebraPluginFactory;
    }

    function addAuthorizedAccount(address account) external onlyOwner {
        require(account != address(0), "zero address");
        require(!authorizedAccounts[account], "already authorized");
        authorizedAccounts[account] = true;
        emit AuthorizedAccountAdded(account);
    }

    function removeAuthorizedAccount(address account) external onlyOwner {
        require(account != address(0), "zero address");
        require(authorizedAccounts[account], "!authorized");
        authorizedAccounts[account] = false;
        emit AuthorizedAccountRemoved(account);
    }

    function createCustomPool(
        address creator,
        address tokenA,
        address tokenB,
        bytes calldata data,
        uint160 initialPrice
    ) external onlyAuthorized returns (address customPool) {
        customPool = IAlgebraCustomPoolEntryPoint(entryPoint).createCustomPool(
            address(this),
            creator,
            tokenA,
            tokenB,
            data
        );
        IAlgebraPool(customPool).initialize(initialPrice);
        IAlgebraCustomPoolEntryPoint(entryPoint).setTickSpacing(
            customPool,
            tickSpacing
        );
        IAlgebraPoolAPIStorage(algebraPoolAPIStorage).setDeployerForPair(customPool);
        address vault = IAlgebraPool(customPool).communityVault();
        IAlgebraCommunityVault(vault).changeAlgebraFeeReceiver(
            algebraFeeRecipient
        );
        // Propose and accept algebra fee change
        IAlgebraCommunityVault(vault).proposeAlgebraFeeChange(algebraFeeShare);
        IAlgebraCommunityVault(vault).acceptAlgebraFeeChangeProposal(
            algebraFeeShare
        );

        IAlgebraCommunityVault(vault).transferAlgebraFeeManagerRole(
            algebraFeeManager
        );
        address newPluginAddress = IAlgebraFarmingProxyPluginFactory(
            algebraFarmingProxyPluginFactory
        ).createAlgebraProxyPlugin(
                customPool,
                algebraFactory,
                algebraPluginFactory
            );
        IAlgebraCustomPoolEntryPoint(entryPoint).setPlugin(
            customPool,
            newPluginAddress
        );
    }

    function beforeCreatePoolHook(
        address,
        address,
        address,
        address,
        address,
        bytes calldata
    ) external view returns (address) {
        require(msg.sender == entryPoint, "Only entryPoint");
        return plugin;
    }

    function afterCreatePoolHook(address, address, address) external pure {
        return;
    }

    function setPluginForPool(
        address pool,
        address _plugin
    ) external onlyAuthorized {
        poolToPlugin[pool] = _plugin;
    }

    // If we need new tick spacing, we'll use a new deployer
    // function setTickSpacing(address pool, int24 newTickSpacing) external {
    //     IAlgebraCustomPoolEntryPoint(entryPoint).setTickSpacing(pool, newTickSpacing);
    // }

    function setPlugin(
        address pool,
        address newPluginAddress
    ) external onlyAuthorized {
        IAlgebraCustomPoolEntryPoint(entryPoint).setPlugin(
            pool,
            newPluginAddress
        );
    }

    function setPluginConfig(
        address pool,
        uint8 newConfig
    ) external onlyAuthorized {
        IAlgebraCustomPoolEntryPoint(entryPoint).setPluginConfig(
            pool,
            newConfig
        );
    }

    function setFee(address pool, uint16 newFee) external onlyAuthorized {
        IAlgebraCustomPoolEntryPoint(entryPoint).setFee(pool, newFee);
    }

    function setCommunityFee(address pool, uint16 newCommunityFee) external onlyAuthorized {
        IAlgebraCustomVaultPoolEntryPoint(entryPoint).setCommunityFee(pool, newCommunityFee);
    }

    function setAlgebraFeeRecipient(address _newRecipient) external onlyOwner {
        require(_newRecipient != address(0), "zero address");
        algebraFeeRecipient = _newRecipient;
    }

    function setAlgebraFeeManager(address _newManager) external onlyOwner {
        require(_newManager != address(0), "zero address");
        algebraFeeManager = _newManager;
    }

    function setAlgebraFeeShare(uint16 _newFeeShare) external onlyOwner {
        algebraFeeShare = _newFeeShare;
    }

    function setAlgebraFarmingProxyPluginFactory(address _algebraFarmingProxyPluginFactory) external onlyOwner {
        require(_algebraFarmingProxyPluginFactory != address(0), "zero address");
        algebraFarmingProxyPluginFactory = _algebraFarmingProxyPluginFactory;
    }

    function setAlgebraFactory(address _algebraFactory) external onlyOwner {
        require(_algebraFactory != address(0), "zero address");
        algebraFactory = _algebraFactory;
    }

    function setAlgebraPluginFactory(address _algebraPluginFactory) external onlyOwner {
        require(_algebraPluginFactory != address(0), "zero address");
        algebraPluginFactory = _algebraPluginFactory;
    }
}
"},"contracts/CustomToken.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract CustomToken is ERC20, Ownable {
    uint8 private immutable _customDecimals;
    uint256 private immutable _initialSupply;

    /**
     * @dev Constructor to initialize token name, symbol, decimals, and initial supply.
     * @param name_ Name of the token.
     * @param symbol_ Symbol of the token.
     * @param decimals_ Number of decimal places.
     * @param initialSupply_ Initial supply (in whole tokens, converted to smallest unit).
     */
    constructor(
        string memory name_,
        string memory symbol_,
        uint8 decimals_,
        uint256 initialSupply_
    ) ERC20(name_, symbol_) Ownable() {
        _customDecimals = decimals_;
        _initialSupply = initialSupply_ * 10 ** decimals_;
        _mint(msg.sender, _initialSupply);
    }

    /**
     * @dev Override the decimals function to return custom decimals.
     */
    function decimals() public view override returns (uint8) {
        return _customDecimals;
    }

    /**
     * @dev Mint new tokens. Only the owner can call this function.
     * @param account Address to receive the minted tokens.
     * @param amount Amount of tokens to be minted (in smallest unit).
     */
    function mint(address account, uint256 amount) external onlyOwner {
        _mint(account, amount);
    }

    /**
     * @dev Burn tokens from an account. Only the owner can call this function.
     * @param account Address whose tokens will be burned.
     * @param amount Amount of tokens to be burned (in smallest unit).
     */
    function burn(address account, uint256 amount) external onlyOwner {
        _burn(account, amount);
    }
}"},"contracts/factories/AuctionFactory.sol":{"content":"// SPDX-License-Identifier: GPL-3.0-or-later
pragma solidity 0.8.13;

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import '../interfaces/IAuctionFactory.sol';

contract AuctionFactory is IAuctionFactory, OwnableUpgradeable {

    address[] public auctions;
    mapping(address => bool) public isAuction;

    event AddAuction(address indexed auction);
    event SetAuction(address indexed old, address indexed latest);

    modifier onlyManager() {
        require(msg.sender == owner());
        _;
    }

    constructor() {}

    // _auction is a fixed auction (default auction assigned to GPs)
    function initialize(address _auction) public initializer {
        __Ownable_init();

        isAuction[_auction] = true;
        auctions.push(_auction);
    }

     function addAuction(address _auction) external onlyManager {
        require(_auction != address(0), 'addr0');
        require(!isAuction[_auction], 'fact');
        require(_auction.code.length > 0, "!contract");

        auctions.push(_auction);
        isAuction[_auction] = true;
        emit AddAuction(_auction);
    }

    function replaceAuction(address _auction, uint256 _pos) external onlyManager {
        require(_auction != address(0), 'addr0');
        require(!isAuction[_auction], '!fact');
        require(_auction.code.length > 0, "!contract");
        address oldPF = auctions[_pos];
        isAuction[oldPF] = false;

        auctions[_pos] = _auction;
        isAuction[_auction] = true;

        emit SetAuction(oldPF, _auction);
    }

    function removeAuction(uint256 _pos) external onlyManager {
        address oldPF = auctions[_pos];
        require(isAuction[oldPF], '!fact');

        auctions[_pos] = address(0);
        isAuction[oldPF] = false;

        emit SetAuction(oldPF, address(0));
    }

    function auctionsLength() external view returns (uint256){
        return auctions.length;
    }

    function allAuctions() external view returns (address[] memory){
        return auctions;
    }
}"},"contracts/factories/BribeFactoryV3.sol":{"content":"// SPDX-License-Identifier: MIT OR GPL-3.0-or-later
pragma solidity ^0.8.11;

import "../Bribes.sol";

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import '../interfaces/IPermissionsRegistry.sol';

interface IBribe {
    function addReward(address) external;
    function setVoter(address _Voter) external;
    function setMinter(address _Voter) external;
    function setOwner(address _Voter) external;
    function emergencyRecoverERC20(address tokenAddress, uint256 tokenAmount) external;
    function recoverERC20AndUpdateData(address tokenAddress, uint256 tokenAmount) external;
    function setAVM(address _avm) external;
}

contract BribeFactoryV3 is OwnableUpgradeable {
    address public last_bribe;
    address[] internal _bribes;
    address public voter;
    address public gaugeManager;

    address[] public defaultRewardToken;

    IPermissionsRegistry public permissionsRegistry;
    address public tokenHandler;

    modifier onlyAllowed() {
        require(owner() == msg.sender || permissionsRegistry.hasRole("BRIBE_ADMIN",msg.sender), 'BRIBE_ADMIN');
        _;
    }

    constructor() {}

    function initialize(address _voter, address _gaugeManager, address _permissionsRegistry, address _tokenHandler) initializer  public {
        __Ownable_init();   //after deploy ownership to multisig
        voter = _voter;
        gaugeManager = _gaugeManager;
        //bribe default tokens
        // defaultRewardToken.push(address(0xF4C8E32EaDEC4BFe97E0F595AdD0f4450a863a11));   // $the
        // defaultRewardToken.push(address(0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c));   // $wbnb
        // defaultRewardToken.push(address(0x8AC76a51cc950d9822D68b83fE1Ad97B32Cd580d));   // $usdc
        // defaultRewardToken.push(address(0xe9e7CEA3DedcA5984780Bafc599bD69ADd087D56));   // $busd
        // defaultRewardToken.push(address(0x55d398326f99059fF775485246999027B3197955));   // $usdt

        defaultRewardToken.push(address(0x68b8220c62513493777563943037Ea919ba0b24C)); // BLACK address

        // registry to check accesses
        permissionsRegistry = IPermissionsRegistry(_permissionsRegistry);
        tokenHandler = _tokenHandler;

    }


    /// @notice create a bribe contract
    /// @dev    _owner must be blackTeamMultisig
    function createBribe(address _owner,address _token0,address _token1, string memory _type) external returns (address) {
        require(msg.sender == gaugeManager || msg.sender == owner(), 'NA');

        Bribe lastBribe = new Bribe(_owner,voter, gaugeManager,address(this), tokenHandler, _token0, _token1, _type);

        last_bribe = address(lastBribe);
        _bribes.push(last_bribe);
        return last_bribe;
    }


    /* -----------------------------------------------------------------------------
    --------------------------------------------------------------------------------
    --------------------------------------------------------------------------------
                                    ONLY OWNER
    --------------------------------------------------------------------------------
    --------------------------------------------------------------------------------
    ----------------------------------------------------------------------------- */


    /// @notice set the bribe factory voter
    function setVoter(address _Voter) external {
        require(owner() == msg.sender, 'NA');
        require(_Voter != address(0), 'ZA');
        voter = _Voter;
    }


    /// @notice set the bribe factory permission registry
    function setPermissionsRegistry(address _permReg) external {
        require(owner() == msg.sender, 'NA');
        require(_permReg != address(0), 'ZA');
        permissionsRegistry = IPermissionsRegistry(_permReg);
    }

    function setTokenHandler(address _tokenHandler) external {
        require(owner() == msg.sender, 'NA');
        require(_tokenHandler != address(0), 'ZA');
        tokenHandler = _tokenHandler;
    }

    /// @notice set the bribe factory permission registry
    function pushDefaultRewardToken(address _token) external {
        require(owner() == msg.sender, 'NA');
        require(_token != address(0), 'ZA');
        defaultRewardToken.push(_token);
    }


    /// @notice set the bribe factory permission registry
    function removeDefaultRewardToken(address _token) external {
        require(owner() == msg.sender, 'NA');
        require(_token != address(0), 'ZA');
        uint i = 0;
        for(i; i < defaultRewardToken.length; i++){
            if(defaultRewardToken[i] == _token){
                defaultRewardToken[i] = defaultRewardToken[defaultRewardToken.length -1];
                defaultRewardToken.pop();
                break;
            }
        }
    }

    /* -----------------------------------------------------------------------------
    --------------------------------------------------------------------------------
    --------------------------------------------------------------------------------
                                    ONLY OWNER or BRIBE ADMIN
    --------------------------------------------------------------------------------
    --------------------------------------------------------------------------------
    ----------------------------------------------------------------------------- */

    /// @notice Add a reward token to a given bribe
    function addRewardToBribe(address _token, address __bribe) external onlyAllowed {
        IBribe(__bribe).addReward(_token);
    }

    /// @notice Add multiple reward token to a given bribe
    function addRewardsToBribe(address[] memory _token, address __bribe) external onlyAllowed {
        uint i = 0;
        for ( i ; i < _token.length; i++){
            IBribe(__bribe).addReward(_token[i]);
        }
    }

    /// @notice Add a reward token to given bribes
    function addRewardToBribes(address _token, address[] memory __bribes) external onlyAllowed {
        uint i = 0;
        for ( i ; i < __bribes.length; i++){
            IBribe(__bribes[i]).addReward(_token);
        }

    }

    /// @notice Add multiple reward tokens to given bribes
    function addRewardsToBribes(address[][] memory _token, address[] memory __bribes) external onlyAllowed {
        uint i = 0;
        uint k;
        for ( i ; i < __bribes.length; i++){
            address _br = __bribes[i];
            for(k = 0; k < _token.length; k++){
                IBribe(_br).addReward(_token[i][k]);
            }
        }

    }

    /// @notice set a new voter in given bribes
    function setBribeVoter(address[] memory _bribe, address _voter) external onlyOwner {
        uint i = 0;
        for(i; i< _bribe.length; i++){
            IBribe(_bribe[i]).setVoter(_voter);
        }
    }

    /// @notice set a new avm in given bribes
    function setBribeAVM(address[] memory _bribe, address _avm) external onlyOwner {
        uint i=0;
        for(i; i<_bribe.length; i++){
            IBribe(_bribe[i]).setAVM(_avm);
        }
    }

    /// @notice set a new minter in given bribes
    function setBribeMinter(address[] memory _bribe, address _minter) external onlyOwner {
        uint i = 0;
        for(i; i< _bribe.length; i++){
            IBribe(_bribe[i]).setMinter(_minter);
        }
    }

    /// @notice set a new owner in given bribes
    function setBribeOwner(address[] memory _bribe, address _owner) external onlyOwner {
        uint i = 0;
        for(i; i< _bribe.length; i++){
            IBribe(_bribe[i]).setOwner(_owner);
        }
    }

    /// @notice recover an ERC20 from bribe contracts.
    function recoverERC20From(address[] memory _bribe, address[] memory _tokens, uint[] memory _amounts) external onlyOwner {
        uint i = 0;
        require(_bribe.length == _tokens.length, 'MISMATCH_LEN');
        require(_tokens.length == _amounts.length, 'MISMATCH_LEN');

        for(i; i< _bribe.length; i++){
            if(_amounts[i] > 0) IBribe(_bribe[i]).emergencyRecoverERC20(_tokens[i], _amounts[i]);
        }
    }

    /// @notice recover an ERC20 from bribe contracts and update.
    function recoverERC20AndUpdateData(address[] memory _bribe, address[] memory _tokens, uint[] memory _amounts) external onlyOwner {
        uint i = 0;
        require(_bribe.length == _tokens.length, 'MISMATCH_LEN');
        require(_tokens.length == _amounts.length, 'MISMATCH_LEN');

        for(i; i< _bribe.length; i++){
            if(_amounts[i] > 0) IBribe(_bribe[i]).recoverERC20AndUpdateData(_tokens[i], _amounts[i]);
        }
    }

    function version() external pure returns (string memory) {
        return "BribeFactoryV3 v1.1.4";
    }

}"},"contracts/factories/GaugeFactory.sol":{"content":"// SPDX-License-Identifier: MIT OR GPL-3.0-or-later
pragma solidity 0.8.13;


import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import '../interfaces/IPermissionsRegistry.sol';
import '../interfaces/IGaugeFactory.sol';
import '../GaugeV2.sol';


interface IGauge{
    function setDistribution(address _distro) external;
    function activateEmergencyMode() external;
    function stopEmergencyMode() external;
    function setInternalBribe(address intbribe) external;
    function setRewarderPid(uint256 pid) external;
    function setGaugeRewarder(address _gr) external;
    function setFeeVault(address _feeVault) external;
    function setGenesisPoolManager(address _genesisManager) external;
}


contract GaugeFactory is IGaugeFactory, OwnableUpgradeable {
    address public last_gauge;
    address public permissionsRegistry;

    address[] internal __gauges;
    address public gaugeManager;
    constructor() {}

    function initialize(address _permissionRegistry) initializer  public {
        __Ownable_init();   //after deploy ownership to multisig
        permissionsRegistry = _permissionRegistry;
    }

    function setRegistry(address _registry) external {
        require(owner() == msg.sender, 'NA');
        permissionsRegistry = _registry;
    }

    function gauges(uint256 i) external view returns(address) {
        return __gauges[i];
    }

    function length() external view returns(uint) {
        return __gauges.length;
    }


    function createGauge(address _rewardToken,address _ve,address _token,address _distribution, address _internal_bribe, address _external_bribe, bool _isPair, address _genesisManager) external onlyGaugeManager returns (address) {
        last_gauge = address(new GaugeV2(_rewardToken,_ve,_token,_distribution,_internal_bribe,_external_bribe,_isPair, _genesisManager) );
        __gauges.push(last_gauge);
        return last_gauge;
    }


    modifier onlyAllowed() {
        require(owner() == msg.sender || IPermissionsRegistry(permissionsRegistry).hasRole("GAUGE_ADMIN",msg.sender), 'GAUGE_ADMIN');
        _;
    }

    modifier EmergencyCouncil() {
        require( msg.sender == IPermissionsRegistry(permissionsRegistry).emergencyCouncil(), "NA");
        _;
    }


    function activateEmergencyMode( address[] memory _gauges) external EmergencyCouncil {
        uint i = 0;
        for ( i ; i < _gauges.length; i++){
            IGauge(_gauges[i]).activateEmergencyMode();
        }
    }

    function stopEmergencyMode( address[] memory _gauges) external EmergencyCouncil {
        uint i = 0;
        for ( i ; i < _gauges.length; i++){
            IGauge(_gauges[i]).stopEmergencyMode();
        }
    }

    function setRewarderPid( address[] memory _gauges, uint[] memory _pids) external onlyAllowed {
        require(_gauges.length == _pids.length, "EXACT_LEN");
        uint i = 0;
        for ( i ; i < _gauges.length; i++){
            IGauge(_gauges[i]).setRewarderPid(_pids[i]);
        }
    }

    function setGaugeRewarder( address[] memory _gauges, address[] memory _rewarder) external onlyAllowed {
        require(_gauges.length == _rewarder.length, "EXACT_LEN");
        uint i = 0;
        for ( i ; i < _gauges.length; i++){
            IGauge(_gauges[i]).setGaugeRewarder(_rewarder[i]);
        }
    }

    function setDistribution(address[] memory _gauges,  address distro) external onlyAllowed {
        uint i = 0;
        for ( i ; i < _gauges.length; i++){
            IGauge(_gauges[i]).setDistribution(distro);
        }
    }


    function setInternalBribe(address[] memory _gauges,  address[] memory int_bribe) external onlyAllowed {
        require(_gauges.length == int_bribe.length, "EXACT_LEN");
        uint i = 0;
        for ( i ; i < _gauges.length; i++){
            IGauge(_gauges[i]).setInternalBribe(int_bribe[i]);
        }
    }

    function setGenesisManager(address _gauge, address _genesisManager) external onlyAllowed {
        require(_genesisManager != address(0), "ZA");
        require(_gauge != address(0), "ZA");
        IGauge(_gauge).setGenesisPoolManager(_genesisManager);
    }


    modifier onlyGaugeManager() {
        require(msg.sender == gaugeManager, "N_G_M");
        _;
    }

    function setGaugeManager(address _gaugeManager) external onlyAllowed {
        require(_gaugeManager != address(0), "ZA");
        gaugeManager = _gaugeManager;
    }
}
"},"contracts/factories/GenesisPoolFactory.sol":{"content":"// SPDX-License-Identifier: GPL-3.0-or-later
pragma solidity 0.8.13;

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import '../interfaces/IGenesisPoolFactory.sol';
import '../GenesisPool.sol';
import '../interfaces/IGenesisPool.sol';
import '../interfaces/ITokenHandler.sol';

contract GenesisPoolFactory is IGenesisPoolFactory, OwnableUpgradeable {

    address public genesisManager;
    address public tokenHandler;

    mapping(address => address[]) public genesisPools;
    address[] public allGenesisPools;

    event GenesisCreated(address indexed nativeToken, address indexed fundingToken);
    event GenesisManagerChanged(address indexed oldManager, address indexed newManager);

    modifier onlyManager() {    
        require(msg.sender == genesisManager);
        _;
    }

    constructor() {}

    function initialize(address _tokenHandler) public initializer {
        __Ownable_init();

        genesisManager = msg.sender;
        tokenHandler = _tokenHandler;
    }

    function setGenesisManager(address _genesisManager) external onlyManager {
        emit GenesisManagerChanged(genesisManager, _genesisManager);
        genesisManager = _genesisManager;
    }

    function genesisPoolsLength() external view returns (uint256){
        return allGenesisPools.length;
    }

    function createGenesisPool(address tokenOwner, address nativeToken, address fundingToken) external onlyManager returns (address genesisPool) {
        require(nativeToken != address(0), "ZA"); 
        require(getGenesisPool(nativeToken) == address(0), "!ZA");

        bytes32 salt = keccak256(abi.encodePacked(nativeToken, fundingToken, genesisPools[nativeToken].length));
        genesisPool = address(new GenesisPool{salt: salt}(genesisManager, tokenHandler, tokenOwner, nativeToken, fundingToken));

        genesisPools[nativeToken].push(genesisPool);
        allGenesisPools.push(genesisPool);

        emit GenesisCreated(nativeToken, fundingToken);
    }

    function getGenesisPools(address nativeToken) external view returns (address[] memory){
        return genesisPools[nativeToken];
    }

    function getGenesisPool(address nativeToken) public view returns (address) {
        address[] memory pools = genesisPools[nativeToken];
        uint length = pools.length;

        if (length == 0) {
            return address(0);
        }
        if(IGenesisPool(pools[length - 1]).poolStatus() != IGenesisPoolBase.PoolStatus.NOT_QUALIFIED)
        {
            return pools[length - 1];
        }

        return address(0);
    }

}"},"contracts/factories/PairFactory.sol":{"content":"// SPDX-License-Identifier: MIT OR GPL-3.0-or-later
pragma solidity 0.8.13;

import '../interfaces/IPairFactory.sol';
import '../interfaces/IPair.sol';
import '../interfaces/IPairGenerator.sol';

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";

contract PairFactory is IPairFactory, OwnableUpgradeable {

    bool public isPaused;

    uint256 public stableFee;
    uint256 public volatileFee;
    uint256 public stakingNFTFee;
    uint256 public MAX_REFERRAL_FEE; // 12%
    uint256 public constant MAX_FEE = 500; // 5%

    address public feeManager;
    address public pendingFeeManager;
    address public dibs; // referral fee handler
    address public stakingFeeHandler; // staking fee handler
    address public pairGenerator;
    address public genesisManager;

    mapping(address => mapping(address => mapping(bool => address))) public getPair;
    address[] public allPairs;
    mapping(address => bool) public isPair;
    mapping(address => uint256) public customFees;
    mapping(address => uint256) public customReferralFees;
    mapping(address => bool) public isGenesis;

    event PairCreated(address indexed token0, address indexed token1, bool stable, address pair, uint);

    modifier onlyManager() {
        require(msg.sender == feeManager, "NA");
        _;
    }

    mapping(address => bool) public authorizedAccounts;
    modifier onlyAuthorized() {
        require(
            authorizedAccounts[msg.sender] || msg.sender == feeManager || msg.sender == genesisManager,
            "not manager or authorized"
        );
        _;
    }
    event AuthorizedAccountAdded(address indexed account);
    event AuthorizedAccountRemoved(address indexed account);
    constructor() {}

    function initialize(address _pairGenerator) public initializer {
        __Ownable_init();
        isPaused = false;
        feeManager = msg.sender;
        stableFee = 5; // 0.05%
        volatileFee = 60; // 0.6%
        stakingNFTFee = 0; // 0% of stable/volatileFee, we can change it later if needed
        MAX_REFERRAL_FEE = 0; // 0%
        pairGenerator = _pairGenerator;
    }

    function allPairsLength() external view returns (uint) {
        return allPairs.length;
    }

    function setPause(bool _state) external {
        require(msg.sender == owner(), "NA");
        isPaused = _state;
    }

    function setFeeManager(address _feeManager) external onlyManager {
        pendingFeeManager = _feeManager;
    }

    function acceptFeeManager() external {
        require(msg.sender == pendingFeeManager, "NA");
        feeManager = pendingFeeManager;
    }

    function setStakingFees(uint256 _newFee) external onlyManager {
        require(_newFee <= 3000, "HFE");
        stakingNFTFee = _newFee;
    }

    function setStakingFeeAddress(address _feehandler) external onlyManager {
        require(_feehandler != address(0), "ZA");
        stakingFeeHandler = _feehandler;
    }

    function setDibs(address _dibs) external onlyManager {
        require(_dibs != address(0), "ZA");
        dibs = _dibs;
    }

    function setReferralFee(uint256 _refFee) external onlyManager {
        MAX_REFERRAL_FEE = _refFee;
    }

    function setFee(bool _stable, uint256 _fee) external onlyManager {
        require(_fee <= MAX_FEE, "HFE");
        require(_fee != 0, "ZFE");
        if (_stable) {
            stableFee = _fee;
        } else {
            volatileFee = _fee;
        }
    }

    function setCustomFees(address _pairAddress, uint256 _fees) external onlyManager {
        require(_fees <= MAX_FEE, "HFE");
        require(isPair[_pairAddress], "INVP");
        customFees[_pairAddress] = _fees;
    }

    function setCustomReferralFee(address _pairAddress, uint256 _refFee) external onlyManager {
        require(isPair[_pairAddress], "INVP");
        customReferralFees[_pairAddress] = _refFee;
    }

    function getFee(address _pairAddress, bool _stable) public view returns (uint256) {
        if (customFees[_pairAddress] > 0) {
            return customFees[_pairAddress];
        }
        return _stable ? stableFee : volatileFee;
    }

    function getReferralFee(address _pairAddress) public view returns (uint256) {
        if (customReferralFees[_pairAddress] > 0) {
            return customReferralFees[_pairAddress];
        }
        return MAX_REFERRAL_FEE;
    }

    function getIsGenesis(address _pairAddress) public view returns (bool) {
        return isGenesis[_pairAddress];
    }

    function setIsGenesis(address _pairAddress, bool status) external onlyManager {
        require(_pairAddress != address(0) && isPair[_pairAddress], "INVP");
        isGenesis[_pairAddress] = status;
    }

    function pairCodeHash() external view returns (bytes32) {
        return IPairGenerator(pairGenerator).pairCodeHash();
    }

    function createPair(address tokenA, address tokenB, bool stable) external onlyAuthorized returns (address pair) {
        require(tokenA != tokenB, "IA"); // Pair: IDENTICAL_ADDRESSES
        (address token0, address token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        require(token0 != address(0), "ZA"); // Pair: ZERO_ADDRESS
        require(getPair[token0][token1][stable] == address(0), "!ZA");
        pair = IPairGenerator(pairGenerator).createPair(token0, token1, stable);
        getPair[tokenA][tokenB][stable] = pair;
        getPair[tokenB][tokenA][stable] = pair; // Store in reverse direction
        allPairs.push(pair);
        isPair[pair] = true;

        emit PairCreated(token0, token1, stable, pair, allPairs.length);
    }

    function setGenesisManager(address _genesisManager) external onlyManager {
        genesisManager = _genesisManager;
    }

    function setGenesisStatus(address _pair, bool status) external {
        require(msg.sender == genesisManager || msg.sender == feeManager, "NA");
        isGenesis[_pair] = status;
    }

    function addAuthorizedAccount(address account) external onlyManager {
        require(account != address(0), "zero address");
        require(!authorizedAccounts[account], "already authorized");
        authorizedAccounts[account] = true;
        emit AuthorizedAccountAdded(account);
    }

    function removeAuthorizedAccount(address account) external onlyManager {
        require(account != address(0), "zero address");
        require(authorizedAccounts[account], "!authorized");
        authorizedAccounts[account] = false;
        emit AuthorizedAccountRemoved(account);
    }

    function version() external pure returns (string memory) {
        return "PairFactory v1.2.2";
    }
}"},"contracts/Fan.sol":{"content":"// SPDX-License-Identifier: MIT

