pragma solidity 0.8.13;

import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import {BlackTimeLibrary} from "./libraries/BlackTimeLibrary.sol";

import "./interfaces/IGenesisPool.sol";
import "./interfaces/IGenesisPoolBase.sol";
import "./interfaces/ITokenHandler.sol";
import "./interfaces/IAuction.sol";
import "./interfaces/IBribe.sol";
import "./interfaces/IRouter.sol";
import "./interfaces/IGauge.sol";

contract GenesisPool is IGenesisPool, IGenesisPoolBase {

    using SafeERC20 for IERC20;

    address immutable internal genesisManager;
    ITokenHandler immutable internal tokenHandler;
    IAuction internal auction;

    TokenAllocation public allocationInfo;
    GenesisInfo public genesisInfo;
    PoolStatus public poolStatus;
    LiquidityPool public liquidityPoolInfo;

    address[] public incentiveTokens;
    mapping(address => uint256) public incentives;

    address[] public depositers;
    mapping(address => uint256) public userDeposits;

    uint256 internal totalDeposits;
    uint256 liquidity;
    uint256 tokenOwnerUnstaked;

    event DepositedNativeToken(address native, address fundingToken, address owner, address genesisPool, uint256 proposedNativeAmount, uint proposedFundingAmount);
    event AddedIncentives(address native, address[] incentivesToken, uint256[] incentivesAmount);
    event RejectedGenesisPool(address native);
    event ApprovedGenesisPool(address proposedToken);

    modifier onlyManager() {
        require(msg.sender == genesisManager);
        _;
    }

    modifier onlyManagerOrProtocol() {
        require(msg.sender == genesisManager || msg.sender == genesisInfo.tokenOwner);
        _;
    }

    modifier onlyGauge() {
        require(msg.sender == liquidityPoolInfo.gaugeAddress);
        _;
    }

    constructor(address _genesisManager, address _tokenHandler, address _tokenOwner, address _nativeToken, address _fundingToken){
        genesisInfo.tokenOwner = _tokenOwner;
        genesisInfo.nativeToken = _nativeToken;    
        genesisInfo.fundingToken = _fundingToken;

        genesisManager = _genesisManager;
        tokenHandler = ITokenHandler(_tokenHandler);

        totalDeposits = 0;
        liquidity = 0;
        tokenOwnerUnstaked = 0;
    }


    function setGenesisPoolInfo(GenesisInfo calldata _genesisInfo, TokenAllocation calldata _allocationInfo, address _auction) external onlyManager(){
        genesisInfo = _genesisInfo;

        genesisInfo.duration = BlackTimeLibrary.epochMultiples(genesisInfo.duration);
        genesisInfo.startTime = BlackTimeLibrary.epochStart(genesisInfo.startTime);

        allocationInfo.proposedNativeAmount = _allocationInfo.proposedNativeAmount;
        allocationInfo.proposedFundingAmount = _allocationInfo.proposedFundingAmount;
        allocationInfo.allocatedNativeAmount = 0;
        allocationInfo.allocatedFundingAmount = 0;
        allocationInfo.refundableNativeAmount = 0;

        auction = IAuction(_auction);
        poolStatus = PoolStatus.NATIVE_TOKEN_DEPOSITED;

        emit DepositedNativeToken(_genesisInfo.nativeToken, _genesisInfo.fundingToken, genesisInfo.tokenOwner, address(this), _allocationInfo.proposedNativeAmount, _allocationInfo.proposedFundingAmount);
    }

    function addIncentives(address[] calldata _incentivesToken, uint256[] calldata _incentivesAmount) external {
        address _sender = msg.sender;
        require(_sender == genesisInfo.tokenOwner, "NA");
        require(poolStatus == PoolStatus.NATIVE_TOKEN_DEPOSITED || poolStatus == PoolStatus.PRE_LISTING, "INS");
        require(_incentivesToken.length > 0, "ZV");
        require(_incentivesToken.length == _incentivesAmount.length, "MISMATCH_LEN");
        uint256 _incentivesCnt = _incentivesToken.length;
        uint256 i = 0;

        address _token;
        uint256 _amount;
        for(i = 0; i < _incentivesCnt; i++){
            _token = _incentivesToken[i];
            _amount = _incentivesAmount[i];
            if(_token != address(0) && _amount > 0 && (_token == genesisInfo.nativeToken || tokenHandler.isConnector(_token))){
                IERC20(_token).safeTransferFrom(_sender, address(this), _amount);
                if(incentives[_token] == 0){
                    incentiveTokens.push(_token);
                }
                incentives[_token] += _amount;
            }
        }

        emit AddedIncentives(genesisInfo.nativeToken, _incentivesToken, _incentivesAmount);
    }

    function rejectPool() external onlyManager {
        require(poolStatus == PoolStatus.NATIVE_TOKEN_DEPOSITED || poolStatus == PoolStatus.PRE_LISTING, "INS");
        poolStatus = PoolStatus.NOT_QUALIFIED;
        allocationInfo.refundableNativeAmount = allocationInfo.proposedNativeAmount;
        emit RejectedGenesisPool(genesisInfo.nativeToken);
    }

    function approvePool(address _pairAddress) external onlyManager {
        require(poolStatus == PoolStatus.NATIVE_TOKEN_DEPOSITED, "INS");
        liquidityPoolInfo.pairAddress = _pairAddress;
        poolStatus = PoolStatus.PRE_LISTING;
        emit ApprovedGenesisPool(genesisInfo.nativeToken);
    }

    function depositToken(address spender, uint256 amount) external onlyManager returns (bool) {
        require(poolStatus == PoolStatus.PRE_LISTING || poolStatus == PoolStatus.PRE_LAUNCH, "INS");
        require(block.timestamp >= genesisInfo.startTime, "INS");

        uint256 _fundingLeft = allocationInfo.proposedFundingAmount - allocationInfo.allocatedFundingAmount;
        uint256 _maxFundingLeft = _getFundingTokenAmount(allocationInfo.proposedNativeAmount - allocationInfo.allocatedNativeAmount);
        uint _amount = _maxFundingLeft <= _fundingLeft ? _maxFundingLeft : _fundingLeft;
        _amount = _amount <= amount ? _amount : amount;
        require(_amount > 0, "ZV");

        IERC20(genesisInfo.fundingToken).safeTransferFrom(spender, address(this), _amount);

        if(userDeposits[spender] == 0){
            depositers.push(spender);
        }

        userDeposits[spender] = userDeposits[spender] + _amount;
        totalDeposits += _amount;

        uint256 nativeAmount = _getNativeTokenAmount(totalDeposits);
        allocationInfo.allocatedFundingAmount += _amount;
        allocationInfo.allocatedNativeAmount = nativeAmount;

        IAuction(auction).purchased(nativeAmount);

        return poolStatus == PoolStatus.PRE_LISTING && _eligbleForPreLaunchPool();
    }

    function eligbleForPreLaunchPool() external view returns (bool){
        return _eligbleForPreLaunchPool();
    }

    function _eligbleForPreLaunchPool() internal view returns (bool){
        uint _endTime = genesisInfo.startTime + genesisInfo.duration;
        uint256 targetNativeAmount = (allocationInfo.proposedNativeAmount * genesisInfo.threshold) / 10000; // threshold is 100 * of original to support 2 deciamls

        return (BlackTimeLibrary.isLastEpoch(block.timestamp, _endTime) && allocationInfo.allocatedNativeAmount >= targetNativeAmount);
    }

    function _eligbleForCompleteLaunch() internal view returns (bool){
        return allocationInfo.allocatedNativeAmount >= allocationInfo.proposedNativeAmount;
    }

    function eligbleForDisqualify() external view returns (bool){
        uint256 _endTime = genesisInfo.startTime + genesisInfo.duration;    
        uint256 targetNativeAmount = (allocationInfo.proposedNativeAmount * genesisInfo.threshold) / 10000; // threshold is 100 * of original to support 2 deciamls

        return (BlackTimeLibrary.isLastEpoch(block.timestamp, _endTime) && allocationInfo.allocatedNativeAmount < targetNativeAmount);
    }

    function transferIncentives(address gauge, address external_bribe, address internal_bribe) external onlyManager {
        liquidityPoolInfo.gaugeAddress = gauge;
        liquidityPoolInfo.external_bribe = external_bribe;
        liquidityPoolInfo.internal_bribe = internal_bribe;

        uint256 i = 0;
        uint256 _amount = 0;
        uint256 _incentivesCnt = incentiveTokens.length;
        for(i = 0; i < _incentivesCnt; i++){
            _amount = incentives[incentiveTokens[i]];
            if(_amount > 0)
            {
                IERC20(incentiveTokens[i]).safeApprove(external_bribe, _amount);
                IBribe(external_bribe).notifyRewardAmount(incentiveTokens[i], _amount);
            }
        }

        poolStatus = PoolStatus.PRE_LAUNCH;
    }

    function setPoolStatus(PoolStatus status) external onlyManager {
        _setPoolStatus(status);
    }

    function _setPoolStatus(PoolStatus status) internal {
        if(status == PoolStatus.PARTIALLY_LAUNCHED){
            allocationInfo.refundableNativeAmount = allocationInfo.proposedNativeAmount - allocationInfo.allocatedNativeAmount;
        }
        else if(status == PoolStatus.LAUNCH){
            allocationInfo.refundableNativeAmount = 0;
        }
        else if(status == PoolStatus.NOT_QUALIFIED){
            allocationInfo.refundableNativeAmount = allocationInfo.proposedNativeAmount;
        }

        poolStatus = status;
    }

    function _approveTokens(address router) internal {
        IERC20(genesisInfo.nativeToken).safeApprove(router, allocationInfo.allocatedNativeAmount);
        IERC20(genesisInfo.fundingToken).safeApprove(router, allocationInfo.allocatedFundingAmount);
    }

    function _addLiquidityAndDistribute(address _router, uint256 nativeDesired, uint256 fundingDesired, uint256 maturityTime) internal {
        (, , uint _liquidity) = IRouter(_router).addLiquidity(genesisInfo.nativeToken, genesisInfo.fundingToken, genesisInfo.stable, nativeDesired, fundingDesired, 0, 0, address(this), block.timestamp + 100);
        liquidity = _liquidity;
        IERC20(liquidityPoolInfo.pairAddress).safeApprove(liquidityPoolInfo.gaugeAddress, liquidity);
        IGauge(liquidityPoolInfo.gaugeAddress).depositsForGenesis(genesisInfo.tokenOwner, block.timestamp + maturityTime, liquidity);
    }

    function _launchCompletely(address router, uint256 maturityTime) internal {
        _approveTokens(router);
        _addLiquidityAndDistribute(router,  allocationInfo.allocatedNativeAmount,  allocationInfo.allocatedFundingAmount, maturityTime);
        _setPoolStatus(PoolStatus.LAUNCH);
    }

    function _launchPartially(address router, uint256 maturityTime) internal {
        _approveTokens(router);
        _addLiquidityAndDistribute(router,  allocationInfo.allocatedNativeAmount,  allocationInfo.allocatedFundingAmount, maturityTime);
        _setPoolStatus(PoolStatus.PARTIALLY_LAUNCHED);
    }

    function launch(address router, uint256 maturityTime) external onlyManager {
        if(genesisInfo.maturityTime > 0) {
            maturityTime = genesisInfo.maturityTime;
        }
        if(_eligbleForCompleteLaunch()){
            _launchCompletely(router, maturityTime);
        }else{
            _launchPartially(router, maturityTime);
        }
    }

    function claimableNative() public view returns(PoolStatus, address token, uint256 amount){
        if(msg.sender == genesisInfo.tokenOwner){
            if(poolStatus == PoolStatus.PARTIALLY_LAUNCHED || poolStatus == PoolStatus.NOT_QUALIFIED){
                token = genesisInfo.nativeToken;
                amount = allocationInfo.refundableNativeAmount;
            }
        }
        return (poolStatus, token, amount);
    }

    function claimableDeposits() public view returns(PoolStatus, address token, uint256 amount){
        if(poolStatus == PoolStatus.NOT_QUALIFIED){
            token = genesisInfo.fundingToken;
            amount = userDeposits[msg.sender];
        }
        return (poolStatus, token, amount);
    }

    function claimNative() external {
        require(poolStatus == PoolStatus.NOT_QUALIFIED || poolStatus == PoolStatus.PARTIALLY_LAUNCHED, "INS");
        require(msg.sender == genesisInfo.tokenOwner, "NA");

        uint256 _amount = allocationInfo.refundableNativeAmount;
        allocationInfo.refundableNativeAmount = 0;

        if(_amount > 0){
            IERC20(genesisInfo.nativeToken).safeTransfer(msg.sender, _amount);
        }
    }

    function claimDeposits() external {
        require(poolStatus == PoolStatus.NOT_QUALIFIED, "INS");

        uint256 _amount = userDeposits[msg.sender];
        userDeposits[msg.sender] = 0;

        if(_amount > 0){
            IERC20(genesisInfo.fundingToken).safeTransfer(msg.sender, _amount);
        }
    }

    function claimableIncentives() public view returns(address[] memory tokens , uint256[] memory amounts){
        if(poolStatus == PoolStatus.NOT_QUALIFIED && msg.sender == genesisInfo.tokenOwner){
            tokens = incentiveTokens;
            uint256 incentivesCnt = incentiveTokens.length;
            amounts = new uint256[](incentivesCnt);
            uint256 i;
            for(i = 0; i < incentivesCnt; i++){
                amounts[i] = incentives[incentiveTokens[i]];
            }
        }
    }

    function claimIncentives() external {
        require(poolStatus == PoolStatus.NOT_QUALIFIED, "INS");
        require(msg.sender == genesisInfo.tokenOwner, "NA");

        uint256 _incentivesCnt = incentiveTokens.length;
        uint256 i;
        uint _amount;

        for(i = 0; i < _incentivesCnt; i++){
            _amount = incentives[incentiveTokens[i]];
            incentives[incentiveTokens[i]] = 0;

            IERC20(incentiveTokens[i]).safeTransfer(msg.sender, _amount);
        }
    }

    function balanceOf(address account) external view returns (uint256) {
        uint256 _depositerLiquidity = liquidity / 2;
        uint256 balance = (_depositerLiquidity * userDeposits[account]) / totalDeposits;
        if(account == genesisInfo.tokenOwner) balance += (liquidity - _depositerLiquidity - tokenOwnerUnstaked);
        return balance;
    }

    function deductAmount(address account, uint256 gaugeTokenAmount) external onlyGauge {
        uint256 _depositerLiquidity = liquidity / 2;
        uint256 userAmount = (totalDeposits * gaugeTokenAmount) / _depositerLiquidity; 

        if(account == genesisInfo.tokenOwner) {
            uint256 pendingOwnerStaked = liquidity - _depositerLiquidity - tokenOwnerUnstaked;

            if(gaugeTokenAmount < pendingOwnerStaked){
                tokenOwnerUnstaked += gaugeTokenAmount;
                userAmount = 0;
            } else {
                tokenOwnerUnstaked = liquidity - _depositerLiquidity;
                userAmount -= (totalDeposits * pendingOwnerStaked) / _depositerLiquidity;
            }
        }
        userDeposits[account] -= userAmount;
    }

    function deductAllAmount(address account) external onlyGauge {
        uint256 _depositerLiquidity = liquidity / 2;
        if(account == genesisInfo.tokenOwner) tokenOwnerUnstaked = liquidity - _depositerLiquidity;
        userDeposits[account] = 0;
    }

    function getNativeTokenAmount(uint256 depositAmount) external view returns (uint256){
        if(depositAmount <= 0) return 0;
        return _getNativeTokenAmount(depositAmount);
    }

    function _getNativeTokenAmount(uint256 depositAmount) internal view returns (uint256){
        return auction.getNativeTokenAmount(depositAmount);
    }

    function getFundingTokenAmount(uint256 nativeAmount) external view returns (uint256){
        if(nativeAmount <= 0) return 0;
        return _getFundingTokenAmount(nativeAmount);
    }

    function _getFundingTokenAmount(uint256 nativeAmount) internal view returns (uint256){
        return auction.getFundingTokenAmount(nativeAmount);
    }

    function getAllocationInfo() external view returns (TokenAllocation memory){
        return allocationInfo;
    }

    function getIncentivesInfo() external view returns (IGenesisPoolBase.TokenIncentiveInfo memory incentiveInfo){
        uint256 incentivesCnt = incentiveTokens.length;
        incentiveInfo.incentivesToken = new address[](incentivesCnt);
        incentiveInfo.incentivesAmount = new uint256[](incentivesCnt);
        uint256 i;
        for(i = 0; i < incentivesCnt; i++){
            incentiveInfo.incentivesToken[i] = incentiveTokens[i];
            incentiveInfo.incentivesAmount[i] = incentives[incentiveTokens[i]];
        }
    }

    function getGenesisInfo() external view returns (IGenesisPoolBase.GenesisInfo memory){
        return genesisInfo;
    }

    function getLiquidityPoolInfo() external view returns (IGenesisPoolBase.LiquidityPool memory){
        return liquidityPoolInfo;
    }

    function setAuction(address _auction) external onlyManagerOrProtocol {
        require(_auction != address(0), "ZA");
        require(poolStatus == PoolStatus.NATIVE_TOKEN_DEPOSITED, "INS");
        auction = IAuction(_auction);
    }

    function setMaturityTime(uint256 _maturityTime) external onlyManager{
        genesisInfo.maturityTime = _maturityTime;
    }

    function setStartTime(uint256 _startTime) external onlyManager{
        _startTime = BlackTimeLibrary.epochStart(_startTime);
        require(_startTime + genesisInfo.duration - BlackTimeLibrary.NO_GENESIS_DEPOSIT_WINDOW > block.timestamp, "TIME");
        genesisInfo.startTime = _startTime;
    }
}"},"contracts/GenesisPoolManager.sol":{"content":"// SPDX-License-Identifier: GPL-3.0-or-later
pragma solidity 0.8.13;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";

import "./interfaces/IGenesisPoolManager.sol";
import "./interfaces/IGaugeManager.sol";
import "./interfaces/IGenesisPoolBase.sol";
import "./interfaces/IGauge.sol";

import "./interfaces/ITokenHandler.sol";
import "./interfaces/IPermissionsRegistry.sol";
import "./interfaces/IGenesisPoolFactory.sol";
import './interfaces/IGenesisPool.sol';
import './interfaces/IAuctionFactory.sol';
import './interfaces/IPair.sol';
import {BlackTimeLibrary} from "./libraries/BlackTimeLibrary.sol";

interface IBaseV1Factory {
    function isPair(address pair) external view returns (bool);
    function getPair(address tokenA, address token, bool stable) external view returns (address);
    function createPair(address tokenA, address tokenB, bool stable) external returns (address pair);
    function setGenesisPool(address _genesisPool) external;
    function setGenesisStatus(address _pair, bool status) external;
}

contract GenesisPoolManager is IGenesisPoolBase, IGenesisPoolManager, OwnableUpgradeable, ReentrancyGuardUpgradeable {

    uint256 public MIN_DURATION;
    uint256 public MIN_THRESHOLD;
    uint256 public MATURITY_TIME;

    address public epochController;
    address public permissionRegistory;
    address public router;
    IBaseV1Factory public pairFactory;

    IGaugeManager public gaugeManager;
    ITokenHandler public tokenHandler;

    IGenesisPoolFactory public genesisFactory;
    IAuctionFactory public auctionFactory;

    uint public WEEK;
    uint public pre_epoch_period; // 2 : 30 of every thursday

    using SafeERC20 for IERC20;

    mapping(address => mapping(address => bool)) public whiteListedTokensToUser;
    address[] public nativeTokens;
    address[] public liveNativeTokens;
    mapping(address => uint256) internal liveNativeTokensIndex;
    mapping(address => bool) internal isNativeToken;
    uint256 public processingIndex;
    uint256 public epochFlipProcessingIndex;


    event WhiteListedTokenToUser(address proposedToken, address tokenOwner);
    event DespositedToken(address genesisPool, address sender, uint256 amount);

    modifier Governance() {
        require(IPermissionsRegistry(permissionRegistory).hasRole("GOVERNANCE",msg.sender), 'GOVERNANCE');
        _;
    }

    function _checkGovernance() internal view returns (bool) {
        return IPermissionsRegistry(permissionRegistory).hasRole("GOVERNANCE",msg.sender);
    }

    modifier GenesisManager() {
        require(IPermissionsRegistry(permissionRegistory).hasRole("GENESIS_MANAGER", msg.sender), 'GENESIS_MANAGER');
        _;
    }

    constructor() {}

    function initialize(address _epochController, address _router, address _permissionRegistory, address _gaugeManager, address _pairFactory, address _genesisFactory, address _auctionFactory, address _tokenHandler) initializer  public {
        __Ownable_init();
        __ReentrancyGuard_init();

        epochController = _epochController;
        router = _router;
        permissionRegistory = _permissionRegistory;
        gaugeManager = IGaugeManager(_gaugeManager);
        pairFactory = IBaseV1Factory(_pairFactory);
        genesisFactory = IGenesisPoolFactory(_genesisFactory);
        auctionFactory = IAuctionFactory(_auctionFactory);
        tokenHandler = ITokenHandler(_tokenHandler);
        WEEK = BlackTimeLibrary.WEEK;
        MIN_DURATION = 2 * BlackTimeLibrary.WEEK;
        MIN_THRESHOLD = 50 * 10 ** 2;
        MATURITY_TIME = BlackTimeLibrary.GENESIS_STAKING_MATURITY_TIME;

        pre_epoch_period = BlackTimeLibrary.prevPreEpoch(block.timestamp);
        processingIndex = 0;
        epochFlipProcessingIndex =0;
    }

    function check() external view returns (bool) {
        uint _period = pre_epoch_period;
        return block.timestamp >= _period + WEEK;
    }

    function whiteListUserAndToken(address tokenOwner, address proposedToken) external Governance {
        whiteListedTokensToUser[proposedToken][tokenOwner] = true;
        emit WhiteListedTokenToUser(proposedToken, tokenOwner);
    }

    function liveNativeTokensLength() external view returns (uint256) {
        return liveNativeTokens.length;
    }

    function depositNativeToken(address nativeToken, uint auctionIndex, GenesisInfo calldata genesisPoolInfo, TokenAllocation calldata allocationInfo) external nonReentrant returns(address genesisPool) {
        address _sender = msg.sender;
        require(whiteListedTokensToUser[nativeToken][_sender] || _checkGovernance(), "!WHITELIST");
        require(nativeToken == genesisPoolInfo.nativeToken, "IA");
        require(_sender == genesisPoolInfo.tokenOwner, "NA");
        require(allocationInfo.proposedNativeAmount > 0, "ZV");
        require(allocationInfo.proposedFundingAmount > 0, "ZV");

        address _fundingToken = genesisPoolInfo.fundingToken;
        require(tokenHandler.isConnector(_fundingToken), "!CONN");
        bool _stable = genesisPoolInfo.stable;

        address pairAddress = pairFactory.getPair(nativeToken, _fundingToken, _stable);
        if (pairAddress == address(0)) {
            pairAddress = pairFactory.createPair(nativeToken, _fundingToken, _stable);
        } else {
            require(IERC20(nativeToken).balanceOf(pairAddress) == 0, "!ZV");
            require(IERC20(_fundingToken).balanceOf(pairAddress) == 0, "!ZV");
        }
        pairFactory.setGenesisStatus(pairAddress, true);

        require(genesisPoolInfo.duration >= MIN_DURATION && genesisPoolInfo.threshold >= MIN_THRESHOLD && genesisPoolInfo.startPrice > 0, "INV_GENESIS");
        require(genesisPoolInfo.supplyPercent > 0 && genesisPoolInfo.supplyPercent <= 10000, "INV");

        require(genesisPoolInfo.nativeToken == nativeToken, "MISMATCH");

        genesisPool = genesisFactory.getGenesisPool(nativeToken);
        if(genesisPool == address(0))
            genesisPool = genesisFactory.createGenesisPool(_sender, nativeToken, _fundingToken);

        require(genesisPool != address(0), "ZA");
        IERC20(nativeToken).safeTransferFrom(_sender, genesisPool, allocationInfo.proposedNativeAmount);

        address auction = auctionFactory.auctions(auctionIndex);
        auction = auction == address(0) ? auctionFactory.auctions(0) : auction;
        if(!isNativeToken[nativeToken]){
            nativeTokens.push(nativeToken);
            isNativeToken[nativeToken] = true;
        }
        IGenesisPool(genesisPool).setGenesisPoolInfo(genesisPoolInfo, allocationInfo, auction);
    }

    function rejectGenesisPool(address nativeToken) external Governance {
        require(nativeToken != address(0), "ZA");
        address genesisPool = genesisFactory.getGenesisPool(nativeToken);
        require(genesisPool != address(0), 'ZA');

        IGenesisPool(genesisPool).rejectPool();
        _removeLiveToken(nativeToken);
    }

    function approveGenesisPool(address nativeToken) external Governance {
        require(nativeToken != address(0), "ZA");
        address genesisPool = genesisFactory.getGenesisPool(nativeToken);
        require(genesisPool != address(0), 'ZA');

        GenesisInfo memory genesisInfo =  IGenesisPool(genesisPool).getGenesisInfo();
        require(genesisInfo.startTime + genesisInfo.duration - BlackTimeLibrary.NO_GENESIS_DEPOSIT_WINDOW > block.timestamp, "TIME");

        address pairAddress = pairFactory.getPair(nativeToken, genesisInfo.fundingToken, genesisInfo.stable);
        IPair ipair = IPair(pairAddress);
        (uint r0,uint r1,) = ipair.getReserves();
        require(r0 == 0 && r1 == 0, "!ZV");

        liveNativeTokens.push(nativeToken);
        liveNativeTokensIndex[nativeToken] = liveNativeTokens.length; // becuase default valie is 0, so starting with 1

        IGenesisPool(genesisPool).approvePool(pairAddress);
    }

    function depositToken(address genesisPool, uint256 amount) external nonReentrant{
        require(amount > 0, "ZV");
        require(genesisPool != address(0), "ZA");

        bool preLaunchPool = IGenesisPool(genesisPool).depositToken(msg.sender, amount);

        if(preLaunchPool){
            tokenHandler.whitelistToken(IGenesisPool(genesisPool).getGenesisInfo().nativeToken);
            _preLaunchPool(genesisPool);
        }

        emit DespositedToken(genesisPool, msg.sender, amount);
    }


    function _preLaunchPool(address genesisPool) internal {
        address _poolAddress = IGenesisPool(genesisPool).getLiquidityPoolInfo().pairAddress;
        (address _gauge, address _internal_bribe, address _external_bribe) = gaugeManager.createGauge(_poolAddress, 0);

        IGenesisPool(genesisPool).transferIncentives(_gauge, _external_bribe, _internal_bribe);
    }

    function _launchPool(address _nativeToken, address _genesisPool) internal {
        LiquidityPool memory liquidityPool = IGenesisPool(_genesisPool).getLiquidityPoolInfo();
        pairFactory.setGenesisStatus(liquidityPool.pairAddress, false);
        IGauge(liquidityPool.gaugeAddress).setGenesisPool(_genesisPool);
        IGenesisPool(_genesisPool).launch(router, MATURITY_TIME);
        _removeLiveToken(_nativeToken);
    }

    // at epoch flip, PRE_LISTING -> PRE_LAUNCH (condition met) , PRE_LAUNCH_DDEPOSIT_DISBALED -> LAUNCH or PARTIALLY_LAUNCH
    function checkAtEpochFlipOld() external GenesisManager {
        require(epochController == msg.sender, "NA");

        uint256 _proposedTokensCnt = liveNativeTokens.length;
        uint256 i;
        address _genesisPool;
        PoolStatus _poolStatus;
        address nativeToken;

        for(i = _proposedTokensCnt; i > 0; i--){
            nativeToken = liveNativeTokens[i-1];
            _genesisPool = genesisFactory.getGenesisPool(nativeToken);
            _poolStatus = IGenesisPool(_genesisPool).poolStatus();

            if(_poolStatus == PoolStatus.PRE_LISTING && IGenesisPool(_genesisPool).eligbleForPreLaunchPool()){
                tokenHandler.whitelistToken(nativeToken);
                _preLaunchPool(_genesisPool);
            }else if(_poolStatus == PoolStatus.PRE_LAUNCH_DEPOSIT_DISABLED){
                _launchPool(nativeToken, _genesisPool);
            }
        }
    }

    // before 3 hrs
    function checkBeforeEpochFlip() external GenesisManager {
        require(epochController == msg.sender, "NA");

        uint _period = pre_epoch_period;
        if (block.timestamp >= _period + WEEK) {

            uint256 _proposedTokensCnt = liveNativeTokens.length;
            uint256 i;
            address _genesisPool;
            PoolStatus _poolStatus;
            address nativeToken;

            for(i = _proposedTokensCnt; i > 0; i--){
                nativeToken = liveNativeTokens[i-1];
                _genesisPool = genesisFactory.getGenesisPool(nativeToken);
                _poolStatus = IGenesisPool(_genesisPool).poolStatus();

                if(_poolStatus == PoolStatus.PRE_LISTING && IGenesisPool(_genesisPool).eligbleForDisqualify()){
                    IGenesisPool(_genesisPool).setPoolStatus(PoolStatus.NOT_QUALIFIED);
                    _removeLiveToken(nativeToken);
                }
                else if(_poolStatus == PoolStatus.PRE_LAUNCH){
                    IGenesisPool(_genesisPool).setPoolStatus(PoolStatus.PRE_LAUNCH_DEPOSIT_DISABLED);
                }
            }
            pre_epoch_period = BlackTimeLibrary.currPreEpoch(block.timestamp);
        }
    }

    // at epoch flip, PRE_LISTING -> PRE_LAUNCH (condition met) , PRE_LAUNCH_DDEPOSIT_DISBALED -> LAUNCH or PARTIALLY_LAUNCH
    function checkAtEpochFlip() external GenesisManager {
        // require(epochController == msg.sender, "NA");

        uint256 tokensCount = liveNativeTokens.length;

        // If no tokens or all processed, reset index and exit
        if (tokensCount == 0 || epochFlipProcessingIndex >= tokensCount) {
            epochFlipProcessingIndex = 0;
            return;
        }

        // Process one token at current index
        address nativeToken = liveNativeTokens[epochFlipProcessingIndex];
        address _genesisPool = genesisFactory.getGenesisPool(nativeToken);
        PoolStatus _poolStatus = IGenesisPool(_genesisPool).poolStatus();

        if (_poolStatus == PoolStatus.PRE_LISTING && IGenesisPool(_genesisPool).eligbleForPreLaunchPool()) {
            tokenHandler.whitelistToken(nativeToken);
            _preLaunchPool(_genesisPool);
            epochFlipProcessingIndex++;
        } else if (_poolStatus == PoolStatus.PRE_LAUNCH_DEPOSIT_DISABLED) {
            _launchPool(nativeToken, _genesisPool);
        } else {
            epochFlipProcessingIndex++;
        }
    }

    function processNextTokenPreEpoch() external GenesisManager {
        // require(epochController == msg.sender, "NA");

        uint _period = pre_epoch_period;
        if (block.timestamp < _period + WEEK) {
            return;
        }

        uint256 tokensCount = liveNativeTokens.length;

        // If no tokens or all processed, nothing to do here
        if (tokensCount == 0 || processingIndex >= tokensCount) {
            return;
        }

        // Process current token
        address nativeToken = liveNativeTokens[processingIndex];
        address _genesisPool = genesisFactory.getGenesisPool(nativeToken);
        PoolStatus _poolStatus = IGenesisPool(_genesisPool).poolStatus();

        if (_poolStatus == PoolStatus.PRE_LISTING && _eligibleForDisqualify(_genesisPool)) {
            IGenesisPool(_genesisPool).setPoolStatus(PoolStatus.NOT_QUALIFIED);
            _removeLiveToken(nativeToken);
        } else {
            if (_poolStatus == PoolStatus.PRE_LAUNCH) {
                IGenesisPool(_genesisPool).setPoolStatus(PoolStatus.PRE_LAUNCH_DEPOSIT_DISABLED);
            }
            processingIndex++;
        }
    }


    function finalizePreEpochIfReady() external GenesisManager {
        // require(epochController == msg.sender, "NA");

        uint _period = pre_epoch_period;
        if (block.timestamp < _period + WEEK) {
            revert("Epoch not ready to finalize");
        }

        if (liveNativeTokens.length == 0 || processingIndex >= liveNativeTokens.length) {
            pre_epoch_period = BlackTimeLibrary.currPreEpoch(block.timestamp);
            processingIndex = 0;
        } else {
            revert("Still processing tokens");
        }
    }


    function _eligibleForDisqualify(address _genesisPool) internal view returns (bool) {
        uint256 _endTime = IGenesisPool(_genesisPool).getGenesisInfo().startTime + IGenesisPool(_genesisPool).getGenesisInfo().duration;
        uint256 targetNativeAmount = (IGenesisPool(_genesisPool).getAllocationInfo().proposedNativeAmount * IGenesisPool(_genesisPool).getGenesisInfo().threshold) / 10000;
        return (_endTime - WEEK <= block.timestamp && IGenesisPool(_genesisPool).getAllocationInfo().allocatedNativeAmount < targetNativeAmount);
    }

    function _removeLiveToken(address nativeToken) internal {
        uint index = liveNativeTokensIndex[nativeToken]; // 1-based index
        uint length = liveNativeTokens.length;

        if (length > 0 && index >= 1 && index <= length) {
            uint arrayIndex = index - 1;
            address lastToken = liveNativeTokens[length - 1];

            // Replace the token to remove with the last token
            liveNativeTokens[arrayIndex] = lastToken;
            liveNativeTokens.pop();

            // Update index for the moved token (if not the same)
            if (nativeToken != lastToken) {
                liveNativeTokensIndex[lastToken] = index;
            }

            // Remove index mapping for removed token
            delete liveNativeTokensIndex[nativeToken];
        }
    }

    function setAuction(address _genesisPool, address _auction) external Governance {
        require(_genesisPool != address(0), "ZA");
        IGenesisPool(_genesisPool).setAuction(_auction);
    }

    function getAllNaitveTokens() external view returns (address[] memory) {
        return nativeTokens;
    }

    function getLiveNaitveTokens() external view returns (address[] memory) {
        return liveNativeTokens;
    }

    function setEpochController(address _epochController) external Governance {
        require(_epochController != address(0), "ZA");
        epochController = _epochController;
    }

    function setMinimumDuration(uint256 _duration) external Governance {
        MIN_DURATION = _duration;
    }

    function setMinimumThreshold(uint256 _threshold) external Governance {
        MIN_THRESHOLD = _threshold;
    }

    function setMaturityTime(uint256 _maturityTime) external Governance {
        MATURITY_TIME = _maturityTime;
    }

    function setMaturityTime(address _nativeToken, uint256 _maturityTime) external Governance {
        require(_nativeToken != address(0), "ZA");
        address genesisPool = genesisFactory.getGenesisPool(_nativeToken);
        require(genesisPool != address(0), "ZA");
        IGenesisPool(genesisPool).setMaturityTime(_maturityTime);
    }

    function setGenesisStartTime(address _nativeToken, uint256 _startTime) external Governance {
        require(_nativeToken != address(0), "ZA");
        address genesisPool = genesisFactory.getGenesisPool(_nativeToken);
        require(genesisPool != address(0), "ZA");
        IGenesisPool(genesisPool).setStartTime(_startTime);
    }

    function setRouter (address _router) external onlyOwner {
        require(_router != address(0), "ZA");
        router = _router;
    }

    function updateGenesisPoolStatus(address nativeToken, PoolStatus poolStatus) external GenesisManager {
        address _genesisPool = genesisFactory.getGenesisPool(nativeToken);
        require(_genesisPool != address(0), "ZA");
        IGenesisPool(_genesisPool).setPoolStatus(poolStatus);
        if (poolStatus == PoolStatus.NOT_QUALIFIED) {
            _removeLiveToken(nativeToken);
        }
        if (poolStatus == PoolStatus.PRE_LAUNCH_DEPOSIT_DISABLED) {
            tokenHandler.whitelistToken(nativeToken);
            _preLaunchPool(_genesisPool);
        }
        if (poolStatus == PoolStatus.LAUNCH) {
            _launchPool(nativeToken, _genesisPool);
        }
    }

    function version() external pure returns (string memory) {
        return "1.5.5";
    }
}"},"contracts/GlobalRouter.sol":{"content":"// SPDX-License-Identifier: MIT OR GPL-3.0-or-later
pragma solidity 0.8.13;

