pragma solidity 0.8.13;

library SignedSafeMath {
    int256 constant private _INT256_MIN = -2**255;

    /**
     * @dev Returns the multiplication of two signed integers, reverting on
     * overflow.
     *
     * Counterpart to Solidity's `*` operator.
     *
     * Requirements:
     *
     * - Multiplication cannot overflow.
     */
    function mul(int256 a, int256 b) internal pure returns (int256) {
        // Gas optimization: this is cheaper than requiring 'a' not being zero, but the
        // benefit is lost if 'b' is also tested.
        // See: https://github.com/OpenZeppelin/openzeppelin-contracts/pull/522
        if (a == 0) {
            return 0;
        }

        require(!(a == -1 && b == _INT256_MIN), "SignedSafeMath: multiplication overflow");

        int256 c = a * b;
        require(c / a == b, "SignedSafeMath: multiplication overflow");

        return c;
    }

    /**
     * @dev Returns the integer division of two signed integers. Reverts on
     * division by zero. The result is rounded towards zero.
     *
     * Counterpart to Solidity's `/` operator. Note: this function uses a
     * `revert` opcode (which leaves remaining gas untouched) while Solidity
     * uses an invalid opcode to revert (consuming all remaining gas).
     *
     * Requirements:
     *
     * - The divisor cannot be zero.
     */
    function div(int256 a, int256 b) internal pure returns (int256) {
        require(b != 0, "SignedSafeMath: division by zero");
        require(!(b == -1 && a == _INT256_MIN), "SignedSafeMath: division overflow");

        int256 c = a / b;

        return c;
    }

    /**
     * @dev Returns the subtraction of two signed integers, reverting on
     * overflow.
     *
     * Counterpart to Solidity's `-` operator.
     *
     * Requirements:
     *
     * - Subtraction cannot overflow.
     */
    function sub(int256 a, int256 b) internal pure returns (int256) {
        int256 c = a - b;
        require((b >= 0 && c <= a) || (b < 0 && c > a), "SignedSafeMath: subtraction overflow");

        return c;
    }

    /**
     * @dev Returns the addition of two signed integers, reverting on
     * overflow.
     *
     * Counterpart to Solidity's `+` operator.
     *
     * Requirements:
     *
     * - Addition cannot overflow.
     */
    function add(int256 a, int256 b) internal pure returns (int256) {
        int256 c = a + b;
        require((b >= 0 && c >= a) || (b < 0 && c < a), "SignedSafeMath: addition overflow");

        return c;
    }

    function toUInt256(int256 a) internal pure returns (uint256) {
        require(a >= 0, "Integer < 0");
        return uint256(a);
    }
}"},"contracts/libraries/VoterFactoryLib.sol":{"content":"// SPDX-License-Identifier: MIT OR GPL-3.0-or-later
pragma solidity 0.8.13;

library VoterFactoryLib {
    struct Data {
        address[] pairFactories;
        address[] gaugeFactories;
        mapping(address => bool) isFactory;
        mapping(address => bool) isGaugeFactory;
    }

    event AddPairFactories(address indexed pairfactory);
    event AddGaugeFactories(address indexed gaugefactory);
    event SetGaugeFactory(address indexed old, address indexed latest);
    event SetPairFactory(address indexed old, address indexed latest);


    function addPairFactory(Data storage self, address _pairFactory) external {
        require(_pairFactory != address(0) , 'addr0');
        require(!self.isFactory[_pairFactory], "fact");
        require(_pairFactory.code.length > 0, "!contract");
        self.pairFactories.push(_pairFactory);
        self.isFactory[_pairFactory] = true;
        emit AddPairFactories(_pairFactory);
    }

    function addGaugeFactory(Data storage self, address _gaugeFactory) external {
        require(_gaugeFactory != address(0) , 'addr0');
        require(!self.isGaugeFactory[_gaugeFactory], "gFact");
        require(_gaugeFactory.code.length > 0, "!contract");
        self.gaugeFactories.push(_gaugeFactory);
        self.isGaugeFactory[_gaugeFactory] = true;
        emit AddGaugeFactories(_gaugeFactory);
    }

    function replacePairFactory(Data storage self, address _pairFactory, uint256 _pos) external {
        require(_pairFactory != address(0), 'addr0');
        require(!self.isFactory[_pairFactory], 'fact');
        require(_pairFactory.code.length > 0, "!contract");
        address oldPF = self.pairFactories[_pos];
        self.isFactory[oldPF] = false;
        self.pairFactories[_pos] = _pairFactory;
        self.isFactory[_pairFactory] = true;

        emit SetPairFactory(oldPF, _pairFactory);
    }

    function replaceGaugeFactory(Data storage self, address _gaugeFactory, uint256 _pos) external {
        require(_gaugeFactory != address(0) , 'addr0');
        require(!self.isGaugeFactory[_gaugeFactory], 'gFact');
        require(_gaugeFactory.code.length > 0, "!contract");
        address oldGF = self.gaugeFactories[_pos];
        self.isGaugeFactory[oldGF] = false;
        self.gaugeFactories[_pos] = _gaugeFactory;
        self.isGaugeFactory[_gaugeFactory] = true;

        emit SetGaugeFactory(oldGF, _gaugeFactory);
    }

    function removePairFactory(Data storage self, uint256 _pos) external {
        address oldPF = self.pairFactories[_pos];
        require(self.isFactory[oldPF], "!exists");
        self.isFactory[oldPF] = false;
        self.pairFactories[_pos] = address(0);
        emit SetPairFactory(oldPF, address(0));
    }

    function removeGaugeFactory(Data storage self, uint256 _pos) external {
        address oldGF = self.gaugeFactories[_pos];
        require(self.isGaugeFactory[oldGF], "!exists");
        self.isGaugeFactory[oldGF] = false;
        self.gaugeFactories[_pos] = address(0);
        emit SetGaugeFactory(oldGF, address(0));
    }

}"},"contracts/libraries/VotingBalanceLogic.sol":{"content":"// SPDX-License-Identifier: MIT OR GPL-3.0-or-later
pragma solidity ^0.8.13;

import {IVotingEscrow} from "../interfaces/IVotingEscrow.sol";
import {BlackTimeLibrary} from "./BlackTimeLibrary.sol";

library VotingBalanceLogic {

    struct Data {
        mapping(uint => IVotingEscrow.Point) point_history;
        mapping(uint => uint) user_point_epoch;
        mapping(uint => IVotingEscrow.Point[1000000000]) user_point_history; // user -> Point[user_epoch]
    }

    /// @notice Get the current voting power for `_tokenId`
    /// @dev Adheres to the ERC20 `balanceOf` interface for Aragon compatibility
    /// @param _tokenId NFT for lock
    /// @param _t Epoch time to return voting power at
    /// @return User voting power
    function balanceOfNFT(uint _tokenId, uint _t, 
        Data storage VotingBalanceLogicData
        ) external view returns (uint) {
        uint _epoch = VotingBalanceLogicData.user_point_epoch[_tokenId];
        if (_epoch == 0) {
            return 0;
        } else {
            uint userEpoch = getPastUserPointIndex(_epoch, _tokenId, _t, VotingBalanceLogicData);
            IVotingEscrow.Point memory last_point = VotingBalanceLogicData.user_point_history[_tokenId][userEpoch];
            if (last_point.smNFT != 0){
                return last_point.smNFT + last_point.smNFTBonus;
            }
            else if (last_point.permanent != 0) {
                return last_point.permanent;
            }
            else {
                last_point.bias -= last_point.slope * int128(int256(_t) - int256(last_point.ts));
                if (last_point.bias < 0) {
                    last_point.bias = 0;
                }
                return uint(int256(last_point.bias));
            }
        }
    }


    function getPastUserPointIndex(uint _epoch, 
    uint _tokenId,
    uint _t,
    Data storage votingBalanceLogicData
    ) internal view returns (uint256){
        uint lower = 0;
        uint upper = _epoch;
        while (upper > lower) {
            uint center = upper - (upper - lower) / 2; // ceil, avoiding overflow
            IVotingEscrow.Point memory userPoint = votingBalanceLogicData.user_point_history[_tokenId][center];
            if (userPoint.ts == _t) {
                return center;
            } else if (userPoint.ts < _t) {
                lower = center;
            } else {
                upper = center - 1;
            }
        }
        return lower;
    }

    /// @notice Measure voting power of `_tokenId` at block height `_block`
    /// @dev Adheres to MiniMe `balanceOfAt` interface: https://github.com/Giveth/minime
    /// @param _tokenId User's wallet NFT
    /// @param _block Block to calculate the voting power at
    /// @return Voting power
    function balanceOfAtNFT(uint _tokenId, 
        uint _block,
        Data storage VotingBalanceLogicData,
        uint epoch
        ) external view returns (uint) {
        // Copying and pasting totalSupply code because Vyper cannot pass by
        // reference yet
        assert(_block <= block.number);

        // Binary search
        uint _min = 0;
        uint _max = VotingBalanceLogicData.user_point_epoch[_tokenId];
        for (uint i = 0; i < 128; ++i) {
            // Will be always enough for 128-bit numbers
            if (_min >= _max) {
                break;
            }
            uint _mid = (_min + _max + 1) / 2;
            if (VotingBalanceLogicData.user_point_history[_tokenId][_mid].blk <= _block) {
                _min = _mid;
            } else {
                _max = _mid - 1;
            }
        }

        IVotingEscrow.Point memory upoint = VotingBalanceLogicData.user_point_history[_tokenId][_min];

        if (upoint.permanent > 0){
            return upoint.permanent;
        }
        else if(upoint.smNFT > 0){
            return upoint.smNFT + upoint.smNFTBonus;
        }

        uint max_epoch = epoch;
        uint _epoch = _find_block_epoch(_block, max_epoch, VotingBalanceLogicData);
        IVotingEscrow.Point memory point_0 = VotingBalanceLogicData.point_history[_epoch];
        uint d_block = 0;
        uint d_t = 0;
        if (_epoch < max_epoch) {
            IVotingEscrow.Point memory point_1 = VotingBalanceLogicData.point_history[_epoch + 1];
            d_block = point_1.blk - point_0.blk;
            d_t = point_1.ts - point_0.ts;
        } else {
            d_block = block.number - point_0.blk;
            d_t = block.timestamp - point_0.ts;
        }
        uint block_time = point_0.ts;
        if (d_block != 0) {
            block_time += (d_t * (_block - point_0.blk)) / d_block;
        }

        upoint.bias -= upoint.slope * int128(int256(block_time - upoint.ts));
        if (upoint.bias >= 0) {
            return uint(uint128(upoint.bias));
        } else {
            return 0;
        }
    }

    function totalSupplyAt(uint _block, uint epoch,
        Data storage VotingBalanceLogicData,
        mapping(uint => int128) storage slope_changes) public view returns (uint) {
        assert(_block <= block.number);
        uint _epoch = epoch;
        uint target_epoch = _find_block_epoch(_block, _epoch, VotingBalanceLogicData);

        IVotingEscrow.Point memory point = VotingBalanceLogicData.point_history[target_epoch];
        uint dt = 0;
        if (target_epoch < _epoch) {
            IVotingEscrow.Point memory point_next = VotingBalanceLogicData.point_history[target_epoch + 1];
            if (point.blk != point_next.blk) {
                dt = ((_block - point.blk) * (point_next.ts - point.ts)) / (point_next.blk - point.blk);
            }
        } else {
            if (point.blk != block.number) {
                dt = ((_block - point.blk) * (block.timestamp - point.ts)) / (block.number - point.blk);
            }
        }
        // Now dt contains info on how far are we beyond point
        return _supply_at(point, point.ts + dt, slope_changes);

    }

         /// @notice Binary search to estimate timestamp for block number
    /// @param _block Block to find
    /// @param max_epoch Don't go beyond this epoch
    /// @return Approximate timestamp for block
    function _find_block_epoch(uint _block, 
        uint max_epoch,
        Data storage VotingBalanceLogicData
        ) internal view returns (uint) {
        // Binary search
        uint _min = 0;
        uint _max = max_epoch;
        for (uint i = 0; i < 128; ++i) {
            // Will be always enough for 128-bit numbers
            if (_min >= _max) {
                break;
            }
            uint _mid = (_min + _max + 1) / 2;
            if (VotingBalanceLogicData.point_history[_mid].blk <= _block) {
                _min = _mid;
            } else {
                _max = _mid - 1;
            }
        }
        return _min;
    }

    /// @notice Calculate total voting power at some point in the past
    /// @param point The point (bias/slope) to start search from
    /// @param t Time to calculate the total voting power at
    /// @return Total voting power at that time
    function _supply_at(IVotingEscrow.Point memory point, 
        uint t,
        mapping(uint => int128) storage slope_changes) internal view returns (uint) {
        uint WEEK = BlackTimeLibrary.WEEK;
        IVotingEscrow.Point memory last_point = point;
        uint t_i = (last_point.ts / WEEK) * WEEK;
        for (uint i = 0; i < 255; ++i) {
            t_i += WEEK;
            int128 d_slope = 0;
            if (t_i > t) {
                t_i = t;
            } else {
                d_slope = slope_changes[t_i];
            }
            last_point.bias -= last_point.slope * int128(int256(t_i - last_point.ts));
            if (t_i == t) {
                break;
            }
            last_point.slope += d_slope;
            last_point.ts = t_i;
        }

        if (last_point.bias < 0) {
            last_point.bias = 0;
        }
        return uint(uint128(last_point.bias)) + last_point.permanent + last_point.smNFT + last_point.smNFTBonus;
    }

    function getPastGlobalPointIndex(uint _epoch,
        uint _t,
        Data storage VotingBalanceLogicData) internal view returns (uint256){
        uint lower = 0;
        uint upper = _epoch;
        while (upper > lower) {
            uint center = upper - (upper - lower) / 2; // ceil, avoiding overflow
            IVotingEscrow.Point memory point = VotingBalanceLogicData.point_history[center];
            if (point.ts == _t) {
                return center;
            } else if (point.ts < _t) {
                lower = center;
            } else {
                upper = center - 1;
            }
        }
        return lower;
    }

        /// @notice Calculate total voting power
    /// @dev Adheres to the ERC20 `totalSupply` interface for Aragon compatibility
    /// @return Total voting power
    function totalSupplyAtT(uint t, uint epoch,
        mapping(uint => int128) storage slope_changes,
        Data storage VotingBalanceLogicData) external view returns (uint) {
        uint _epoch = epoch;
        if(_epoch == 0) {
            return 0;
        } else {
            uint globalEpoch = getPastGlobalPointIndex(_epoch, t, VotingBalanceLogicData);
            IVotingEscrow.Point memory last_point = VotingBalanceLogicData.point_history[globalEpoch];
            return _supply_at(last_point, t, slope_changes);
        }
    }
}"},"contracts/libraries/VotingDelegationLib.sol":{"content":"// SPDX-License-Identifier: MIT OR GPL-3.0-or-later
pragma solidity ^0.8.13;


library VotingDelegationLib {
    /// @notice A checkpoint for marking delegated tokenIds from a given timestamp
    struct Checkpoint {
        uint timestamp;
        uint[] tokenIds;
    }

    // A struct that holds all checkpoint data for different accounts.
    // The calling contract will include one instance of this struct in storage.
    struct Data {
        // For each account, store a mapping from checkpoint index to Checkpoint.
        mapping(address => mapping(uint32 => Checkpoint)) checkpoints;
        // For each account, store the number of checkpoints.
        mapping(address => uint32) numCheckpoints;
    }

    struct TokenHelpers {
        function(uint) view returns (address) ownerOfFn;
        function(address) view returns (uint) ownerToNFTokenCountFn;
        function(address, uint) view returns (uint) tokenOfOwnerByIndex;
    }

    uint public constant MAX_DELEGATES = 1024; // avoid too much gas
    /**
     * @notice Returns the checkpoint index to write for an account.
     * If the most recent checkpoint was created in the current timestamp, returns that index.
     * Otherwise, returns the current number of checkpoints (i.e. a new checkpoint index).
     */
    function findCheckpointToWrite(
        Data storage self,
        address account,
        uint256 currentTimestamp
    ) internal view returns (uint32) {
        uint32 n = self.numCheckpoints[account];
        if (n > 0 && self.checkpoints[account][n - 1].timestamp == currentTimestamp) {
            return n - 1;
        } else {
            return n;
        }
    }

    function moveTokenDelegates(
        Data storage self,
        address srcRep,
        address dstRep,
        uint _tokenId,
        function(uint) view returns (address) ownerOfFn
    ) internal {
        if (srcRep != dstRep && _tokenId > 0) {
            if (srcRep != address(0)) {
                uint32 srcRepNum = self.numCheckpoints[srcRep];
                uint[] storage srcRepOld = srcRepNum > 0
                    ? self.checkpoints[srcRep][srcRepNum - 1].tokenIds
                    : self.checkpoints[srcRep][0].tokenIds;
                uint32 nextSrcRepNum = findCheckpointToWrite(self, srcRep, block.timestamp);
                bool _isCheckpointInNewBlock = (srcRepNum > 0) ? (nextSrcRepNum != srcRepNum - 1) : true;
                Checkpoint storage cpSrcRep = self.checkpoints[srcRep][nextSrcRepNum];
                uint[] storage srcRepNew = cpSrcRep.tokenIds;
                cpSrcRep.timestamp = block.timestamp;
                // All the same except _tokenId
                uint256 length = srcRepOld.length;
                for (uint i = 0; i < length;) {
                    uint tId = srcRepOld[i];
                    if(_isCheckpointInNewBlock) {
                        if(ownerOfFn(tId) == srcRep) {
                            srcRepNew.push(tId);
                        }
                        i++;
                    } else {
                        if(ownerOfFn(tId) != srcRep) {
                            srcRepNew[i] = srcRepNew[length -1];
                            srcRepNew.pop();
                            length--;
                        } else {
                            i++;
                        }
                    }
                }
                self.numCheckpoints[srcRep] = nextSrcRepNum + 1;   
            }

            if (dstRep != address(0)) {
                uint32 dstRepNum = self.numCheckpoints[dstRep];
                uint[] storage dstRepOld = dstRepNum > 0
                    ? self.checkpoints[dstRep][dstRepNum - 1].tokenIds
                    : self.checkpoints[dstRep][0].tokenIds;
                uint32 nextDstRepNum = findCheckpointToWrite(self, dstRep, block.timestamp);
                bool _isCheckpointInNewBlock = (dstRepNum > 0) ? (nextDstRepNum != dstRepNum - 1) : true;
                Checkpoint storage cpDstRep = self.checkpoints[dstRep][nextDstRepNum];
                uint[] storage dstRepNew = cpDstRep.tokenIds;
                cpDstRep.timestamp = block.timestamp;
                require(
                    dstRepOld.length + 1 <= MAX_DELEGATES,
                    "tokens>1"
                );
                if(_isCheckpointInNewBlock) {
                    for (uint i = 0; i < dstRepOld.length; i++) {
                        uint tId = dstRepOld[i];
                        dstRepNew.push(tId);
                    }
                }
                dstRepNew.push(_tokenId);
                self.numCheckpoints[dstRep] = nextDstRepNum + 1;
            }
        }
    }

    function _moveAllDelegates(
        Data storage self,
        address owner,
        address srcRep,
        address dstRep,
        TokenHelpers memory tokenHelpers
    ) internal {
        // You can only redelegate what you own
        address _owner = owner;
        Data storage _self = self;
        address _srcRep = srcRep;
        address _dstRep = dstRep;
        TokenHelpers memory _tokenHelper = tokenHelpers;
        if (_srcRep != _dstRep) {
            if (_srcRep != address(0)) {
                uint32 srcRepNum = _self.numCheckpoints[_srcRep];
                uint[] storage srcRepOld = srcRepNum > 0
                    ? _self.checkpoints[_srcRep][srcRepNum - 1].tokenIds
                    : _self.checkpoints[_srcRep][0].tokenIds;
                uint32 nextSrcRepNum = findCheckpointToWrite(_self,_srcRep, block.timestamp);
                bool _isCheckpointInNewBlock = (srcRepNum > 0) ? (nextSrcRepNum != srcRepNum - 1) : true;
                // if(_isCheckpointInNewBlock) {
                Checkpoint storage cpSrcRep = _self.checkpoints[_srcRep][nextSrcRepNum];
                uint[] storage srcRepNew = cpSrcRep.tokenIds;
                cpSrcRep.timestamp = block.timestamp;

                uint256 length = srcRepOld.length;
                for (uint i = 0; i < length;) {
                    uint tId = srcRepOld[i];
                    if(_isCheckpointInNewBlock) {
                        if(_tokenHelper.ownerOfFn(tId) != _owner) {
                            srcRepNew.push(tId);
                        }
                        i++;
                    } else {
                        if(_tokenHelper.ownerOfFn(tId) == _owner) {
                            srcRepNew[i] = srcRepNew[length -1];
                            srcRepNew.pop();
                            length--;
                        } else {
                            i++;
                        }
                    }
                }
                _self.numCheckpoints[_srcRep] = nextSrcRepNum + 1;
            }


            if (_dstRep != address(0)) {
                uint32 dstRepNum = _self.numCheckpoints[_dstRep];
                uint[] storage dstRepOld = dstRepNum > 0
                    ? _self.checkpoints[_dstRep][dstRepNum - 1].tokenIds
                    : _self.checkpoints[_dstRep][0].tokenIds;
                uint32 nextDstRepNum = findCheckpointToWrite(_self,_dstRep, block.timestamp);
                bool _isCheckpointInNewBlock = (dstRepNum > 0) ? (nextDstRepNum != dstRepNum - 1) : true;
                Checkpoint storage cpDstRep = _self.checkpoints[_dstRep][nextDstRepNum];
                uint[] storage dstRepNew = cpDstRep.tokenIds;
                cpDstRep.timestamp = block.timestamp;
                uint ownerTokenCount = _tokenHelper.ownerToNFTokenCountFn(_owner);
                require(
                    dstRepOld.length + ownerTokenCount <= MAX_DELEGATES,
                    "tokens>1"
                );
                if(_isCheckpointInNewBlock) {
                    for (uint i = 0; i < dstRepOld.length; i++) {
                        uint tId = dstRepOld[i];
                        dstRepNew.push(tId);
                    }
                }
                // Plus all that's owned
                for (uint i = 0; i < ownerTokenCount; i++) {
                    uint tId = _tokenHelper.tokenOfOwnerByIndex(_owner,i);
                    dstRepNew.push(tId);
                }
                _self.numCheckpoints[_dstRep] = nextDstRepNum + 1;   
            }
        }
    }

    function getPastVotesIndex(Data storage data, address account, uint timestamp) internal view returns (uint32) {
        uint32 nCheckpoints = data.numCheckpoints[account];
        if (nCheckpoints == 0) {
            return 0;
        }
        // First check most recent balance
        if (data.checkpoints[account][nCheckpoints - 1].timestamp <= timestamp) {
            return (nCheckpoints - 1);
        }

        // Next check implicit zero balance
        if (data.checkpoints[account][0].timestamp > timestamp) {
            return 0;
        }

        uint32 lower = 0;
        uint32 upper = nCheckpoints - 1;
        while (upper > lower) {
            uint32 center = upper - (upper - lower) / 2; // ceil, avoiding overflow
            VotingDelegationLib.Checkpoint storage cp = data.checkpoints[account][center];
            if (cp.timestamp == timestamp) {
                return center;
            } else if (cp.timestamp < timestamp) {
                lower = center;
            } else {
                upper = center - 1;
            }
        }
        return lower;
    }

}"},"contracts/MinterUpgradeable.sol":{"content":"// SPDX-License-Identifier: GPL-3.0-or-later
pragma solidity 0.8.13;

import "./libraries/Math.sol";
import "./interfaces/IMinter.sol";
import "./interfaces/IRewardsDistributor.sol";
import "./interfaces/IBlack.sol";
import "./interfaces/IGaugeManager.sol";
import "./interfaces/IVotingEscrow.sol";

import { IBlackGovernor } from "./interfaces/IBlackGovernor.sol";

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import {BlackTimeLibrary} from "./libraries/BlackTimeLibrary.sol";

// codifies the minting rules as per ve(3,3), abstracted from the token to support any token that allows minting
// 14 increment epochs followed by 52 decrement epochs after which we wil have vote based epochs

contract MinterUpgradeable is IMinter, OwnableUpgradeable {

    bool public isFirstMint;

    uint public teamRate;  //EMISSION that goes to protocol
    uint public constant MAX_TEAM_RATE = 500; // 5%
    uint256 public constant TAIL_START = 67; //TAIL EMISSIONS
    uint256 public tailEmissionRate; 
    uint256 public constant NUDGE = 1; //delta added in tail emissions rate after voting
    uint256 public constant MAXIMUM_TAIL_RATE = 100; //maximum tail emissions rate after voting
    uint256 public constant MINIMUM_TAIL_RATE = 1; //maximum tail emissions rate after voting
    uint256 public constant MAX_BPS = 10_000; 
    uint256 public constant WEEKLY_DECAY = 9_900; //for epoch 15 to 66 growth
    uint256 public constant WEEKLY_GROWTH = 10_300; //for epoch 1 to 14 growth
    uint256 public constant PROPOSAL_INCREASE = 10_100; // 1% increment after the 67th epoch based on proposal
    uint256 public constant PROPOSAL_DECREASE = 9_900; // 1% increment after the 67th epoch based on proposal

    uint public WEEK; // allows minting once per week (reset every Thursday 00:00 UTC)
    uint public weekly; // represents a starting weekly emission of 2.6M BLACK (BLACK has 18 decimals)
    uint public active_period;
    uint public LOCK;
    uint256 public epochCount;

    address internal _initializer;
    address public team;
    address public pendingTeam;

    IBlack public _black;
    IGaugeManager public _gaugeManager;
    IVotingEscrow public _ve;
    IRewardsDistributor public _rewards_distributor;
    address private burnTokenAddress;

    mapping(uint256 => bool) public proposals;

    event Mint(address indexed sender, uint weekly, uint circulating_supply, uint circulating_emission);

    constructor() {}

    function initialize(    
        address __gaugeManager, // distribution system
        address __ve, // the ve(3,3) system that will be locked into
        address __rewards_distributor // the distribution system that ensures users aren't diluted
    ) initializer public {
        __Ownable_init();

        _initializer = msg.sender;
        team = msg.sender;
        tailEmissionRate = MAX_BPS;
        teamRate = 500; // 500 bps = 5%
        WEEK = BlackTimeLibrary.WEEK;
        LOCK = BlackTimeLibrary.MAX_LOCK_DURATION;
        _black = IBlack(IVotingEscrow(__ve).token());
        _gaugeManager = IGaugeManager(__gaugeManager);
        _ve = IVotingEscrow(__ve);
        _rewards_distributor = IRewardsDistributor(__rewards_distributor);

        active_period = ((block.timestamp + (2 * WEEK)) / WEEK) * WEEK;
        weekly = 10_000_000 * 1e18; // represents a starting weekly emission of 10M BLACK (BLACK has 18 decimals)
        isFirstMint = true;

        burnTokenAddress=0x000000000000000000000000000000000000dEaD;
    }

    function _initialize(
        address[] memory claimants,
        uint[] memory amounts,
        uint max // sum amounts / max = % ownership of top protocols, so if initial 20m is distributed, and target is 25% protocol ownership, then max - 4 x 20m = 80m
    ) external {
        require(_initializer == msg.sender);
        if(max > 0){
            _black.mint(address(this), max);
            _black.approve(address(_ve), type(uint).max);
            for (uint i = 0; i < claimants.length; i++) {
                _ve.create_lock_for(amounts[i], LOCK, claimants[i], false);
            }
        }

        _initializer = address(0);
        active_period = ((block.timestamp) / WEEK) * WEEK; // allow minter.update_period() to mint new emissions THIS Thursday
    }

    function setTeam(address _team) external {
        require(msg.sender == team);
        pendingTeam = _team;
    }

    function acceptTeam() external {
        require(msg.sender == pendingTeam, "not pending team");
        team = pendingTeam;
    }

    function setGaugeManager(address __gaugeManager) external {
        require(__gaugeManager != address(0));
        require(msg.sender == team, "not team");
        _gaugeManager = IGaugeManager(__gaugeManager);
    }

    function setTeamRate(uint _teamRate) external {
        require(msg.sender == team, "not team");
        require(_teamRate <= MAX_TEAM_RATE, "rate too high");
        teamRate = _teamRate;
    }

    // calculate inflation and adjust ve balances accordingly
    function calculate_rebase(uint _weeklyMint) public view returns (uint) {
        uint _veTotal = IVotingEscrow(_ve).totalSupplyAtT(active_period - 1);
        uint _blackTotal = _black.totalSupply();
        uint _smNFTBalance = IVotingEscrow(_ve).smNFTBalance();
        uint _superMassiveBonus = IVotingEscrow(_ve).calculate_sm_nft_bonus(_smNFTBalance);

        uint blackSupply = _blackTotal + _smNFTBalance + _superMassiveBonus;
        uint256 rebaseAmount =  (((_weeklyMint * (blackSupply - _veTotal)) / blackSupply) * (blackSupply - _veTotal)) / blackSupply / 2;
        return rebaseAmount;
    }

    function nudge() external {
        address _epochGovernor = _gaugeManager.getBlackGovernor();
        require (msg.sender == _epochGovernor, "NA");
        IBlackGovernor.ProposalState _state = IBlackGovernor(_epochGovernor).status();
        require (epochCount >= TAIL_START);
        uint256 _period = active_period;
        require (!proposals[_period]);

        if (_state == IBlackGovernor.ProposalState.Succeeded) {
            tailEmissionRate = PROPOSAL_INCREASE;
        }
        else if(_state == IBlackGovernor.ProposalState.Defeated) {
            tailEmissionRate = PROPOSAL_DECREASE;
        } else  {
            tailEmissionRate = 10000;
        }
        proposals[_period] = true;
    }


    // update period can only be called once per cycle (1 week)
    function update_period() external returns (uint) {
        uint _period = active_period;
        if (block.timestamp >= _period + WEEK && _initializer == address(0)) { // only trigger if new week
            epochCount++;
            _period = (block.timestamp / WEEK) * WEEK;
            active_period = _period;
            uint256 _weekly = weekly;
            uint256 _emission;
            bool _tail = epochCount > TAIL_START;

            if (_tail) {
                _emission = (_weekly * tailEmissionRate) / MAX_BPS;
                weekly = _emission;
            } else {
                _emission = _weekly;
                if (epochCount < 15) {
                    _weekly = (_weekly * WEEKLY_GROWTH) / MAX_BPS;
                } else {
                    _weekly = (_weekly * WEEKLY_DECAY) / MAX_BPS;
                }
                weekly = _weekly;
            }

            tailEmissionRate = MAX_BPS;

            uint _rebase = calculate_rebase(_emission);

            uint _teamEmissions = _emission * teamRate / MAX_BPS;

            uint _gauge = _emission - _rebase - _teamEmissions;

            uint _balanceOf = _black.balanceOf(address(this));
            if (_balanceOf < _emission) {
                _black.mint(address(this), _emission - _balanceOf);
            }

            require(_black.transfer(team, _teamEmissions));

            require(_black.transfer(address(_rewards_distributor), _rebase));
            _rewards_distributor.checkpoint_token(); // checkpoint token balance that was just minted in rewards distributor

            _black.approve(address(_gaugeManager), _gauge);
            _gaugeManager.notifyRewardAmount(_gauge);

            emit Mint(msg.sender, _emission, _rebase, circulating_supply());
        }
        return _period;
    }

    function circulating_supply() public view returns (uint) {
        return _black.totalSupply() - _black.balanceOf(address(_ve)) - _black.balanceOf(address(burnTokenAddress));
    }

    function check() external view returns(bool){
        uint _period = active_period;
        return (block.timestamp >= _period + WEEK && _initializer == address(0));
    }

    function period() external view returns(uint){
        return(block.timestamp / WEEK) * WEEK;
    }
    function setRewardDistributor(address _rewardDistro) external {
        require(msg.sender == team);
        _rewards_distributor = IRewardsDistributor(_rewardDistro);
    }

    function version() external view returns (string memory version) {
        version  = "MinterUpgradable v1.1.2";
    }
}
"},"contracts/Pair.sol":{"content":"// SPDX-License-Identifier: MIT OR GPL-3.0-or-later
pragma solidity 0.8.13;

import './libraries/Math.sol';
import './interfaces/IERC20.sol';
import './interfaces/IPair.sol';
import './interfaces/IDibs.sol';
import './interfaces/IPairCallee.sol';
import './factories/PairFactory.sol';
import './PairFees.sol';


// The base pair of pools, either stable or volatile
contract Pair is IPair {

    string public name;
    string public symbol;
    uint8 public constant decimals = 18;

    // Used to denote stable or volatile pair, not immutable since construction happens in the initialize method for CREATE2 deterministic addresses
    bool public immutable stable;

    uint public totalSupply = 0;

    mapping(address => mapping (address => uint)) public allowance;
    mapping(address => uint) public balanceOf;

    bytes32 internal DOMAIN_SEPARATOR;
    // keccak256("Permit(address owner,address spender,uint256 value,uint256 nonce,uint256 deadline)");
    bytes32 internal constant PERMIT_TYPEHASH = 0x6e71edae12b1b97f4d1f60370fef10105fa2faae0126114a169c64845d6126c9;
    mapping(address => uint) public nonces;

    uint internal constant MINIMUM_LIQUIDITY = 10**3;
    uint256 internal constant MINIMUM_K = 10 ** 10;

    address public immutable token0;
    address public immutable token1;
    address public immutable fees;
    address immutable factory;

    // Structure to capture time period obervations every 30 minutes, used for local oracles
    struct Observation {
        uint timestamp;
        uint reserve0Cumulative;
        uint reserve1Cumulative;
    }

    // Capture oracle reading every 30 minutes
    uint constant periodSize = 1800;

    Observation[] public observations;

    uint internal immutable decimals0;
    uint internal immutable decimals1;

    uint public reserve0;
    uint public reserve1;
    uint public blockTimestampLast;

    uint public reserve0CumulativeLast;
    uint public reserve1CumulativeLast;

    // index0 and index1 are used to accumulate fees, this is split out from normal trades to keep the swap "clean"
    // this further allows LP holders to easily claim fees for tokens they have/staked
    uint public index0 = 0;
    uint public index1 = 0;

    // position assigned to each LP to track their current index0 & index1 vs the global position
    mapping(address => uint) public supplyIndex0;
    mapping(address => uint) public supplyIndex1;

    // tracks the amount of unclaimed, but claimable tokens off of fees for token0 and token1
    mapping(address => uint) public claimable0;
    mapping(address => uint) public claimable1;

    event Fees(address indexed sender, uint amount0, uint amount1);
    event Mint(address indexed sender, uint amount0, uint amount1);
    event Burn(address indexed sender, uint amount0, uint amount1, address indexed to);
    event Swap(
        address indexed sender,
        uint amount0In,
        uint amount1In,
        uint amount0Out,
        uint amount1Out,
        address indexed to
    );
    event Sync(uint reserve0, uint reserve1);
    event Claim(address indexed sender, address indexed recipient, uint amount0, uint amount1);

    event Transfer(address indexed from, address indexed to, uint amount);
    event Approval(address indexed owner, address indexed spender, uint amount);

    constructor(address _factory, address _token0, address _token1, bool _stable) {
        factory = _factory;
        (token0, token1, stable) = (_token0, _token1, _stable);
        fees = address(new PairFees(_token0, _token1));
        if (_stable) {
            name = string(abi.encodePacked("StableV1 AMM - ", IERC20(_token0).symbol(), "/", IERC20(_token1).symbol()));
            symbol = string(abi.encodePacked("sAMM-", IERC20(_token0).symbol(), "/", IERC20(_token1).symbol()));
        } else {
            name = string(abi.encodePacked("VolatileV1 AMM - ", IERC20(_token0).symbol(), "/", IERC20(_token1).symbol()));
            symbol = string(abi.encodePacked("vAMM-", IERC20(_token0).symbol(), "/", IERC20(_token1).symbol()));
        }

        decimals0 = 10**IERC20(_token0).decimals();
        decimals1 = 10**IERC20(_token1).decimals();

        observations.push(Observation(block.timestamp, 0, 0));
    }

    // simple re-entrancy check
    uint internal _unlocked = 1;
    modifier lock() {
        require(_unlocked == 1, "LOCKED");
        _unlocked = 2;
        _;
        _unlocked = 1;
    }

    function observationLength() external view returns (uint) {
        return observations.length;
    }

    function lastObservation() public view returns (Observation memory) {
        return observations[observations.length-1];
    }

    function metadata() external view returns (uint dec0, uint dec1, uint r0, uint r1, bool st, address t0, address t1) {
        return (decimals0, decimals1, reserve0, reserve1, stable, token0, token1);
    }

    function tokens() external view returns (address, address) {
        return (token0, token1);
    }

    function isStable() external view returns(bool) {
        return stable;
    }

    // claim accumulated but unclaimed fees (viewable via claimable0 and claimable1)
    function claimFees() external returns (uint claimed0, uint claimed1) {
        _updateFor(msg.sender);

        claimed0 = claimable0[msg.sender];
        claimed1 = claimable1[msg.sender];

        if (claimed0 > 0 || claimed1 > 0) {
            claimable0[msg.sender] = 0;
            claimable1[msg.sender] = 0;

            PairFees(fees).claimFeesFor(msg.sender, claimed0, claimed1);

            emit Claim(msg.sender, msg.sender, claimed0, claimed1);
        }
    }

    function claimStakingFees() external {
        address _feehandler = PairFactory(factory).stakingFeeHandler();
        PairFees(fees).withdrawStakingFees(_feehandler);
    }

    // Accrue fees on token0
    function _update0(uint amount) internal {
        // get referral fee
        address _dibs = PairFactory(factory).dibs();
        uint256 _maxRef = PairFactory(factory).getReferralFee(address(this));
        uint256 _referralFee = (_dibs != address(0)) ? (amount * _maxRef / 10000) : 0;
        if (_referralFee > 0) {
            _safeTransfer(token0, _dibs, _referralFee); // Transfer referral fees
            amount -= _referralFee;
        }
        // get lp and staking fee
        uint256 _stakingNftFee =  amount * PairFactory(factory).stakingNFTFee() / 10000;
        PairFees(fees).processStakingFees(_stakingNftFee, true);
        _safeTransfer(token0, fees, amount); // transfer the fees out to PairFees


        // remove staking fees from lpfees
        amount -= _stakingNftFee;
        uint256 _ratio = amount * 1e18 / totalSupply; // 1e18 adjustment is removed during claim
        if (_ratio > 0) {
            index0 += _ratio;
        }
        emit Fees(msg.sender, amount+_stakingNftFee+_referralFee, 0);
    }

    // Accrue fees on token1
    function _update1(uint amount) internal {
        // get referral fee
        address _dibs = PairFactory(factory).dibs();
        uint256 _maxRef = PairFactory(factory).getReferralFee(address(this));
        uint256 _referralFee = (_dibs != address(0)) ? (amount * _maxRef / 10000) : 0;
         if (_referralFee > 0) {
             _safeTransfer(token1, _dibs, _referralFee); // transfer the fees out to PairFees
            amount -= _referralFee;
         }
        // get lp and staking fee
        uint256 _stakingNftFee =  amount * PairFactory(factory).stakingNFTFee() / 10000;
        PairFees(fees).processStakingFees(_stakingNftFee, false);
        _safeTransfer(token1, fees, amount); // transfer the fees out to PairFees

        // remove staking fees from lpfees
        amount -= _stakingNftFee;

        uint256 _ratio = amount * 1e18 / totalSupply;

        if (_ratio > 0) {
            index1 += _ratio;
        }

        emit Fees(msg.sender, 0,  amount+_stakingNftFee+_referralFee);
    }

    // this function MUST be called on any balance changes, otherwise can be used to infinitely claim fees
    // Fees are segregated from core funds, so fees can never put liquidity at risk
    function _updateFor(address recipient) internal {
        uint _supplied = balanceOf[recipient]; // get LP balance of `recipient`
        if (_supplied > 0) {
            uint _supplyIndex0 = supplyIndex0[recipient]; // get last adjusted index0 for recipient
            uint _supplyIndex1 = supplyIndex1[recipient];
            uint _index0 = index0; // get global index0 for accumulated fees
            uint _index1 = index1;
            supplyIndex0[recipient] = _index0; // update user current position to global position
            supplyIndex1[recipient] = _index1;
            uint _delta0 = _index0 - _supplyIndex0; // see if there is any difference that need to be accrued
            uint _delta1 = _index1 - _supplyIndex1;
            if (_delta0 > 0) {
                uint _share = _supplied * _delta0 / 1e18; // add accrued difference for each supplied token
                claimable0[recipient] += _share;
            }
            if (_delta1 > 0) {
                uint _share = _supplied * _delta1 / 1e18;
                claimable1[recipient] += _share;
            }
        } else {
            supplyIndex0[recipient] = index0; // new users are set to the default global state
            supplyIndex1[recipient] = index1;
        }
    }

    function getReserves() public view returns (uint _reserve0, uint _reserve1, uint _blockTimestampLast) {
        _reserve0 = reserve0;
        _reserve1 = reserve1;
        _blockTimestampLast = blockTimestampLast;
    }

    // update reserves and, on the first call per block, price accumulators
    function _update(uint balance0, uint balance1, uint _reserve0, uint _reserve1) internal {
        uint blockTimestamp = block.timestamp;
        uint timeElapsed = blockTimestamp - blockTimestampLast; // overflow is desired
        if (timeElapsed > 0 && _reserve0 != 0 && _reserve1 != 0) {
            reserve0CumulativeLast += _reserve0 * timeElapsed;
            reserve1CumulativeLast += _reserve1 * timeElapsed;
        }

        Observation memory _point = lastObservation();
        timeElapsed = blockTimestamp - _point.timestamp; // compare the last observation with current timestamp, if greater than 30 minutes, record a new event
        if (timeElapsed > periodSize) {
            observations.push(Observation(blockTimestamp, reserve0CumulativeLast, reserve1CumulativeLast));
        }
        reserve0 = balance0;
        reserve1 = balance1;
        blockTimestampLast = blockTimestamp;
        emit Sync(reserve0, reserve1);
    }

    // produces the cumulative price using counterfactuals to save gas and avoid a call to sync.
    function currentCumulativePrices() public view returns (uint reserve0Cumulative, uint reserve1Cumulative, uint blockTimestamp) {
        blockTimestamp = block.timestamp;
        reserve0Cumulative = reserve0CumulativeLast;
        reserve1Cumulative = reserve1CumulativeLast;

        // if time has elapsed since the last update on the pair, mock the accumulated price values
        (uint _reserve0, uint _reserve1, uint _blockTimestampLast) = getReserves();
        if (_blockTimestampLast != blockTimestamp) {
            // subtraction overflow is desired
            uint timeElapsed = blockTimestamp - _blockTimestampLast;
            reserve0Cumulative += _reserve0 * timeElapsed;
            reserve1Cumulative += _reserve1 * timeElapsed;
        }
    }

    // gives the current twap price measured from amountIn * tokenIn gives amountOut
    function current(address tokenIn, uint amountIn) external view returns (uint amountOut) {
        Observation memory _observation = lastObservation();
        (uint reserve0Cumulative, uint reserve1Cumulative,) = currentCumulativePrices();
        if (block.timestamp == _observation.timestamp) {
            _observation = observations[observations.length-2];
        }

        uint timeElapsed = block.timestamp - _observation.timestamp;
        uint _reserve0 = (reserve0Cumulative - _observation.reserve0Cumulative) / timeElapsed;
        uint _reserve1 = (reserve1Cumulative - _observation.reserve1Cumulative) / timeElapsed;
        amountOut = _getAmountOut(amountIn, tokenIn, _reserve0, _reserve1);
    }

    // as per `current`, however allows user configured granularity, up to the full window size
    function quote(address tokenIn, uint amountIn, uint granularity) external view returns (uint amountOut) {
        uint [] memory _prices = sample(tokenIn, amountIn, granularity, 1);
        uint priceAverageCumulative;
        for (uint i = 0; i < _prices.length; i++) {
            priceAverageCumulative += _prices[i];
        }
        return priceAverageCumulative / granularity;
    }

    // returns a memory set of twap prices
    function prices(address tokenIn, uint amountIn, uint points) external view returns (uint[] memory) {
        return sample(tokenIn, amountIn, points, 1);
    }

    function sample(address tokenIn, uint amountIn, uint points, uint window) public view returns (uint[] memory) {
        uint[] memory _prices = new uint[](points);

        uint length = observations.length-1;
        uint i = length - (points * window);
        uint nextIndex = 0;
        uint index = 0;

        for (; i < length; i+=window) {
            nextIndex = i + window;
            uint timeElapsed = observations[nextIndex].timestamp - observations[i].timestamp;
            uint _reserve0 = (observations[nextIndex].reserve0Cumulative - observations[i].reserve0Cumulative) / timeElapsed;
            uint _reserve1 = (observations[nextIndex].reserve1Cumulative - observations[i].reserve1Cumulative) / timeElapsed;
            _prices[index] = _getAmountOut(amountIn, tokenIn, _reserve0, _reserve1);
            // index < length; length cannot overflow
            unchecked {
                index = index + 1;
            }
        }
        return _prices;
    }

    // this low-level function should be called by addLiquidity functions in Router.sol, which performs important safety checks
    // standard uniswap v2 implementation
    function mint(address to) external lock returns (uint liquidity) {
        require(!(PairFactory(factory).isGenesis(address(this)) && totalSupply == 0), "GENESIS_POOL_MINT_LOCKED");
        (uint _reserve0, uint _reserve1) = (reserve0, reserve1);
        uint _balance0 = IERC20(token0).balanceOf(address(this));
        uint _balance1 = IERC20(token1).balanceOf(address(this));
        uint _amount0 = _balance0 - _reserve0;
        uint _amount1 = _balance1 - _reserve1;

        uint _totalSupply = totalSupply; // gas savings, must be defined here since totalSupply can update in _mintFee
        if (_totalSupply == 0) {
            liquidity = Math.sqrt(_amount0 * _amount1) - MINIMUM_LIQUIDITY;
            _mint(address(0), MINIMUM_LIQUIDITY); // permanently lock the first MINIMUM_LIQUIDITY tokens
            if (stable) {
                require(_k(_amount0, _amount1) > MINIMUM_K, "MINIMUM_K");
            }
        } else {
            liquidity = Math.min(_amount0 * _totalSupply / _reserve0, _amount1 * _totalSupply / _reserve1);
        }
        require(liquidity > 0, 'ILM'); // Pair: INSUFFICIENT_LIQUIDITY_MINTED
        _mint(to, liquidity);

        _update(_balance0, _balance1, _reserve0, _reserve1);
        emit Mint(msg.sender, _amount0, _amount1);
    }

    // this low-level function should be called from a contract which performs important safety checks
    // standard uniswap v2 implementation
    function burn(address to) external lock returns (uint amount0, uint amount1) {
        (uint _reserve0, uint _reserve1) = (reserve0, reserve1);
        (address _token0, address _token1) = (token0, token1);
        uint _balance0 = IERC20(_token0).balanceOf(address(this));
        uint _balance1 = IERC20(_token1).balanceOf(address(this));
        uint _liquidity = balanceOf[address(this)];

        uint _totalSupply = totalSupply; // gas savings, must be defined here since totalSupply can update in _mintFee
        amount0 = _liquidity * _balance0 / _totalSupply; // using balances ensures pro-rata distribution
        amount1 = _liquidity * _balance1 / _totalSupply; // using balances ensures pro-rata distribution
        require(amount0 > 0 && amount1 > 0, 'ILB'); // Pair: INSUFFICIENT_LIQUIDITY_BURNED
        _burn(address(this), _liquidity);
        _safeTransfer(_token0, to, amount0);
        _safeTransfer(_token1, to, amount1);
        _balance0 = IERC20(_token0).balanceOf(address(this));
        _balance1 = IERC20(_token1).balanceOf(address(this));

        _update(_balance0, _balance1, _reserve0, _reserve1);
        emit Burn(msg.sender, amount0, amount1, to);
    }

    // this low-level function should be called from a contract which performs important safety checks
    function swap(uint amount0Out, uint amount1Out, address to, bytes calldata data) external lock {
        require(!PairFactory(factory).isPaused(), "PAUSED");
        require(amount0Out > 0 || amount1Out > 0, 'IOA'); // Pair: INSUFFICIENT_OUTPUT_AMOUNT
        (uint _reserve0, uint _reserve1) =  (reserve0, reserve1);
        require(amount0Out < _reserve0 && amount1Out < _reserve1, 'IL'); // Pair: INSUFFICIENT_LIQUIDITY

        uint _balance0;
        uint _balance1;
        { // scope for _token{0,1}, avoids stack too deep errors
        (address _token0, address _token1) = (token0, token1);
        require(to != _token0 && to != _token1, 'IT'); // Pair: INVALID_TO
        if (amount0Out > 0) _safeTransfer(_token0, to, amount0Out); // optimistically transfer tokens
        if (amount1Out > 0) _safeTransfer(_token1, to, amount1Out); // optimistically transfer tokens
        if (data.length > 0) IPairCallee(to).hook(msg.sender, amount0Out, amount1Out, data); // callback, used for flash loans
        _balance0 = IERC20(_token0).balanceOf(address(this));
        _balance1 = IERC20(_token1).balanceOf(address(this));
        }

        uint amount0In = _balance0 > _reserve0 - amount0Out ? _balance0 - (_reserve0 - amount0Out) : 0;
        uint amount1In = _balance1 > _reserve1 - amount1Out ? _balance1 - (_reserve1 - amount1Out) : 0;
        require(amount0In > 0 || amount1In > 0, 'IIA'); // Pair: INSUFFICIENT_INPUT_AMOUNT

        { // scope for reserve{0,1}Adjusted, avoids stack too deep errors
        (address _token0, address _token1) = (token0, token1);
        if (amount0In > 0) _update0(amount0In * PairFactory(factory).getFee(address(this), stable) / 10000); // accrue fees for token0 and move them out of pool
        if (amount1In > 0) _update1(amount1In * PairFactory(factory).getFee(address(this), stable) / 10000); // accrue fees for token1 and move them out of pool
        _balance0 = IERC20(_token0).balanceOf(address(this)); // since we removed tokens, we need to reconfirm balances, can also simply use previous balance - amountIn/ 10000, but doing balanceOf again as safety check
        _balance1 = IERC20(_token1).balanceOf(address(this));
        // The curve, either x3y+y3x for stable pools, or x*y for volatile pools
        require(_k(_balance0, _balance1) >= _k(_reserve0, _reserve1), 'K'); // Pair: K
        }

        _update(_balance0, _balance1, _reserve0, _reserve1);
        emit Swap(msg.sender, amount0In, amount1In, amount0Out, amount1Out, to);
    }

    // force balances to match reserves
    function skim(address to) external lock {
        (address _token0, address _token1) = (token0, token1);
        _safeTransfer(_token0, to, IERC20(_token0).balanceOf(address(this)) - (reserve0));
        _safeTransfer(_token1, to, IERC20(_token1).balanceOf(address(this)) - (reserve1));
    }

    // force reserves to match balances
    function sync() external lock {
        _update(IERC20(token0).balanceOf(address(this)), IERC20(token1).balanceOf(address(this)), reserve0, reserve1);
    }

    function _f(uint x0, uint y) internal pure returns (uint) {
        return x0*(y*y/1e18*y/1e18)/1e18+(x0*x0/1e18*x0/1e18)*y/1e18;
    }

    function _d(uint x0, uint y) internal pure returns (uint) {
        return 3*x0*(y*y/1e18)/1e18+(x0*x0/1e18*x0/1e18);
    }

    function _get_y(uint x0, uint xy, uint y) internal pure returns (uint) {
        for (uint i = 0; i < 255; i++) {
            uint y_prev = y;
            uint k = _f(x0, y);
            if (k < xy) {
                uint dy = (xy - k)*1e18/_d(x0, y);
                y = y + dy;
            } else {
                uint dy = (k - xy)*1e18/_d(x0, y);
                y = y - dy;
            }
            if (y > y_prev) {
                if (y - y_prev <= 1) {
                    return y;
                }
            } else {
                if (y_prev - y <= 1) {
                    return y;
                }
            }
        }
        return y;
    }

    function getAmountOut(uint amountIn, address tokenIn) external view returns (uint) {
        (uint _reserve0, uint _reserve1) = (reserve0, reserve1);
        amountIn -= amountIn * PairFactory(factory).getFee(address(this), stable) / 10000; // remove fee from amount received
        return _getAmountOut(amountIn, tokenIn, _reserve0, _reserve1);
    }

    function _getAmountOut(uint amountIn, address tokenIn, uint _reserve0, uint _reserve1) internal view returns (uint) {
        if (stable) {
            uint xy =  _k(_reserve0, _reserve1);
            _reserve0 = _reserve0 * 1e18 / decimals0;
            _reserve1 = _reserve1 * 1e18 / decimals1;
            (uint reserveA, uint reserveB) = tokenIn == token0 ? (_reserve0, _reserve1) : (_reserve1, _reserve0);
            amountIn = tokenIn == token0 ? amountIn * 1e18 / decimals0 : amountIn * 1e18 / decimals1;
            uint y = reserveB - _get_y(amountIn+reserveA, xy, reserveB);
            return y * (tokenIn == token0 ? decimals1 : decimals0) / 1e18;
        } else {
            (uint reserveA, uint reserveB) = tokenIn == token0 ? (_reserve0, _reserve1) : (_reserve1, _reserve0);
            return amountIn * reserveB / (reserveA + amountIn);
        }
    }

    function _k(uint x, uint y) internal view returns (uint) {
        if (stable) {
            uint _x = x * 1e18 / decimals0;
            uint _y = y * 1e18 / decimals1;
            uint _a = (_x * _y) / 1e18;
            uint _b = ((_x * _x) / 1e18 + (_y * _y) / 1e18);
            return _a * _b / 1e18;  // x3y+y3x >= k
        } else {
            return x * y; // xy >= k
        }
    }

    function _mint(address dst, uint amount) internal {
        _updateFor(dst); // balances must be updated on mint/burn/transfer
        totalSupply += amount;
        balanceOf[dst] += amount;
        emit Transfer(address(0), dst, amount);
    }

    function _burn(address dst, uint amount) internal {
        _updateFor(dst);
        totalSupply -= amount;
        balanceOf[dst] -= amount;
        emit Transfer(dst, address(0), amount);
    }

    function approve(address spender, uint amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;

        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function permit(address owner, address spender, uint value, uint deadline, uint8 v, bytes32 r, bytes32 s) external {
        require(deadline >= block.timestamp, 'EXP');
        DOMAIN_SEPARATOR = keccak256(
            abi.encode(
                keccak256('EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)'),
                keccak256(bytes(name)),
                keccak256(bytes('1')),
                block.chainid,
                address(this)
            )
        );
        bytes32 digest = keccak256(
            abi.encodePacked(
                '\x19\x01',
                DOMAIN_SEPARATOR,
                keccak256(abi.encode(PERMIT_TYPEHASH, owner, spender, value, nonces[owner]++, deadline))
            )
        );
        address recoveredAddress = ecrecover(digest, v, r, s);
        require(recoveredAddress != address(0) && recoveredAddress == owner, 'ISIG');
        allowance[owner][spender] = value;

        emit Approval(owner, spender, value);
    }

    function transfer(address dst, uint amount) external returns (bool) {
        _transferTokens(msg.sender, dst, amount);
        return true;
    }

    function transferFrom(address src, address dst, uint amount) external returns (bool) {
        address spender = msg.sender;
        uint spenderAllowance = allowance[src][spender];

        if (spender != src && spenderAllowance != type(uint).max) {
            uint newAllowance = spenderAllowance - amount;
            allowance[src][spender] = newAllowance;

            emit Approval(src, spender, newAllowance);
        }

        _transferTokens(src, dst, amount);
        return true;
    }

    function _transferTokens(address src, address dst, uint amount) internal {
        _updateFor(src); // update fee position for src
        _updateFor(dst); // update fee position for dst

        balanceOf[src] -= amount;
        balanceOf[dst] += amount;

        emit Transfer(src, dst, amount);
    }

    function _safeTransfer(address token,address to,uint256 value) internal {
        require(token.code.length > 0, "CODELEN");
        (bool success, bytes memory data) = token.call(abi.encodeWithSelector(IERC20.transfer.selector, to, value));
        require(success && (data.length == 0 || abi.decode(data, (bool))), "IST");
    }

    function _safeApprove(address token,address spender,uint256 value) internal {
        require(token.code.length > 0, "CODELEN");
        require((value == 0) || (IERC20(token).allowance(address(this), spender) == 0),"INAP");
        (bool success, bytes memory data) = token.call(abi.encodeWithSelector(IERC20.approve.selector, spender, value));
        require(success && (data.length == 0 || abi.decode(data, (bool))), "ISA");
    }


}
