pragma solidity 0.8.13;

import './interfaces/ITokenHandler.sol';
import './interfaces/IPermissionsRegistry.sol';
import "@openzeppelin/contracts/access/Ownable.sol";

contract TokenHandler is  ITokenHandler, Ownable {

    mapping(address => bool) public isWhitelisted;             
    mapping(uint256 => bool) public isWhitelistedNFT;
    mapping(address => bool) public isConnector;
    mapping(address => uint256) public tokenVolatilityBucket; // Mapping of token to volatility bucket ID
    mapping(uint256 => string) public bucketType; // Mapping of token to volatility bucket ID

    address[] public whiteListed;
    address[] public connectors;

    address public permissionRegistry;
    uint256 public volatilityBucketCount;

    event SetPermissionRegistry(address indexed old, address indexed latest);
    event Whitelisted(address indexed whitelister, address indexed token);
    event Blacklisted(address indexed blacklister, address indexed token);
    event WhitelistedNFT(address indexed whitelister, uint256 tokenId);
    event BlacklistNFT(address indexed whitelister, uint256 tokenId);
    event WhitelistedConnector(address indexed whitelister, address indexed token);
    event BlacklistConnector(address indexed whitelister, address indexed token);
    event TokenVolatilityBucketUpdated(address indexed token, uint256 bucketId);

    modifier Governance() {
        require(IPermissionsRegistry(permissionRegistry).hasRole("GOVERNANCE",msg.sender), 'GOVERNANCE');
        _;
    }

    modifier GovernanceOrGenesisManager() {
        require(IPermissionsRegistry(permissionRegistry).hasRole("GENESIS_MANAGER", msg.sender) || IPermissionsRegistry(permissionRegistry).hasRole("GOVERNANCE",msg.sender), 'GOVERNANCE GENESIS_MANAGER');
        _;
    }

    constructor(address _permissionRegistry) {
        permissionRegistry = _permissionRegistry;
    }

    function setPermissionsRegistry(address _permissionRegistry) external onlyOwner {
        require(_permissionRegistry.code.length > 0, "!contract");
        require(_permissionRegistry != address(0), "addr0");
        emit SetPermissionRegistry(permissionRegistry, _permissionRegistry);
        permissionRegistry = _permissionRegistry;
    }

    /// @notice Whitelist a token for gauge creation
    function whitelistTokens(address[] memory _tokens) external GovernanceOrGenesisManager {
        uint256 i = 0;
        for(i = 0; i < _tokens.length; i++){
            _whitelist(_tokens[i]);
        }
    }

    function whitelistToken(address _token) external GovernanceOrGenesisManager {
        _whitelist(_token);
    }

    function _whitelist(address _token) private {
        require(!isWhitelisted[_token], "in");
        require(_token.code.length > 0, "!contract");
        isWhitelisted[_token] = true;
        whiteListed.push(_token);
        emit Whitelisted(msg.sender, _token);
    }

    /// @notice Blacklist a malicious token
    function blacklistTokens(address[] memory _token) external GovernanceOrGenesisManager {
        uint256 i = 0;
        for(i = 0; i < _token.length; i++){
            _blacklist(_token[i]);
        }
    }

    function blacklistToken(address _token) external GovernanceOrGenesisManager {
        _blacklist(_token);
    }

    function _blacklist(address _token) private {
        require(isWhitelisted[_token], "out");
        require(_token.code.length > 0, "!contract");
        isWhitelisted[_token] = false;

        uint256 length = whiteListed.length;
        uint256 i;
        for (i = 0; i < length; i++) {
            if (whiteListed[i] == _token) {
                whiteListed[i] = whiteListed[length - 1]; 
                whiteListed.pop(); 
                return;
            }
        }

        emit Blacklisted(msg.sender, _token);
    }

    function whitelistNFT(uint256 _tokenId) external Governance() {
        isWhitelistedNFT[_tokenId] = true;
        emit WhitelistedNFT(msg.sender, _tokenId);
    }

    function blacklistNFT(uint256 _tokenId) external Governance() {
        isWhitelistedNFT[_tokenId] = false;
        emit BlacklistNFT(msg.sender, _tokenId);
    }

    function whitelistConnectors(address[] memory _tokens) external Governance {
        uint256 i = 0;
        for(i = 0; i < _tokens.length; i++){
            _whitelistConnector(_tokens[i]);
        }
    }

    function whitelistConnector(address _token) external Governance() {
        _whitelistConnector(_token);
    }

    function _whitelistConnector(address _token) internal {
        require(isWhitelisted[_token], "out");
        require(!isConnector[_token], "connector");
        require(_token.code.length > 0, "!contract");
        isConnector[_token] = true;
        connectors.push(_token);
        emit WhitelistedConnector(msg.sender, _token);
    }

    function blacklistConnector(address _token) external Governance() {
        require(isWhitelisted[_token], "out");
        require(isConnector[_token], "not connector");
        require(_token.code.length > 0, "!contract");
        isConnector[_token] = false;

        uint256 length = connectors.length;
        uint256 i;
        for (i = 0; i < length; i++) {
            if (connectors[i] == _token) {
                connectors[i] = connectors[length - 1]; 
                connectors.pop(); 
                return;
            }
        }

        emit BlacklistConnector(msg.sender, _token);
    }

    function setBucketType(uint256 bucketId, string calldata bucketName) external Governance {
        require(bucketId <= volatilityBucketCount + 1);
        if(bucketId == volatilityBucketCount + 1) volatilityBucketCount++;
        bucketType[bucketId] = bucketName;
    }

    function getBucketType(uint256 bucketId) external view returns (string memory) {
        require(bucketId <= volatilityBucketCount);
        return bucketType[bucketId]; // Retrieve bucket type by ID
    }

    function updateTokenVolatilityBucket(address _token, uint256 bucketId) external Governance {
        require(isWhitelisted[_token], "!whitelisted");
        tokenVolatilityBucket[_token] = bucketId; // Update the token's volatility bucket
        emit TokenVolatilityBucketUpdated(_token, bucketId);
    }

    function getTokenVolatilityBucket(address _token) external view returns (uint256) {
        require(isWhitelisted[_token], "!whitelisted");
        return tokenVolatilityBucket[_token];
    }

    function whiteListedTokensLength() external view returns(uint256) {
        return whiteListed.length;
    }

    function connectorTokensLength() external view returns(uint256) {
        return connectors.length;
    }

    function whiteListedTokens() external view returns(address[] memory tokens) {
        return whiteListed;
    }

    function connectorTokens() external view returns(address[] memory tokens) {
        return connectors;
    }

}
"},"contracts/VeArtProxyUpgradeable.sol":{"content":"// SPDX-License-Identifier: MIT OR GPL-3.0-or-later
pragma solidity 0.8.13;

import {Base64} from "./libraries/Base64.sol";
import {IVeArtProxy} from "./interfaces/IVeArtProxy.sol";

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";

contract VeArtProxyUpgradeable is IVeArtProxy, OwnableUpgradeable {


    constructor() {}

    function initialize() initializer public {
        __Ownable_init();
    }


    function toString(uint value) internal pure returns (string memory) {
        // Inspired by OraclizeAPI's implementation - MIT license
        // https://github.com/oraclize/ethereum-api/blob/b42146b063c7d6ee1358846c198246239e9360e8/oraclizeAPI_0.4.25.sol

        if (value == 0) {
            return "0";
        }
        uint temp = value;
        uint digits;
        while (temp != 0) {
            digits++;
            temp /= 10;
        }
        bytes memory buffer = new bytes(digits);
        while (value != 0) {
            digits -= 1;
            buffer[digits] = bytes1(uint8(48 + uint(value % 10)));
            value /= 10;
        }
        return string(buffer);
    }

    function _tokenURI(uint _tokenId, uint _balanceOf, uint _locked_end, uint _value, bool isSMNFT) external pure returns (string memory output) {
        output = '<svg xmlns="http://www.w3.org/2000/svg" preserveAspectRatio="xMinYMin meet" viewBox="0 0 350 350"><style>.base { fill: white; font-family: serif; font-size: 14px; }</style><rect width="100%" height="100%" fill="black" /><text x="10" y="20" class="base">';
        output = string(abi.encodePacked(output, "token ", toString(_tokenId), '</text><text x="10" y="40" class="base">'));
        output = string(abi.encodePacked(output, "balanceOf ", toString(_balanceOf), '</text><text x="10" y="60" class="base">'));
        output = string(abi.encodePacked(output, "locked_end ", toString(_locked_end), '</text><text x="10" y="80" class="base">'));
        output = string(abi.encodePacked(output, "isSMNFT ", isSMNFT?"true":"false", '</text><text x="10" y="100" class="base">'));
        output = string(abi.encodePacked(output, "value ", toString(_value), '</text></svg>'));

        string memory json = Base64.encode(bytes(string(abi.encodePacked('{"name": "lock #', toString(_tokenId), '", "description": "Black locks, can be used to boost gauge yields, vote on token emission, and receive bribes", "image": "data:image/svg+xml;base64,', Base64.encode(bytes(output)), '"}'))));
        output = string(abi.encodePacked('data:application/json;base64,', json));
    }
}

"},"contracts/VoterV3.sol":{"content":"// SPDX-License-Identifier: MIT OR GPL-3.0-or-later
pragma solidity ^0.8.13;

import './libraries/Math.sol';
import './interfaces/IBribe.sol';
import './interfaces/IERC20.sol';
import './interfaces/IPairInfo.sol';
import './interfaces/IPairFactory.sol';
import './interfaces/IVotingEscrow.sol';
import './interfaces/IGaugeManager.sol';
import './interfaces/IPermissionsRegistry.sol';
import "./AVM/interfaces/IAutoVotingEscrowManager.sol";
import './interfaces/ITokenHandler.sol';
import {BlackTimeLibrary} from "./libraries/BlackTimeLibrary.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC20/utils/SafeERC20Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC20/IERC20Upgradeable.sol";

contract VoterV3 is OwnableUpgradeable, ReentrancyGuardUpgradeable {
    using SafeERC20Upgradeable for IERC20Upgradeable;

    address public _ve;                                         // the ve token that governs these contracts
    address public avm;
    address internal base;                                      // $the token
    address public permissionRegistry;                          // registry to check accesses
    address[] public pools;                                     // all pools viable for incentives
    address public epochOwner;
    address public tokenHandler;                     
    uint256 public maxVotingNum;
    uint public EPOCH_DURATION;
    uint256 internal constant MIN_VOTING_NUM = 10;
    IGaugeManager public gaugeManager;

    mapping(uint256 => mapping(address => uint256)) public votes;  // nft      => pool     => votes
    mapping(uint256 => address[]) public poolVote;                 // nft      => pools

    mapping(address => uint256) public weights;
    uint256 public totalWeight;
    mapping(uint256 => uint256) public usedWeights;

    mapping(uint256 => uint256) public lastVoted;                     // nft      => timestamp of last vote (this is shifted to thursday of that epoc)
    mapping(uint256 => uint256) public lastVotedTimestamp;            // nft      => timestamp of last vote

    event Voted(address indexed voter, uint256 tokenId, uint256 weight);
    event Abstained(uint256 tokenId, uint256 weight);
    event SetPermissionRegistry(address indexed old, address indexed latest);

    constructor() {}

    // function initialize(address __ve, address _pairFactory, address  _gaugeFactory, address _bribes, address _tokenHandler) initializer public {
    function initialize(
        address __ve,
        address _tokenHandler,
        address _gaugeManager,
        address _permissionRegistry
    ) public initializer {
        __Ownable_init();
        __ReentrancyGuard_init();
        _ve = __ve;
        base = IVotingEscrow(__ve).token();
        avm = IVotingEscrow(__ve).avm();
        gaugeManager = IGaugeManager(_gaugeManager);
        permissionRegistry = _permissionRegistry;
        tokenHandler = _tokenHandler;
        maxVotingNum = 30;
        EPOCH_DURATION = BlackTimeLibrary.WEEK;
    }

    /* -----------------------------------------------------------------------------
    --------------------------------------------------------------------------------
    --------------------------------------------------------------------------------
                                    MODIFIERS
    --------------------------------------------------------------------------------
    --------------------------------------------------------------------------------
    ----------------------------------------------------------------------------- */

    modifier VoterAdmin() {
        require(IPermissionsRegistry(permissionRegistry).hasRole("VOTER_ADMIN",msg.sender), 'VOTER_ADMIN');
        _;
    }

    modifier Governance() {
        require(IPermissionsRegistry(permissionRegistry).hasRole("GOVERNANCE",msg.sender), 'GOVERNANCE');
        _;
    }

    modifier GenesisManager() {
        require(IPermissionsRegistry(permissionRegistry).hasRole("GENESIS_MANAGER", msg.sender), 'GENESIS_MANAGER');
        _;
    }

    /* -----------------------------------------------------------------------------
    --------------------------------------------------------------------------------
    --------------------------------------------------------------------------------
                                    VoterAdmin
    --------------------------------------------------------------------------------
    --------------------------------------------------------------------------------
    ----------------------------------------------------------------------------- */

    function getAutomationRegistry() external view returns (address){
        return epochOwner;
    }

    function setEpochOwner(address _epochOwner) external onlyOwner {
        require(_epochOwner != address(0), "ZA");
        epochOwner = _epochOwner;
    }


    /// @notice Set a new PermissionRegistry
    function setPermissionsRegistry(address _permissionRegistry) external onlyOwner {
        require(_permissionRegistry.code.length > 0, "CODELEN");
        require(_permissionRegistry != address(0), "ZA");
        emit SetPermissionRegistry(permissionRegistry, _permissionRegistry);
        permissionRegistry = _permissionRegistry;
    }

    function setMaxVotingNum(uint256 _maxVotingNum) external VoterAdmin {
        require (_maxVotingNum >= MIN_VOTING_NUM, "LOW_VOTE");
        maxVotingNum = _maxVotingNum;
    }

    function setAVM() external VoterAdmin {
        avm = IVotingEscrow(_ve).avm();
    }

    /* -----------------------------------------------------------------------------
    --------------------------------------------------------------------------------
    --------------------------------------------------------------------------------
                                    USER INTERACTION
    --------------------------------------------------------------------------------
    --------------------------------------------------------------------------------
    ----------------------------------------------------------------------------- */


    /// @notice Reset the votes of a given TokenID
    function reset(uint256 _tokenId) external onlyNewEpoch(_tokenId) nonReentrant {
        require(IVotingEscrow(_ve).isApprovedOrOwner(msg.sender, _tokenId), "NAO");
        _reset(_tokenId);
        IVotingEscrow(_ve).abstain(_tokenId);
    }

    function _reset(uint256 _tokenId) internal {
        address[] storage _poolVote = poolVote[_tokenId];
        uint256 _poolVoteCnt = _poolVote.length;
        uint256 _totalWeight = 0;

        for (uint256 i = 0; i < _poolVoteCnt; i ++) {
            address _pool = _poolVote[i];
            uint256 _votes = votes[_tokenId][_pool];

            if (_votes != 0) {
                weights[_pool] -= _votes;

                votes[_tokenId][_pool] -= _votes;
                address internal_bribe = gaugeManager.fetchInternalBribeFromPool(_pool);
                address external_bribe = gaugeManager.fetchExternalBribeFromPool(_pool);
                IBribe(internal_bribe).withdraw(uint256(_votes), _tokenId);
                IBribe(external_bribe).withdraw(uint256(_votes), _tokenId);

                // decrease totalWeight irrespective of gauge is killed/alive for this current pool
                _totalWeight += _votes;

                emit Abstained(_tokenId, _votes);
            }
        }
        totalWeight -= _totalWeight;
        usedWeights[_tokenId] = 0;
        delete poolVote[_tokenId];
    }

    /// @notice Recast the saved votes of a given TokenID
    function poke(uint256 _tokenId) external nonReentrant {
        uint256 _timestamp = block.timestamp;
        if (_timestamp <= BlackTimeLibrary.epochVoteStart(_timestamp)){
            revert("DW");
        }
        require(IVotingEscrow(_ve).isApprovedOrOwner(msg.sender, _tokenId) || msg.sender == _ve, "NAO||VE");
        address[] memory _poolVote = poolVote[_tokenId];
        uint256 _poolCnt = _poolVote.length;
        uint256[] memory _weights = new uint256[](_poolCnt);

        for (uint256 i = 0; i < _poolCnt; i ++) {
            _weights[i] = votes[_tokenId][_poolVote[i]];
        } 

        _vote(_tokenId, _poolVote, _weights);
    }


    /// @notice Vote for pools
    /// @param  _tokenId    veNFT tokenID used to vote
    /// @param  _poolVote   array of LPs addresses to vote  (eg.: [sAMM usdc-usdt   , sAMM busd-usdt, vAMM wbnb-the ,...])
    /// @param  _weights    array of weights for each LPs   (eg.: [10               , 90            , 45             ,...])  
    function vote(uint256 _tokenId, address[] calldata _poolVote, uint256[] calldata _weights) 
        external onlyNewEpoch(_tokenId) nonReentrant {
        require(IVotingEscrow(_ve).isApprovedOrOwner(msg.sender, _tokenId), "NAO");
        require(_poolVote.length == _weights.length, "MISMATCH_LEN");
        require(_poolVote.length <= maxVotingNum, "EXCEEDS");
        uint256 _timestamp = block.timestamp;
        if ((_timestamp >= BlackTimeLibrary.epochVoteEnd(_timestamp)) && !ITokenHandler(tokenHandler).isWhitelistedNFT(_tokenId) && (IAutoVotingEscrowManager(avm).tokenIdToAVMId(_tokenId)) == (0)){
            revert("AVM_W");
        }
        _vote(_tokenId, _poolVote, _weights);
        lastVoted[_tokenId] = BlackTimeLibrary.epochStart(block.timestamp) + 1;
        lastVotedTimestamp[_tokenId] = block.timestamp;
    }

    function _vote(uint256 _tokenId, address[] memory _poolVote, uint256[] memory _weights) internal {
        _reset(_tokenId);
        uint256 _poolCnt = _poolVote.length;
        uint256 _weight = IVotingEscrow(_ve).balanceOfNFT(_tokenId);
        uint256 _totalVoteWeight = 0;
        uint256 _usedWeight = 0;

        for (uint i = 0; i < _poolCnt; i++) {

            if(gaugeManager.isGaugeAliveForPool(_poolVote[i])) _totalVoteWeight += _weights[i];
        }

        for (uint256 i = 0; i < _poolCnt; i++) {
            address _pool = _poolVote[i];

            if (gaugeManager.isGaugeAliveForPool(_pool)) {
                uint256 _poolWeight = _weights[i] * _weight / _totalVoteWeight;

                require(votes[_tokenId][_pool] == 0, "ZV");
                require(_poolWeight != 0, "ZV");

                poolVote[_tokenId].push(_pool);
                weights[_pool] += _poolWeight;

                votes[_tokenId][_pool] = _poolWeight;
                address internal_bribe = gaugeManager.fetchInternalBribeFromPool(_pool);
                address external_bribe = gaugeManager.fetchExternalBribeFromPool(_pool);

                IBribe(internal_bribe).deposit(uint256(_poolWeight), _tokenId);
                IBribe(external_bribe).deposit(uint256(_poolWeight), _tokenId);

                _usedWeight += _poolWeight;
                emit Voted(msg.sender, _tokenId, _poolWeight);
            }
        }
        if (_usedWeight > 0) IVotingEscrow(_ve).voting(_tokenId);
        totalWeight += _usedWeight;
        usedWeights[_tokenId] = _usedWeight;
    }


    modifier onlyNewEpoch(uint256 _tokenId) {
        // ensure new epoch since last vote
        if (BlackTimeLibrary.epochStart(block.timestamp) <= lastVoted[_tokenId]) revert("VOTED");
        if (block.timestamp <= BlackTimeLibrary.epochVoteStart(block.timestamp)) revert("DW");
        _;
    }

    /* -----------------------------------------------------------------------------
    --------------------------------------------------------------------------------
    --------------------------------------------------------------------------------
                                    VIEW FUNCTIONS
    --------------------------------------------------------------------------------
    --------------------------------------------------------------------------------
    ----------------------------------------------------------------------------- */

    /// @notice view the total length of the pools
    function length() external view returns (uint256) {
        return pools.length;
    }

    /// @notice view the total length of the voted pools given a tokenId
    function poolVoteLength(uint256 tokenId) external view returns(uint256) { 
        return poolVote[tokenId].length;
    }

    function setGaugeManager(address _gaugeManager) external VoterAdmin {
        require(_gaugeManager != address(0));
        gaugeManager = IGaugeManager(_gaugeManager);
    }

}
"},"contracts/VotingEscrow.sol":{"content":"// SPDX-License-Identifier: MIT OR GPL-3.0-or-later
pragma solidity 0.8.13;

import {IERC721, IERC721Metadata} from "@openzeppelin/contracts/token/ERC721/extensions/IERC721Metadata.sol";
import {IERC721Receiver} from "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";
import {IERC20} from "./interfaces/IERC20.sol";
import "./interfaces/IBlack.sol";
import {IBlackHoleVotes} from "./interfaces/IBlackHoleVotes.sol";
import {IVeArtProxy} from "./interfaces/IVeArtProxy.sol";
import {IVotingEscrow} from "./interfaces/IVotingEscrow.sol";
import {IVoter} from "./interfaces/IVoter.sol";
import {IAutomatedVotingManager} from "./interfaces/IAutomatedVotingManager.sol";
import {BlackTimeLibrary} from "./libraries/BlackTimeLibrary.sol";
import {VotingDelegationLib} from "./libraries/VotingDelegationLib.sol";
import {VotingBalanceLogic} from "./libraries/VotingBalanceLogic.sol";

/// @title Voting Escrow
/// @notice veNFT implementation that escrows ERC-20 tokens in the form of an ERC-721 NFT
/// @notice Votes have a weight depending on time, so that users are committed to the future of (whatever they are voting for)
/// @author Modified from Solidly (https://github.com/solidlyexchange/solidly/blob/master/contracts/ve.sol)
/// @author Modified from Curve (https://github.com/curvefi/curve-dao-contracts/blob/master/contracts/VotingEscrow.vy)
/// @author Modified from Nouns DAO (https://github.com/withtally/my-nft-dao-project/blob/main/contracts/ERC721Checkpointable.sol)
/// @dev Vote weight decays linearly over time. Lock time cannot be more than `MAXTIME` (2 years).
contract VotingEscrow is IERC721, IERC721Metadata, IBlackHoleVotes {
    enum DepositType {
        DEPOSIT_FOR_TYPE,
        CREATE_LOCK_TYPE,
        INCREASE_LOCK_AMOUNT,
        INCREASE_UNLOCK_TIME
    }

    /*//////////////////////////////////////////////////////////////
                                 EVENTS
    //////////////////////////////////////////////////////////////*/

    event Deposit(
        address indexed provider,
        uint tokenId,
        uint value,
        uint indexed locktime,
        DepositType deposit_type,
        uint ts
    );

    event Merge(
        address indexed _sender,
        uint256 indexed _from,
        uint256 indexed _to,
        uint256 _amountFrom,
        uint256 _amountTo,
        uint256 _amountFinal,
        uint256 _locktime,
        uint256 _ts
    );
    event Split(
        uint256 indexed _from,
        uint256 indexed _tokenId1,
